 else stadistinct = 0.0 ;
 }
 if ( vardata -> isunique ) stadistinct = - 1.0 * ( 1.0 - stanullfrac ) ;
 if ( stadistinct > 0.0 ) return clamp_row_est ( stadistinct ) ;
 if ( vardata -> rel == NULL ) {
 * isdefault = true ;
