 return - 1 ;
 }
 if ( level == DC_MAX ) {
 level = get_bits ( & s -> gb , 8 ) ;
 if ( get_bits1 ( & s -> gb ) ) level = - level ;
 }
 else if ( level != 0 ) {
 if ( get_bits1 ( & s -> gb ) ) level = - level ;
 }
 }
 if ( s -> msmpeg4_version == 1 ) {
 int32_t * dc_val ;
 pred = msmpeg4v1_pred_dc ( s , n , & dc_val ) ;
 level += pred ;
 * dc_val = level ;
