 level += pred ;
 if ( n < 4 ) {
 * dc_val = level * s -> y_dc_scale ;
 }
 else {
 * dc_val = level * s -> c_dc_scale ;
 }
 }
 return level ;
 }

static void reorder_block ( MPADecodeContext * s , GranuleDef * g ) {
