 else ptr = g -> sb_hybrid + 72 ;
 }
 else {
 ptr = g -> sb_hybrid ;
 }
 for ( i = g -> short_start ;
 i < 13 ;
 i ++ ) {
 len = band_size_short [ s -> sample_rate_index ] [ i ] ;
 ptr1 = ptr ;
 dst = tmp ;
 for ( j = len ;
 j > 0 ;
 j -- ) {
 * dst ++ = ptr [ 0 * len ] ;
 * dst ++ = ptr [ 1 * len ] ;
 * dst ++ = ptr [ 2 * len ] ;
