 trace_ps2_write_mouse ( opaque , val ) ;
 # ifdef DEBUG_MOUSE printf ( "kbd: write mouse 0x%02x\n" , val ) ;
 # endif switch ( s -> common . write_cmd ) {
 default : case - 1 : if ( s -> mouse_wrap ) {
 if ( val == AUX_RESET_WRAP ) {
 s -> mouse_wrap = 0 ;
