 case AUX_SET_WRAP : s -> mouse_wrap = 1 ;
 ps2_queue ( & s -> common , AUX_ACK ) ;
 break ;
 case AUX_SET_REMOTE : s -> mouse_status |= MOUSE_STATUS_REMOTE ;
 ps2_queue ( & s -> common , AUX_ACK ) ;
 break ;
 case AUX_GET_TYPE : ps2_queue ( & s -> common , AUX_ACK ) ;
