 else {
 first = 0 ;
 last = - 1 ;
 }
 rprintf ( FERROR , "File-list index %d not in %d - %d (%s) [%s]\n" , ndx , first , last , fatal_error_loc , who_am_i ( ) ) ;
 exit_cleanup ( RERR_PROTOCOL ) ;
 }
 return NULL ;
 }

