static gboolean test_dir_is_parent ( GFile * child , GFile * root ) {
 GFile * f , * tmp ;
 f = g_file_dup ( child ) ;
 while ( f ) {
 if ( g_file_equal ( f , root ) ) {
 g_object_unref ( f ) ;
