 if ( req_nr_streams > dev_max_streams ) {
 req_nr_streams = dev_max_streams ;
 }
 r = usb_device_alloc_streams ( eps [ 0 ] -> dev , eps , nr_eps , req_nr_streams ) ;
 if ( r != 0 ) {
