bool DropReplicationSlot ( PGconn * conn , const char * slot_name ) {
 PQExpBuffer query ;
 PGresult * res ;
 Assert ( slot_name != NULL ) ;
 query = createPQExpBuffer ( ) ;
 appendPQExpBuffer ( query , "DROP_REPLICATION_SLOT \"%s\"" , slot_name ) ;
