 if ( PQresultStatus ( res ) != PGRES_COMMAND_OK ) {
 fprintf ( stderr , _ ( "%s: could not send replication command \"%s\": %s" ) , progname , query -> data , PQerrorMessage ( conn ) ) ;
 destroyPQExpBuffer ( query ) ;
 PQclear ( res ) ;
 return false ;
 }
 if ( PQntuples ( res ) != 0 || PQnfields ( res ) != 0 ) {
