 case IMGTYPE_YUV422 : for ( row = 0 ;
 row < height ;
 row ++ ) {
 pixel_ptr = row * width * 2 ;
 yq = uq = vq = 0 ;
 for ( col = 0 ;
 col < width / 4 ;
