 if ( decision == FILTER_BLOCK ) {
 unsigned char * mc_running_avg_y = denoiser -> yv12_mc_running_avg . y_buffer + recon_yoffset ;
 int mc_avg_y_stride = denoiser -> yv12_mc_running_avg . y_stride ;
