 tmin = tmax = values [ i ] ;
 tmin_is_mcv = tmax_is_mcv = have_data = true ;
 continue ;
 }
 if ( DatumGetBool ( FunctionCall2Coll ( & opproc , DEFAULT_COLLATION_OID , values [ i ] , tmin ) ) ) {
 tmin = values [ i ] ;
 tmin_is_mcv = true ;
 }
 if ( DatumGetBool ( FunctionCall2Coll ( & opproc , DEFAULT_COLLATION_OID , tmax , values [ i ] ) ) ) {
 tmax = values [ i ] ;
