 }
 if ( j > cmapseg [ i ] . end ) cmapseg [ i ] . delta = delta ;
 else {
 cmapseg [ i ] . rangeoff = ( rpos + ( segcnt - i ) ) * sizeof ( int16 ) ;
 for ( j = cmapseg [ i ] . start ;
 j <= cmapseg [ i ] . end ;
 ++ j ) {
