 c -> pic . pict_type = ( frame_type == INTRA_FRAME ) ? AV_PICTURE_TYPE_I : AV_PICTURE_TYPE_P ;
 if ( frame_type == SKIP_FRAME ) {
 * got_frame = 1 ;
 * ( AVFrame * ) data = c -> pic ;
