static int calculate_bitrate ( AVFormatContext * s ) {
 AVIContext * avi = s -> priv_data ;
 int i , j ;
 int64_t lensum = 0 ;
 int64_t maxpos = 0 ;
 for ( i = 0 ;
 i < s -> nb_streams ;
 i ++ ) {
 int64_t len = 0 ;
 AVStream * st = s -> streams [ i ] ;
 if ( ! st -> nb_index_entries ) continue ;
 for ( j = 0 ;
 j < st -> nb_index_entries ;
 j ++ ) len += st -> index_entries [ j ] . size ;
 maxpos = FFMAX ( maxpos , st -> index_entries [ j - 1 ] . pos ) ;
 lensum += len ;
 }
 if ( maxpos < avi -> io_fsize * 9 / 10 ) return 0 ;
 if ( lensum * 9 / 10 > maxpos || lensum < maxpos * 9 / 10 ) return 0 ;
 for ( i = 0 ;
 i < s -> nb_streams ;
 i ++ ) {
 int64_t len = 0 ;
 AVStream * st = s -> streams [ i ] ;
 int64_t duration ;
 int64_t bitrate ;
 for ( j = 0 ;
 j < st -> nb_index_entries ;
 j ++ ) len += st -> index_entries [ j ] . size ;
 if ( st -> nb_index_entries < 2 || st -> codecpar -> bit_rate > 0 ) continue ;
 duration = st -> index_entries [ j - 1 ] . timestamp - st -> index_entries [ 0 ] . timestamp ;
 bitrate = av_rescale ( 8 * len , st -> time_base . den , duration * st -> time_base . num ) ;
 if ( bitrate <= INT_MAX && bitrate > 0 ) {
 st -> codecpar -> bit_rate = bitrate ;
 }
 }
 return 1 ;
 }

