 if ( S_ISGITLINK ( entry . mode ) ) continue ;
 cmp = tree_entry_len ( & entry ) != cmplen ? 1 : memcmp ( name , entry . path , cmplen ) ;
 if ( cmp > 0 ) continue ;
 if ( cmp < 0 ) return ;
 if ( name [ cmplen ] != '/' ) {
