static void translation_buf_decode ( struct message_decoder_context * ctx , const unsigned char * * data , size_t * size ) {
 unsigned char trans_buf [ CHARSET_MAX_PENDING_BUF_SIZE + 1 ] ;
 size_t data_wanted , skip ;
 size_t trans_size , orig_size ;
 memcpy ( trans_buf , ctx -> translation_buf , ctx -> translation_size ) ;
 data_wanted = sizeof ( trans_buf ) - ctx -> translation_size ;
 if ( data_wanted > * size ) data_wanted = * size ;
 memcpy ( trans_buf + ctx -> translation_size , * data , data_wanted ) ;
 orig_size = trans_size = ctx -> translation_size + data_wanted ;
 ( void ) charset_to_utf8 ( ctx -> charset_trans , trans_buf , & trans_size , ctx -> buf2 ) ;
 if ( trans_size <= ctx -> translation_size ) {
 i_assert ( orig_size < CHARSET_MAX_PENDING_BUF_SIZE ) ;
 memcpy ( ctx -> translation_buf , trans_buf , orig_size ) ;
 ctx -> translation_size = orig_size ;
 * data += * size ;
 * size = 0 ;
 return ;
 }
 skip = trans_size - ctx -> translation_size ;
 i_assert ( * size >= skip ) ;
 * data += skip ;
 * size -= skip ;
 ctx -> translation_size = 0 ;
 }

int ff_MPV_common_frame_size_change ( MpegEncContext * s ) {
 int i , err = 0 ;
 if ( s -> slice_context_count > 1 ) {
 for ( i = 0 ;
 i < s -> slice_context_count ;
 i ++ ) {
 free_duplicate_context ( s -> thread_context [ i ] ) ;
 }
 for ( i = 1 ;
 i < s -> slice_context_count ;
 i ++ ) {
 av_freep ( & s -> thread_context [ i ] ) ;
 }
 }
 else free_duplicate_context ( s ) ;
 if ( ( err = free_context_frame ( s ) ) < 0 ) return err ;
 if ( s -> picture ) for ( i = 0 ;
 i < MAX_PICTURE_COUNT ;
 i ++ ) {
 s -> picture [ i ] . needs_realloc = 1 ;
 }
 s -> last_picture_ptr = s -> next_picture_ptr = s -> current_picture_ptr = NULL ;
 if ( s -> codec_id == AV_CODEC_ID_MPEG2VIDEO && ! s -> progressive_sequence ) s -> mb_height = ( s -> height + 31 ) / 32 * 2 ;
 else if ( s -> codec_id != AV_CODEC_ID_H264 ) s -> mb_height = ( s -> height + 15 ) / 16 ;
 if ( ( s -> width || s -> height ) && av_image_check_size ( s -> width , s -> height , 0 , s -> avctx ) ) return AVERROR_INVALIDDATA ;
 if ( ( err = init_context_frame ( s ) ) ) goto fail ;
 s -> thread_context [ 0 ] = s ;
 if ( s -> width && s -> height ) {
 int nb_slices = s -> slice_context_count ;
 if ( nb_slices > 1 ) {
 for ( i = 1 ;
 i < nb_slices ;
 i ++ ) {
 s -> thread_context [ i ] = av_malloc ( sizeof ( MpegEncContext ) ) ;
 memcpy ( s -> thread_context [ i ] , s , sizeof ( MpegEncContext ) ) ;
 }
 for ( i = 0 ;
 i < nb_slices ;
 i ++ ) {
 if ( init_duplicate_context ( s -> thread_context [ i ] ) < 0 ) goto fail ;
 s -> thread_context [ i ] -> start_mb_y = ( s -> mb_height * ( i ) + nb_slices / 2 ) / nb_slices ;
 s -> thread_context [ i ] -> end_mb_y = ( s -> mb_height * ( i + 1 ) + nb_slices / 2 ) / nb_slices ;
 }
 }
 else {
 if ( init_duplicate_context ( s ) < 0 ) goto fail ;
 s -> start_mb_y = 0 ;
 s -> end_mb_y = s -> mb_height ;
 }
 s -> slice_context_count = nb_slices ;
 }
 return 0 ;
 fail : ff_MPV_common_end ( s ) ;
 return err ;
 }

