void safe_connect ( MYSQL * mysql , const char * name , const char * host , const char * user , const char * pass , const char * db , int port , const char * sock ) {
 int failed_attempts = 0 ;
 DBUG_ENTER ( "safe_connect" ) ;
 verbose_msg ( "Connecting to server %s:%d (socket %s) as '%s'" ", connection '%s', attempt %d ..." , host , port , sock , user , name , failed_attempts ) ;
 while ( ! mysql_real_connect ( mysql , host , user , pass , db , port , sock , CLIENT_MULTI_STATEMENTS | CLIENT_REMEMBER_OPTIONS ) ) {
