 else die ( "Could not open connection '%s': %d %s" , name , mysql_errno ( mysql ) , mysql_error ( mysql ) ) ;
 }
 failed_attempts ++ ;
 }
 verbose_msg ( "... Connected." ) ;
 DBUG_VOID_RETURN ;
 }

