 sample += ( ( code >> 2 ) & 0x3 ) - 2 ;
 sample = av_clip_uint8 ( sample ) ;
 * samples ++ = sample ;
 sample += ( ( code >> 4 ) & 0x3 ) - 2 ;
 sample = av_clip_uint8 ( sample ) ;
 * samples ++ = sample ;
 sample += ( code >> 6 ) - 2 ;
