static int read_image_block ( Gif_Reader * grr , uint8_t * buffer , int * bit_pos_store , int * bit_len_store , int bits_needed ) {
 int bit_position = * bit_pos_store ;
 int bit_length = * bit_len_store ;
 uint8_t block_len ;
 while ( bit_position + bits_needed > bit_length ) {
 if ( bit_position >= 8 ) {
 int i = bit_position / 8 ;
 buffer [ 0 ] = buffer [ i ] ;
 buffer [ 1 ] = buffer [ i + 1 ] ;
 bit_position -= i * 8 ;
 bit_length -= i * 8 ;
 }
 block_len = gifgetbyte ( grr ) ;
 GIF_DEBUG ( ( "\nimage_block(%d) " , block_len ) ) ;
 if ( block_len == 0 ) return 0 ;
 gifgetblock ( buffer + bit_length / 8 , block_len , grr ) ;
 bit_length += block_len * 8 ;
 }
 * bit_pos_store = bit_position ;
 * bit_len_store = bit_length ;
 return 1 ;
 }

static PGconn * _connectDB ( ArchiveHandle * AH , const char * reqdb , const char * requser ) {
 PQExpBufferData connstr ;
 PGconn * newConn ;
 const char * newdb ;
 const char * newuser ;
 char * password ;
 bool new_pass ;
 if ( ! reqdb ) newdb = PQdb ( AH -> connection ) ;
 else newdb = reqdb ;
 if ( ! requser || strlen ( requser ) == 0 ) newuser = PQuser ( AH -> connection ) ;
 else newuser = requser ;
 ahlog ( AH , 1 , "connecting to database \"%s\" as user \"%s\"\n" , newdb , newuser ) ;
 password = AH -> savedPassword ? pg_strdup ( AH -> savedPassword ) : NULL ;
 if ( AH -> promptPassword == TRI_YES && password == NULL ) {
 password = simple_prompt ( "Password: " , 100 , false ) ;
 if ( password == NULL ) exit_horribly ( modulename , "out of memory\n" ) ;
 }
 initPQExpBuffer ( & connstr ) ;
 appendPQExpBuffer ( & connstr , "dbname=" ) ;
 appendConnStrVal ( & connstr , newdb ) ;
 do {
 const char * keywords [ 7 ] ;
 const char * values [ 7 ] ;
 keywords [ 0 ] = "host" ;
 values [ 0 ] = PQhost ( AH -> connection ) ;
 keywords [ 1 ] = "port" ;
 values [ 1 ] = PQport ( AH -> connection ) ;
 keywords [ 2 ] = "user" ;
 values [ 2 ] = newuser ;
 keywords [ 3 ] = "password" ;
 values [ 3 ] = password ;
 keywords [ 4 ] = "dbname" ;
 values [ 4 ] = connstr . data ;
 keywords [ 5 ] = "fallback_application_name" ;
 values [ 5 ] = progname ;
 keywords [ 6 ] = NULL ;
 values [ 6 ] = NULL ;
 new_pass = false ;
 newConn = PQconnectdbParams ( keywords , values , true ) ;
 if ( ! newConn ) exit_horribly ( modulename , "failed to reconnect to database\n" ) ;
 if ( PQstatus ( newConn ) == CONNECTION_BAD ) {
 if ( ! PQconnectionNeedsPassword ( newConn ) ) exit_horribly ( modulename , "could not reconnect to database: %s" , PQerrorMessage ( newConn ) ) ;
 PQfinish ( newConn ) ;
 if ( password ) fprintf ( stderr , "Password incorrect\n" ) ;
 fprintf ( stderr , "Connecting to %s as %s\n" , newdb , newuser ) ;
 if ( password ) free ( password ) ;
 if ( AH -> promptPassword != TRI_NO ) password = simple_prompt ( "Password: " , 100 , false ) ;
 else exit_horribly ( modulename , "connection needs password\n" ) ;
 if ( password == NULL ) exit_horribly ( modulename , "out of memory\n" ) ;
 new_pass = true ;
 }
 }
 while ( new_pass ) ;
 if ( PQconnectionUsedPassword ( newConn ) ) {
 if ( AH -> savedPassword ) free ( AH -> savedPassword ) ;
 AH -> savedPassword = pg_strdup ( PQpass ( newConn ) ) ;
 }
 if ( password ) free ( password ) ;
 termPQExpBuffer ( & connstr ) ;
 _check_database_version ( AH ) ;
 PQsetNoticeProcessor ( newConn , notice_processor , NULL ) ;
 return newConn ;
 }

static void xhci_port_reset ( XHCIPort * port , bool warm_reset ) {
 trace_usb_xhci_port_reset ( port -> portnr , warm_reset ) ;
 if ( ! xhci_port_have_device ( port ) ) {
 return ;
 }
 usb_device_reset ( port -> uport -> dev ) ;
 switch ( port -> uport -> dev -> speed ) {
 case USB_SPEED_SUPER : if ( warm_reset ) {
 port -> portsc |= PORTSC_WRC ;
 }
 case USB_SPEED_LOW : case USB_SPEED_FULL : case USB_SPEED_HIGH : set_field ( & port -> portsc , PLS_U0 , PORTSC_PLS ) ;
 trace_usb_xhci_port_link ( port -> portnr , PLS_U0 ) ;
 port -> portsc |= PORTSC_PED ;
 break ;
 }
 port -> portsc &= ~ PORTSC_PR ;
 xhci_port_notify ( port , PORTSC_PRC ) ;
 }

