 * globbed = NULL ;
 if ( ! glob -> beenhere ) glob -> beenhere = 1 ;
 else {
 bool carry = TRUE ;
 for ( i = 0 ;
 carry && ( i < glob -> size ) ;
 i ++ ) {
 carry = FALSE ;
 pat = & glob -> pattern [ glob -> size - 1 - i ] ;
 switch ( pat -> type ) {
 case UPTSet : if ( ( pat -> content . Set . elements ) && ( ++ pat -> content . Set . ptr_s == pat -> content . Set . size ) ) {
