 s -> mb_x < s -> mb_width ;
 s -> mb_x ++ ) {
 ff_update_block_index ( s ) ;
 if ( v -> fcm == ILACE_FIELD ) vc1_decode_p_mb_intfi ( v ) ;
 else if ( v -> fcm == ILACE_FRAME ) vc1_decode_p_mb_intfr ( v ) ;
 else vc1_decode_p_mb ( v ) ;
