 debug2 ( "%s: disabled because of invalid user" , __func__ ) ;
 goto done ;
 }
 xasprintf ( & userstyle , "%s%s%s" , authctxt -> user , authctxt -> style ? ":" : "" , authctxt -> style ? authctxt -> style : "" ) ;
 if ( ( r = sshbuf_put_u8 ( b , SSH2_MSG_USERAUTH_REQUEST ) ) != 0 || ( r = sshbuf_put_cstring ( b , userstyle ) ) != 0 || ( r = sshbuf_put_cstring ( b , authctxt -> service ) ) != 0 || ( r = sshbuf_put_cstring ( b , "publickey" ) ) != 0 || ( r = sshbuf_put_u8 ( b , have_sig ) ) != 0 || ( r = sshbuf_put_cstring ( b , pkalg ) != 0 ) || ( r = sshbuf_put_string ( b , pkblob , blen ) ) != 0 ) fatal ( "%s: build packet failed: %s" , __func__ , ssh_err ( r ) ) ;
 # ifdef DEBUG_PK sshbuf_dump ( b , stderr ) ;
