 if ( ( n = matroska_ebmlnum_uint ( matroska , data , size , & num ) ) < 0 ) {
 av_log ( matroska -> ctx , AV_LOG_ERROR , "EBML block data error\n" ) ;
 return n ;
 }
 data += n ;
 size -= n ;
 track = matroska_find_track_by_num ( matroska , num ) ;
 if ( ! track || ! track -> stream ) {
 av_log ( matroska -> ctx , AV_LOG_INFO , "Invalid stream %" PRIu64 " or size %u\n" , num , size ) ;
 return AVERROR_INVALIDDATA ;
 }
 else if ( size <= 3 ) return 0 ;
 st = track -> stream ;
 if ( st -> discard >= AVDISCARD_ALL ) return res ;
 block_time = AV_RB16 ( data ) ;
 data += 2 ;
 flags = * data ++ ;
 size -= 3 ;
 if ( is_keyframe == - 1 ) is_keyframe = flags & 0x80 ? AV_PKT_FLAG_KEY : 0 ;
 if ( cluster_time != ( uint64_t ) - 1 && ( block_time >= 0 || cluster_time >= - block_time ) ) {
 timecode = cluster_time + block_time - track -> codec_delay ;
 if ( track -> type == MATROSKA_TRACK_TYPE_SUBTITLE && timecode < track -> end_timecode ) is_keyframe = 0 ;
 if ( is_keyframe ) av_add_index_entry ( st , cluster_pos , timecode , 0 , 0 , AVINDEX_KEYFRAME ) ;
 }
 if ( matroska -> skip_to_keyframe && track -> type != MATROSKA_TRACK_TYPE_SUBTITLE ) {
 if ( ! is_keyframe || timecode < matroska -> skip_to_timecode ) return res ;
 matroska -> skip_to_keyframe = 0 ;
 }
 res = matroska_parse_laces ( matroska , & data , & size , ( flags & 0x06 ) >> 1 , & lace_size , & laces ) ;
 if ( res ) goto end ;
 if ( block_duration != AV_NOPTS_VALUE ) {
 duration = block_duration / laces ;
 if ( block_duration != duration * laces ) {
 av_log ( matroska -> ctx , AV_LOG_WARNING , "Incorrect block_duration, possibly corrupted container" ) ;
 }
 }
 else {
 duration = track -> default_duration / matroska -> time_scale ;
 block_duration = duration * laces ;
 }
 if ( timecode != AV_NOPTS_VALUE ) track -> end_timecode = FFMAX ( track -> end_timecode , timecode + block_duration ) ;
