 n < laces ;
 n ++ ) {
 if ( ( st -> codec -> codec_id == AV_CODEC_ID_RA_288 || st -> codec -> codec_id == AV_CODEC_ID_COOK || st -> codec -> codec_id == AV_CODEC_ID_SIPR || st -> codec -> codec_id == AV_CODEC_ID_ATRAC3 ) && st -> codec -> block_align && track -> audio . sub_packet_size ) {
