 if ( res ) goto end ;
 }
 else {
 res = matroska_parse_frame ( matroska , track , st , data , lace_size [ n ] , timecode , duration , pos , ! n ? is_keyframe : 0 ) ;
 if ( res ) goto end ;
 }
 if ( timecode != AV_NOPTS_VALUE ) timecode = duration ? timecode + duration : AV_NOPTS_VALUE ;
 data += lace_size [ n ] ;
 }
 end : av_free ( lace_size ) ;
