 proto_item_append_text ( item , "%c" , ' ' ) ;
 type_start = * signature ;
 do {
 if ( type_start == * signature ) {
 depth ++ ;
 }
 if ( type_stop == * signature ) {
 depth -- ;
 }
 proto_item_append_text ( item , "%c" , * signature ++ ) ;
