 div = ( s -> avctx -> time_base . num * 1800000LL + 500LL * s -> avctx -> time_base . den ) / ( ( 1000LL + i ) * s -> avctx -> time_base . den ) ;
 div = av_clip ( div , 1 , 127 ) ;
