 put_sbits ( & s -> pb , 8 , temp_ref ) ;
 put_bits ( & s -> pb , 1 , 1 ) ;
 put_bits ( & s -> pb , 1 , 0 ) ;
 put_bits ( & s -> pb , 1 , 0 ) ;
 put_bits ( & s -> pb , 1 , 0 ) ;
