 break ;
 case 'h' : case 'l' : if ( s -> nb_args < 2 ) s -> args [ 0 ] = DEFAULT_SCREEN_MODE ;
 switch ( s -> args [ 0 ] ) {
 case 0 : case 1 : case 4 : case 5 : case 13 : case 19 : s -> font = ff_cga_font ;
 s -> font_height = 8 ;
