 height = 25 << 4 ;
 break ;
 case 6 : case 14 : s -> font = ff_cga_font ;
 s -> font_height = 8 ;
 width = 80 << 3 ;
 height = 25 << 3 ;
 break ;
 case 7 : break ;
 case 15 : case 16 : s -> font = ff_cga_font ;
 s -> font_height = 8 ;
 width = 80 << 3 ;
