 }
 if ( width != avctx -> width || height != avctx -> height ) {
 if ( s -> frame . data [ 0 ] ) avctx -> release_buffer ( avctx , & s -> frame ) ;
 avcodec_set_dimensions ( avctx , width , height ) ;
