 case 2 : erase_screen ( avctx ) ;
 }
 break ;
 case 'K' : switch ( s -> args [ 0 ] ) {
 case 0 : erase_line ( avctx , s -> x , avctx -> width - s -> x ) ;
 break ;
 case 1 : erase_line ( avctx , 0 , s -> x ) ;
 break ;
 case 2 : erase_line ( avctx , 0 , avctx -> width ) ;
 }
