 s -> nb_args = 1 ;
 s -> args [ 0 ] = 0 ;
 }
 for ( i = 0 ;
 i < FFMIN ( s -> nb_args , MAX_NB_ARGS ) ;
 i ++ ) {
 int m = s -> args [ i ] ;
 if ( m == 0 ) {
 s -> attributes = 0 ;
 s -> fg = DEFAULT_FG_COLOR ;
 s -> bg = DEFAULT_BG_COLOR ;
 }
 else if ( m == 1 || m == 2 || m == 4 || m == 5 || m == 7 || m == 8 ) {
