 salt [ 3 ] = ntp_random ( ) ;
 last_salt_update = current_time ;
 }
 EVP_DigestInit ( & ctx , EVP_get_digestbynid ( NID_md5 ) ) ;
 EVP_DigestUpdate ( & ctx , salt , sizeof ( salt ) ) ;
