 src += 16 ;
 Y1 = pic -> data [ 0 ] ;
 Y2 = pic -> data [ 0 ] + pic -> linesize [ 0 ] ;
 U = pic -> data [ 1 ] ;
 V = pic -> data [ 2 ] ;
 for ( h = 0 ;
 h < avctx -> height ;
 h += 2 ) {
 for ( w = 0 ;
 w < avctx -> width ;
 w += 2 ) {
 AV_COPY16 ( Y1 + w , src ) ;
 AV_COPY16 ( Y2 + w , src + 2 ) ;
 U [ w >> 1 ] = src [ 4 ] + 0x80 ;
 V [ w >> 1 ] = src [ 5 ] + 0x80 ;
 src += 6 ;
 }
 Y1 += pic -> linesize [ 0 ] << 1 ;
 Y2 += pic -> linesize [ 0 ] << 1 ;
 U += pic -> linesize [ 1 ] ;
 V += pic -> linesize [ 2 ] ;
 }
 * got_frame = 1 ;
 * ( AVFrame * ) data = * pic ;
 return avpkt -> size ;
 }

