 spin_lock ( & key_user_lock ) ;
 while ( * p ) {
 parent = * p ;
 user = rb_entry ( parent , struct key_user , node ) ;
 if ( uid_lt ( uid , user -> uid ) ) p = & ( * p ) -> rb_left ;
 else if ( uid_gt ( uid , user -> uid ) ) p = & ( * p ) -> rb_right ;
 else goto found ;
 }
 if ( ! candidate ) {
