 if ( ( c & ( 1 << 7 ) ) >> 7 == 0 ) {
 d_length = c ;
 d_ptr ++ ;
 }
 else {
 numbytes = c & 0x7f ;
 d_ptr ++ ;
 if ( DecodeAsn1BuildValue ( & d_ptr , & d_length , numbytes , errcode ) == - 1 ) {
 SCFree ( node ) ;
 return NULL ;
 }
 }
 node -> length = d_length + ( d_ptr - buffer ) ;
 if ( node -> length > max_size || node -> length < d_length ) {
 if ( errcode ) * errcode = ERR_DER_ELEMENT_SIZE_TOO_BIG ;
 SCFree ( node ) ;
