 }
 parsed_bytes = 0 ;
 seq_index = 0 ;
 while ( parsed_bytes < d_length ) {
 el_max_size = max_size - ( d_ptr - buffer ) ;
 Asn1Generic * child = DecodeAsn1DerGeneric ( d_ptr , el_max_size , depth , seq_index , errcode ) ;
 if ( child == NULL ) {
 if ( errcode && * errcode != 0 ) {
 DerFree ( node ) ;
 return NULL ;
 }
