 }
 int ret = Asn1SequenceAppend ( node , child ) ;
 if ( ret == - 1 ) {
 DerFree ( child ) ;
 break ;
 }
 parsed_bytes += child -> length ;
 d_ptr += child -> length ;
 seq_index ++ ;
 }
 return ( Asn1Generic * ) node ;
 }

