int main ( int argc , char * argv [ ] ) {
 static char buff [ 16384 ] ;
 struct cpio _cpio ;
 struct cpio * cpio ;
 const char * errmsg ;
 int uid , gid ;
 int opt ;
 cpio = & _cpio ;
 memset ( cpio , 0 , sizeof ( * cpio ) ) ;
 cpio -> buff = buff ;
 cpio -> buff_size = sizeof ( buff ) ;
 # if defined ( HAVE_SIGACTION ) && defined ( SIGPIPE ) {
 struct sigaction sa ;
 sigemptyset ( & sa . sa_mask ) ;
 sa . sa_flags = 0 ;
 sa . sa_handler = SIG_IGN ;
 sigaction ( SIGPIPE , & sa , NULL ) ;
 }
 # endif lafe_setprogname ( * argv , "bsdcpio" ) ;
 # if HAVE_SETLOCALE if ( setlocale ( LC_ALL , "" ) == NULL ) lafe_warnc ( 0 , "Failed to set default locale" ) ;
 # endif cpio -> uid_override = - 1 ;
 cpio -> gid_override = - 1 ;
 cpio -> argv = argv ;
 cpio -> argc = argc ;
 cpio -> mode = '\0' ;
 cpio -> verbose = 0 ;
 cpio -> compress = '\0' ;
 cpio -> extract_flags = ARCHIVE_EXTRACT_NO_AUTODIR ;
 cpio -> extract_flags |= ARCHIVE_EXTRACT_NO_OVERWRITE_NEWER ;
 cpio -> extract_flags |= ARCHIVE_EXTRACT_SECURE_SYMLINKS ;
 cpio -> extract_flags |= ARCHIVE_EXTRACT_SECURE_NODOTDOT ;
 cpio -> extract_flags |= ARCHIVE_EXTRACT_PERM ;
 cpio -> extract_flags |= ARCHIVE_EXTRACT_FFLAGS ;
 cpio -> extract_flags |= ARCHIVE_EXTRACT_ACL ;
 # if ! defined ( _WIN32 ) && ! defined ( __CYGWIN__ ) if ( geteuid ( ) == 0 ) cpio -> extract_flags |= ARCHIVE_EXTRACT_OWNER ;
 # endif cpio -> bytes_per_block = 512 ;
 cpio -> filename = NULL ;
 cpio -> matching = archive_match_new ( ) ;
 if ( cpio -> matching == NULL ) lafe_errc ( 1 , 0 , "Out of memory" ) ;
 while ( ( opt = cpio_getopt ( cpio ) ) != - 1 ) {
 switch ( opt ) {
 case '0' : cpio -> option_null = 1 ;
 break ;
 case 'A' : cpio -> option_append = 1 ;
 break ;
 case 'a' : cpio -> option_atime_restore = 1 ;
 break ;
 case 'B' : cpio -> bytes_per_block = 5120 ;
 break ;
 case OPTION_B64ENCODE : cpio -> add_filter = opt ;
 break ;
 case 'C' : cpio -> bytes_per_block = atoi ( cpio -> argument ) ;
 if ( cpio -> bytes_per_block <= 0 ) lafe_errc ( 1 , 0 , "Invalid blocksize %s" , cpio -> argument ) ;
 break ;
 case 'c' : cpio -> format = "odc" ;
 break ;
 case 'd' : cpio -> extract_flags &= ~ ARCHIVE_EXTRACT_NO_AUTODIR ;
 break ;
 case 'E' : if ( archive_match_include_pattern_from_file ( cpio -> matching , cpio -> argument , cpio -> option_null ) != ARCHIVE_OK ) lafe_errc ( 1 , 0 , "Error : %s" , archive_error_string ( cpio -> matching ) ) ;
 break ;
 case 'F' : cpio -> filename = cpio -> argument ;
 break ;
 case 'f' : if ( archive_match_exclude_pattern ( cpio -> matching , cpio -> argument ) != ARCHIVE_OK ) lafe_errc ( 1 , 0 , "Error : %s" , archive_error_string ( cpio -> matching ) ) ;
 break ;
 case OPTION_GRZIP : cpio -> compress = opt ;
 break ;
 case 'H' : cpio -> format = cpio -> argument ;
 break ;
 case 'h' : long_help ( ) ;
 break ;
 case 'I' : cpio -> filename = cpio -> argument ;
 break ;
 case 'i' : if ( cpio -> mode != '\0' ) lafe_errc ( 1 , 0 , "Cannot use both -i and -%c" , cpio -> mode ) ;
 cpio -> mode = opt ;
 break ;
 case 'J' : cpio -> compress = opt ;
 break ;
 case 'j' : cpio -> compress = opt ;
 break ;
 case OPTION_INSECURE : cpio -> extract_flags &= ~ ARCHIVE_EXTRACT_SECURE_SYMLINKS ;
 cpio -> extract_flags &= ~ ARCHIVE_EXTRACT_SECURE_NODOTDOT ;
 break ;
 case 'L' : cpio -> option_follow_links = 1 ;
 break ;
 case 'l' : cpio -> option_link = 1 ;
 break ;
 case OPTION_LRZIP : case OPTION_LZ4 : case OPTION_LZMA : case OPTION_LZOP : cpio -> compress = opt ;
 break ;
 case 'm' : cpio -> extract_flags |= ARCHIVE_EXTRACT_TIME ;
 break ;
 case 'n' : cpio -> option_numeric_uid_gid = 1 ;
 break ;
 case OPTION_NO_PRESERVE_OWNER : cpio -> extract_flags &= ~ ARCHIVE_EXTRACT_OWNER ;
 break ;
 case 'O' : cpio -> filename = cpio -> argument ;
 break ;
 case 'o' : if ( cpio -> mode != '\0' ) lafe_errc ( 1 , 0 , "Cannot use both -o and -%c" , cpio -> mode ) ;
 cpio -> mode = opt ;
 break ;
 case 'p' : if ( cpio -> mode != '\0' ) lafe_errc ( 1 , 0 , "Cannot use both -p and -%c" , cpio -> mode ) ;
 cpio -> mode = opt ;
 cpio -> extract_flags &= ~ ARCHIVE_EXTRACT_SECURE_NODOTDOT ;
 break ;
 case OPTION_PASSPHRASE : cpio -> passphrase = cpio -> argument ;
 break ;
 case OPTION_PRESERVE_OWNER : cpio -> extract_flags |= ARCHIVE_EXTRACT_OWNER ;
 break ;
 case OPTION_QUIET : cpio -> quiet = 1 ;
 break ;
 case 'R' : errmsg = owner_parse ( cpio -> argument , & uid , & gid ) ;
 if ( errmsg ) {
 lafe_warnc ( - 1 , "%s" , errmsg ) ;
 usage ( ) ;
 }
 if ( uid != - 1 ) {
 cpio -> uid_override = uid ;
 cpio -> uname_override = NULL ;
 }
 if ( gid != - 1 ) {
 cpio -> gid_override = gid ;
 cpio -> gname_override = NULL ;
 }
 break ;
 case 'r' : cpio -> option_rename = 1 ;
 break ;
 case 't' : cpio -> option_list = 1 ;
 break ;
 case 'u' : cpio -> extract_flags &= ~ ARCHIVE_EXTRACT_NO_OVERWRITE_NEWER ;
 break ;
 case OPTION_UUENCODE : cpio -> add_filter = opt ;
 break ;
 case 'v' : cpio -> verbose ++ ;
 break ;
 case 'V' : cpio -> dot ++ ;
 break ;
 case OPTION_VERSION : version ( ) ;
 break ;
 # if 0 case 'W' : break ;
 # endif case 'y' : cpio -> compress = opt ;
 break ;
 case 'Z' : cpio -> compress = opt ;
 break ;
 case 'z' : cpio -> compress = opt ;
 break ;
 default : usage ( ) ;
 }
 }
 if ( cpio -> option_list && cpio -> mode == '\0' ) cpio -> mode = 'i' ;
 if ( cpio -> option_list && cpio -> mode != 'i' ) lafe_errc ( 1 , 0 , "Option -t requires -i" ) ;
 if ( cpio -> option_numeric_uid_gid && ! cpio -> option_list ) lafe_errc ( 1 , 0 , "Option -n requires -it" ) ;
 if ( cpio -> format != NULL && cpio -> mode != 'o' ) lafe_errc ( 1 , 0 , "Option --format requires -o" ) ;
 if ( cpio -> option_link && cpio -> mode != 'p' ) lafe_errc ( 1 , 0 , "Option -l requires -p" ) ;
 if ( cpio -> dot && cpio -> verbose ) cpio -> dot = 0 ;
 switch ( cpio -> mode ) {
 case 'o' : if ( cpio -> format == NULL ) cpio -> format = "odc" ;
 mode_out ( cpio ) ;
 break ;
 case 'i' : while ( * cpio -> argv != NULL ) {
 if ( archive_match_include_pattern ( cpio -> matching , * cpio -> argv ) != ARCHIVE_OK ) lafe_errc ( 1 , 0 , "Error : %s" , archive_error_string ( cpio -> matching ) ) ;
 -- cpio -> argc ;
 ++ cpio -> argv ;
 }
 if ( cpio -> option_list ) mode_list ( cpio ) ;
 else mode_in ( cpio ) ;
 break ;
 case 'p' : if ( * cpio -> argv == NULL || * * cpio -> argv == '\0' ) lafe_errc ( 1 , 0 , "-p mode requires a target directory" ) ;
 mode_pass ( cpio , * cpio -> argv ) ;
 break ;
 default : lafe_errc ( 1 , 0 , "Must specify at least one of -i, -o, or -p" ) ;
 }
 archive_match_free ( cpio -> matching ) ;
 free_cache ( cpio -> gname_cache ) ;
 free_cache ( cpio -> uname_cache ) ;
 free ( cpio -> destdir ) ;
 passphrase_free ( cpio -> ppbuff ) ;
 return ( cpio -> return_value ) ;
 }

static int selinux_set_mnt_opts ( struct super_block * sb , struct security_mnt_opts * opts , unsigned long kern_flags , unsigned long * set_kern_flags ) {
 const struct cred * cred = current_cred ( ) ;
 int rc = 0 , i ;
 struct superblock_security_struct * sbsec = sb -> s_security ;
 const char * name = sb -> s_type -> name ;
 struct dentry * root = sbsec -> sb -> s_root ;
 struct inode_security_struct * root_isec ;
 u32 fscontext_sid = 0 , context_sid = 0 , rootcontext_sid = 0 ;
 u32 defcontext_sid = 0 ;
 char * * mount_options = opts -> mnt_opts ;
 int * flags = opts -> mnt_opts_flags ;
 int num_opts = opts -> num_mnt_opts ;
 mutex_lock ( & sbsec -> lock ) ;
 if ( ! ss_initialized ) {
 if ( ! num_opts ) {
 goto out ;
 }
 rc = - EINVAL ;
 printk ( KERN_WARNING "SELinux: Unable to set superblock options " "before the security server is initialized\n" ) ;
 goto out ;
 }
 if ( kern_flags && ! set_kern_flags ) {
 rc = - EINVAL ;
 goto out ;
 }
 if ( ( sbsec -> flags & SE_SBINITIALIZED ) && ( sb -> s_type -> fs_flags & FS_BINARY_MOUNTDATA ) && ( num_opts == 0 ) ) goto out ;
 root_isec = backing_inode_security_novalidate ( root ) ;
 for ( i = 0 ;
 i < num_opts ;
 i ++ ) {
 u32 sid ;
 if ( flags [ i ] == SBLABEL_MNT ) continue ;
 rc = security_context_str_to_sid ( mount_options [ i ] , & sid , GFP_KERNEL ) ;
 if ( rc ) {
 printk ( KERN_WARNING "SELinux: security_context_str_to_sid" "(%s) failed for (dev %s, type %s) errno=%d\n" , mount_options [ i ] , sb -> s_id , name , rc ) ;
 goto out ;
 }
 switch ( flags [ i ] ) {
 case FSCONTEXT_MNT : fscontext_sid = sid ;
 if ( bad_option ( sbsec , FSCONTEXT_MNT , sbsec -> sid , fscontext_sid ) ) goto out_double_mount ;
 sbsec -> flags |= FSCONTEXT_MNT ;
 break ;
 case CONTEXT_MNT : context_sid = sid ;
 if ( bad_option ( sbsec , CONTEXT_MNT , sbsec -> mntpoint_sid , context_sid ) ) goto out_double_mount ;
 sbsec -> flags |= CONTEXT_MNT ;
 break ;
 case ROOTCONTEXT_MNT : rootcontext_sid = sid ;
 if ( bad_option ( sbsec , ROOTCONTEXT_MNT , root_isec -> sid , rootcontext_sid ) ) goto out_double_mount ;
 sbsec -> flags |= ROOTCONTEXT_MNT ;
 break ;
 case DEFCONTEXT_MNT : defcontext_sid = sid ;
 if ( bad_option ( sbsec , DEFCONTEXT_MNT , sbsec -> def_sid , defcontext_sid ) ) goto out_double_mount ;
 sbsec -> flags |= DEFCONTEXT_MNT ;
 break ;
 default : rc = - EINVAL ;
 goto out ;
 }
 }
 if ( sbsec -> flags & SE_SBINITIALIZED ) {
 if ( ( sbsec -> flags & SE_MNTMASK ) && ! num_opts ) goto out_double_mount ;
 rc = 0 ;
 goto out ;
 }
 if ( strcmp ( sb -> s_type -> name , "proc" ) == 0 ) sbsec -> flags |= SE_SBPROC | SE_SBGENFS ;
 if ( ! strcmp ( sb -> s_type -> name , "debugfs" ) || ! strcmp ( sb -> s_type -> name , "sysfs" ) || ! strcmp ( sb -> s_type -> name , "pstore" ) ) sbsec -> flags |= SE_SBGENFS ;
 if ( ! sbsec -> behavior ) {
 rc = security_fs_use ( sb ) ;
 if ( rc ) {
 printk ( KERN_WARNING "%s: security_fs_use(%s) returned %d\n" , __func__ , sb -> s_type -> name , rc ) ;
 goto out ;
 }
 }
 if ( sb -> s_user_ns != & init_user_ns ) {
 if ( context_sid || fscontext_sid || rootcontext_sid || defcontext_sid ) {
 rc = - EACCES ;
 goto out ;
 }
 if ( sbsec -> behavior == SECURITY_FS_USE_XATTR ) {
 sbsec -> behavior = SECURITY_FS_USE_MNTPOINT ;
 rc = security_transition_sid ( current_sid ( ) , current_sid ( ) , SECCLASS_FILE , NULL , & sbsec -> mntpoint_sid ) ;
 if ( rc ) goto out ;
 }
 goto out_set_opts ;
 }
 if ( fscontext_sid ) {
 rc = may_context_mount_sb_relabel ( fscontext_sid , sbsec , cred ) ;
 if ( rc ) goto out ;
 sbsec -> sid = fscontext_sid ;
 }
 if ( kern_flags & SECURITY_LSM_NATIVE_LABELS && ! context_sid ) {
 sbsec -> behavior = SECURITY_FS_USE_NATIVE ;
 * set_kern_flags |= SECURITY_LSM_NATIVE_LABELS ;
 }
 if ( context_sid ) {
 if ( ! fscontext_sid ) {
 rc = may_context_mount_sb_relabel ( context_sid , sbsec , cred ) ;
 if ( rc ) goto out ;
 sbsec -> sid = context_sid ;
 }
 else {
 rc = may_context_mount_inode_relabel ( context_sid , sbsec , cred ) ;
 if ( rc ) goto out ;
 }
 if ( ! rootcontext_sid ) rootcontext_sid = context_sid ;
 sbsec -> mntpoint_sid = context_sid ;
 sbsec -> behavior = SECURITY_FS_USE_MNTPOINT ;
 }
 if ( rootcontext_sid ) {
 rc = may_context_mount_inode_relabel ( rootcontext_sid , sbsec , cred ) ;
 if ( rc ) goto out ;
 root_isec -> sid = rootcontext_sid ;
 root_isec -> initialized = LABEL_INITIALIZED ;
 }
 if ( defcontext_sid ) {
 if ( sbsec -> behavior != SECURITY_FS_USE_XATTR && sbsec -> behavior != SECURITY_FS_USE_NATIVE ) {
 rc = - EINVAL ;
 printk ( KERN_WARNING "SELinux: defcontext option is " "invalid for this filesystem type\n" ) ;
 goto out ;
 }
 if ( defcontext_sid != sbsec -> def_sid ) {
 rc = may_context_mount_inode_relabel ( defcontext_sid , sbsec , cred ) ;
 if ( rc ) goto out ;
 }
 sbsec -> def_sid = defcontext_sid ;
 }
 out_set_opts : rc = sb_finish_set_opts ( sb ) ;
 out : mutex_unlock ( & sbsec -> lock ) ;
 return rc ;
 out_double_mount : rc = - EINVAL ;
 printk ( KERN_WARNING "SELinux: mount invalid. Same superblock, different " "security settings for (dev %s, type %s)\n" , sb -> s_id , name ) ;
 goto out ;
 }

