 case C93_4X4_FROM_PREV : for ( j = 0 ;
 j < 8 ;
 j += 4 ) {
 for ( i = 0 ;
 i < 8 ;
 i += 4 ) {
 offset = bytestream2_get_le16 ( & gb ) ;
