 }

inline static void _slurm_rpc_reboot_nodes ( slurm_msg_t * msg ) {
 int rc ;
 uid_t uid = g_slurm_auth_get_uid ( msg -> auth_cred , slurmctld_config . auth_info ) ;
 # ifndef HAVE_FRONT_END int i ;
 struct node_record * node_ptr ;
