 DPRINTF ( "ACK no pending IRQ\n" ) ;
 return 1023 ;
 }
 s -> last_active [ new_irq ] [ cpu ] = s -> running_irq [ cpu ] ;
 GIC_CLEAR_PENDING ( new_irq , GIC_TEST_MODEL ( new_irq ) ? ALL_CPU_MASK : cm ) ;
