 input_clock_t * p_clock = p_owner -> p_clock ;
 vlc_assert_locked ( & p_owner -> lock ) ;
 const mtime_t i_es_delay = p_owner -> i_ts_delay ;
 if ( ! p_clock ) return ;
 const bool b_ephemere = pi_ts1 && * pi_ts0 == * pi_ts1 ;
 int i_rate ;
 if ( * pi_ts0 > VLC_TS_INVALID ) {
 * pi_ts0 += i_es_delay ;
 if ( pi_ts1 && * pi_ts1 > VLC_TS_INVALID ) * pi_ts1 += i_es_delay ;
 if ( input_clock_ConvertTS ( VLC_OBJECT ( p_dec ) , p_clock , & i_rate , pi_ts0 , pi_ts1 , i_ts_bound ) ) {
 if ( pi_ts1 != NULL ) msg_Err ( p_dec , "Could not convert timestamps %" PRId64 ", %" PRId64 "" , * pi_ts0 , * pi_ts1 ) ;
 else msg_Err ( p_dec , "Could not convert timestamp %" PRId64 , * pi_ts0 ) ;
 * pi_ts0 = VLC_TS_INVALID ;
 }
 }
 else {
 i_rate = input_clock_GetRate ( p_clock ) ;
 }
 if ( ! b_ephemere && pi_ts1 && * pi_ts0 == * pi_ts1 ) * pi_ts1 += 1 ;
 if ( pi_duration ) * pi_duration = ( * pi_duration * i_rate + INPUT_RATE_DEFAULT - 1 ) / INPUT_RATE_DEFAULT ;
 if ( pi_rate ) * pi_rate = i_rate ;
 }

static int joint_decode ( COOKContext * q , COOKSubpacket * p , float * mlt_buffer_left , float * mlt_buffer_right ) {
 int i , j , res ;
 int decouple_tab [ SUBBAND_SIZE ] = {
 0 }
 ;
 float * decode_buffer = q -> decode_buffer_0 ;
 int idx , cpl_tmp ;
 float f1 , f2 ;
 const float * cplscale ;
 memset ( decode_buffer , 0 , sizeof ( q -> decode_buffer_0 ) ) ;
 memset ( mlt_buffer_left , 0 , 1024 * sizeof ( * mlt_buffer_left ) ) ;
 memset ( mlt_buffer_right , 0 , 1024 * sizeof ( * mlt_buffer_right ) ) ;
 decouple_info ( q , p , decouple_tab ) ;
 if ( ( res = mono_decode ( q , p , decode_buffer ) ) < 0 ) return res ;
 for ( i = 0 ;
 i < p -> js_subband_start ;
 i ++ ) {
 for ( j = 0 ;
 j < SUBBAND_SIZE ;
 j ++ ) {
 mlt_buffer_left [ i * 20 + j ] = decode_buffer [ i * 40 + j ] ;
 mlt_buffer_right [ i * 20 + j ] = decode_buffer [ i * 40 + 20 + j ] ;
 }
 }
 idx = ( 1 << p -> js_vlc_bits ) - 1 ;
 for ( i = p -> js_subband_start ;
 i < p -> subbands ;
 i ++ ) {
 cpl_tmp = cplband [ i ] ;
 idx -= decouple_tab [ cpl_tmp ] ;
 cplscale = q -> cplscales [ p -> js_vlc_bits - 2 ] ;
 f1 = cplscale [ decouple_tab [ cpl_tmp ] + 1 ] ;
