 config -> flags |= XD3_SEC_FGK ;
 }
 else if ( strcmp ( option_secondary , "lzma" ) == 0 && SECONDARY_LZMA ) {
 config -> flags |= XD3_SEC_LZMA ;
 }
 else if ( strncmp ( option_secondary , "djw" , 3 ) == 0 && SECONDARY_DJW ) {
