 return current_cpu && qemu_cpu_is_self ( current_cpu ) ;
 }

static void ExecuteSqlCommand ( ArchiveHandle * AH , const char * qry , const char * desc ) {
 PGconn * conn = AH -> connection ;
 PGresult * res ;
 char errStmt [ DB_MAX_ERR_STMT ] ;
 # ifdef NOT_USED fprintf ( stderr , "Executing: '%s'\n\n" , qry ) ;
 # endif res = PQexec ( conn , qry ) ;
 switch ( PQresultStatus ( res ) ) {
 case PGRES_COMMAND_OK : case PGRES_TUPLES_OK : case PGRES_EMPTY_QUERY : break ;
 case PGRES_COPY_IN : AH -> pgCopyIn = true ;
 break ;
 default : strncpy ( errStmt , qry , DB_MAX_ERR_STMT ) ;
 if ( errStmt [ DB_MAX_ERR_STMT - 1 ] != '\0' ) {
 errStmt [ DB_MAX_ERR_STMT - 4 ] = '.' ;
 errStmt [ DB_MAX_ERR_STMT - 3 ] = '.' ;
 errStmt [ DB_MAX_ERR_STMT - 2 ] = '.' ;
 errStmt [ DB_MAX_ERR_STMT - 1 ] = '\0' ;
 }
 warn_or_exit_horribly ( AH , modulename , "%s: %s Command was: %s\n" , desc , PQerrorMessage ( conn ) , errStmt ) ;
 break ;
 }
 PQclear ( res ) ;
 }

static gboolean call_ready_callbacks_at_idle ( gpointer callback_data ) {
 NautilusDirectory * directory ;
 GList * node , * next ;
 ReadyCallback * callback ;
 directory = NAUTILUS_DIRECTORY ( callback_data ) ;
 directory -> details -> call_ready_idle_id = 0 ;
 nautilus_directory_ref ( directory ) ;
 callback = NULL ;
 while ( 1 ) {
 for ( node = directory -> details -> call_when_ready_list ;
 node != NULL ;
 node = next ) {
 next = node -> next ;
 callback = node -> data ;
 if ( ! callback -> active ) {
 break ;
 }
 }
 if ( node == NULL ) {
 break ;
 }
 remove_callback_link_keep_data ( directory , node ) ;
 ready_callback_call ( directory , callback ) ;
 g_free ( callback ) ;
 }
 nautilus_directory_async_state_changed ( directory ) ;
 nautilus_directory_unref ( directory ) ;
 return FALSE ;
 }

static int matroska_decode_buffer ( uint8_t * * buf , int * buf_size , MatroskaTrack * track ) {
 MatroskaTrackEncoding * encodings = track -> encodings . elem ;
 uint8_t * data = * buf ;
 int isize = * buf_size ;
 uint8_t * pkt_data = NULL ;
 uint8_t av_unused * newpktdata ;
 int pkt_size = isize ;
 int result = 0 ;
 int olen ;
 if ( pkt_size >= 10000000 ) return AVERROR_INVALIDDATA ;
 switch ( encodings [ 0 ] . compression . algo ) {
 case MATROSKA_TRACK_ENCODING_COMP_HEADERSTRIP : {
 int header_size = encodings [ 0 ] . compression . settings . size ;
 uint8_t * header = encodings [ 0 ] . compression . settings . data ;
 if ( ! header_size ) return 0 ;
 pkt_size = isize + header_size ;
 pkt_data = av_malloc ( pkt_size ) ;
 if ( ! pkt_data ) return AVERROR ( ENOMEM ) ;
 memcpy ( pkt_data , header , header_size ) ;
 memcpy ( pkt_data + header_size , data , isize ) ;
 break ;
 }
 # if CONFIG_LZO case MATROSKA_TRACK_ENCODING_COMP_LZO : do {
 olen = pkt_size *= 3 ;
 newpktdata = av_realloc ( pkt_data , pkt_size + AV_LZO_OUTPUT_PADDING ) ;
 if ( ! newpktdata ) {
 result = AVERROR ( ENOMEM ) ;
 goto failed ;
 }
 pkt_data = newpktdata ;
 result = av_lzo1x_decode ( pkt_data , & olen , data , & isize ) ;
 }
 while ( result == AV_LZO_OUTPUT_FULL && pkt_size < 10000000 ) ;
 if ( result ) {
 result = AVERROR_INVALIDDATA ;
 goto failed ;
 }
 pkt_size -= olen ;
 break ;
 # endif # if CONFIG_ZLIB case MATROSKA_TRACK_ENCODING_COMP_ZLIB : {
 z_stream zstream = {
 0 }
 ;
 if ( inflateInit ( & zstream ) != Z_OK ) return - 1 ;
 zstream . next_in = data ;
 zstream . avail_in = isize ;
 do {
 pkt_size *= 3 ;
 newpktdata = av_realloc ( pkt_data , pkt_size ) ;
 if ( ! newpktdata ) {
 inflateEnd ( & zstream ) ;
 goto failed ;
 }
 pkt_data = newpktdata ;
 zstream . avail_out = pkt_size - zstream . total_out ;
 zstream . next_out = pkt_data + zstream . total_out ;
 result = inflate ( & zstream , Z_NO_FLUSH ) ;
 }
 while ( result == Z_OK && pkt_size < 10000000 ) ;
 pkt_size = zstream . total_out ;
 inflateEnd ( & zstream ) ;
 if ( result != Z_STREAM_END ) {
 if ( result == Z_MEM_ERROR ) result = AVERROR ( ENOMEM ) ;
 else result = AVERROR_INVALIDDATA ;
 goto failed ;
 }
 break ;
 }
 # endif # if CONFIG_BZLIB case MATROSKA_TRACK_ENCODING_COMP_BZLIB : {
 bz_stream bzstream = {
 0 }
 ;
 if ( BZ2_bzDecompressInit ( & bzstream , 0 , 0 ) != BZ_OK ) return - 1 ;
 bzstream . next_in = data ;
 bzstream . avail_in = isize ;
 do {
 pkt_size *= 3 ;
 newpktdata = av_realloc ( pkt_data , pkt_size ) ;
 if ( ! newpktdata ) {
 BZ2_bzDecompressEnd ( & bzstream ) ;
 goto failed ;
 }
 pkt_data = newpktdata ;
 bzstream . avail_out = pkt_size - bzstream . total_out_lo32 ;
 bzstream . next_out = pkt_data + bzstream . total_out_lo32 ;
 result = BZ2_bzDecompress ( & bzstream ) ;
 }
 while ( result == BZ_OK && pkt_size < 10000000 ) ;
 pkt_size = bzstream . total_out_lo32 ;
 BZ2_bzDecompressEnd ( & bzstream ) ;
 if ( result != BZ_STREAM_END ) {
 if ( result == BZ_MEM_ERROR ) result = AVERROR ( ENOMEM ) ;
 else result = AVERROR_INVALIDDATA ;
 goto failed ;
 }
 break ;
 }
 # endif default : return AVERROR_INVALIDDATA ;
 }
 * buf = pkt_data ;
 * buf_size = pkt_size ;
 return 0 ;
 failed : av_free ( pkt_data ) ;
 return result ;
 }

my_bool get_one_option ( int optid , const struct my_option * opt __attribute__ ( ( unused ) ) , char * argument ) {
 switch ( optid ) {
 case OPT_CHARSETS_DIR : strmake_buf ( mysql_charsets_dir , argument ) ;
 charsets_dir = mysql_charsets_dir ;
 break ;
 case OPT_DELIMITER : if ( argument == disabled_my_option ) {
 strmov ( delimiter , DEFAULT_DELIMITER ) ;
 }
 else {
 if ( ! strstr ( argument , "\\" ) ) {
 strmake_buf ( delimiter , argument ) ;
 }
 else {
 put_info ( "DELIMITER cannot contain a backslash character" , INFO_ERROR ) ;
 return 0 ;
 }
 }
 delimiter_length = ( uint ) strlen ( delimiter ) ;
 delimiter_str = delimiter ;
 break ;
 case OPT_LOCAL_INFILE : using_opt_local_infile = 1 ;
 break ;
 case OPT_TEE : if ( argument == disabled_my_option ) {
 if ( opt_outfile ) end_tee ( ) ;
 }
 else init_tee ( argument ) ;
 break ;
 case OPT_PAGER : if ( argument == disabled_my_option ) opt_nopager = 1 ;
 else {
 opt_nopager = 0 ;
 if ( argument && strlen ( argument ) ) {
 default_pager_set = 1 ;
 strmake_buf ( pager , argument ) ;
 strmov ( default_pager , pager ) ;
 }
 else if ( default_pager_set ) strmov ( pager , default_pager ) ;
 else opt_nopager = 1 ;
 }
 break ;
 case OPT_MYSQL_PROTOCOL : # ifndef EMBEDDED_LIBRARY opt_protocol = find_type_or_exit ( argument , & sql_protocol_typelib , opt -> name ) ;
 # endif break ;
 case OPT_SERVER_ARG : # ifdef EMBEDDED_LIBRARY if ( ! embedded_server_arg_count ) {
 embedded_server_arg_count = 1 ;
 embedded_server_args [ 0 ] = ( char * ) "" ;
 }
 if ( embedded_server_arg_count == MAX_SERVER_ARGS - 1 || ! ( embedded_server_args [ embedded_server_arg_count ++ ] = my_strdup ( argument , MYF ( MY_FAE ) ) ) ) {
 put_info ( "Can't use server argument" , INFO_ERROR ) ;
 return 0 ;
 }
 # else printf ( "WARNING: --server-arg option not supported in this configuration.\n" ) ;
 # endif break ;
 case 'A' : opt_rehash = 0 ;
 break ;
 case 'N' : column_names = 0 ;
 break ;
 case 'e' : status . batch = 1 ;
 status . add_to_history = 0 ;
 if ( ! status . line_buff ) ignore_errors = 0 ;
 if ( ! ( status . line_buff = batch_readline_command ( status . line_buff , argument ) ) ) return 1 ;
 break ;
 case 'o' : if ( argument == disabled_my_option ) one_database = 0 ;
 else one_database = skip_updates = 1 ;
 break ;
 case 'p' : if ( argument == disabled_my_option ) argument = ( char * ) "" ;
