static void pxa2xx_fir_write ( void * opaque , hwaddr addr , uint64_t value64 , unsigned size ) {
 PXA2xxFIrState * s = ( PXA2xxFIrState * ) opaque ;
 uint32_t value = value64 ;
 uint8_t ch ;
 switch ( addr ) {
 case ICCR0 : s -> control [ 0 ] = value ;
 if ( ! ( value & ( 1 << 4 ) ) ) s -> rx_len = s -> rx_start = 0 ;
 if ( ! ( value & ( 1 << 3 ) ) ) {
 }
 s -> enable = value & 1 ;
 if ( ! s -> enable ) s -> status [ 0 ] = 0 ;
 pxa2xx_fir_update ( s ) ;
 break ;
 case ICCR1 : s -> control [ 1 ] = value ;
 break ;
 case ICCR2 : s -> control [ 2 ] = value & 0x3f ;
 pxa2xx_fir_update ( s ) ;
 break ;
 case ICDR : if ( s -> control [ 2 ] & ( 1 << 2 ) ) ch = value ;
 else ch = ~ value ;
 if ( s -> chr && s -> enable && ( s -> control [ 0 ] & ( 1 << 3 ) ) ) qemu_chr_fe_write ( s -> chr , & ch , 1 ) ;
 break ;
 case ICSR0 : s -> status [ 0 ] &= ~ ( value & 0x66 ) ;
 pxa2xx_fir_update ( s ) ;
 break ;
 case ICFOR : break ;
 default : printf ( "%s: Bad register " REG_FMT "\n" , __FUNCTION__ , addr ) ;
 }
 }

static bfd_boolean srec_write_record ( bfd * abfd , unsigned int type , bfd_vma address , const bfd_byte * data , const bfd_byte * end ) {
 char buffer [ 2 * MAXCHUNK + 6 ] ;
 unsigned int check_sum = 0 ;
 const bfd_byte * src = data ;
 char * dst = buffer ;
 char * length ;
 bfd_size_type wrlen ;
 * dst ++ = 'S' ;
 * dst ++ = '0' + type ;
 length = dst ;
 dst += 2 ;
 switch ( type ) {
 case 3 : case 7 : TOHEX ( dst , ( address >> 24 ) , check_sum ) ;
 dst += 2 ;
 case 8 : case 2 : TOHEX ( dst , ( address >> 16 ) , check_sum ) ;
 dst += 2 ;
 case 9 : case 1 : case 0 : TOHEX ( dst , ( address >> 8 ) , check_sum ) ;
 dst += 2 ;
 TOHEX ( dst , ( address ) , check_sum ) ;
 dst += 2 ;
 break ;
 }
 for ( src = data ;
 src < end ;
 src ++ ) {
 TOHEX ( dst , * src , check_sum ) ;
 dst += 2 ;
 }
 TOHEX ( length , ( dst - length ) / 2 , check_sum ) ;
 check_sum &= 0xff ;
 check_sum = 255 - check_sum ;
 TOHEX ( dst , check_sum , check_sum ) ;
 dst += 2 ;
 * dst ++ = '\r' ;
 * dst ++ = '\n' ;
 wrlen = dst - buffer ;
 return bfd_bwrite ( ( void * ) buffer , wrlen , abfd ) == wrlen ;
 }

static gpgme_error_t uiserver_encrypt ( void * engine , gpgme_key_t recp [ ] , gpgme_encrypt_flags_t flags , gpgme_data_t plain , gpgme_data_t ciph , int use_armor ) {
 engine_uiserver_t uiserver = engine ;
