 if ( qemuMonitorHMPCommand ( mon , cmd , & reply ) < 0 ) goto fail ;
 if ( strstr ( reply , "unknown command" ) != NULL ) {
 VIR_FREE ( reply ) ;
 cmd = "nmi 0" ;
 reply = NULL ;
 if ( qemuMonitorHMPCommand ( mon , cmd , & reply ) < 0 ) goto fail ;
 }
