 mpi_powm ( a , pkey -> g , k , pkey -> p ) ;
 mpi_powm ( b , pkey -> y , k , pkey -> p ) ;
 mpi_mulm ( b , b , input , pkey -> p ) ;
 # if 0 if ( DBG_CIPHER ) {
 log_mpidump ( "elg encrypted y= " , pkey -> y ) ;
