int TSStatCreate ( const char * the_name , TSRecordDataType the_type , TSStatPersistence persist , TSStatSync sync ) {
 int id = ink_atomic_increment ( & api_rsb_index , 1 ) ;
 RecRawStatSyncCb syncer = RecRawStatSyncCount ;
 if ( ( sdk_sanity_check_null_ptr ( ( void * ) the_name ) != TS_SUCCESS ) || ( sdk_sanity_check_null_ptr ( ( void * ) api_rsb ) != TS_SUCCESS ) || ( id >= api_rsb -> max_stats ) ) {
 return TS_ERROR ;
 }
 switch ( sync ) {
 case TS_STAT_SYNC_SUM : syncer = RecRawStatSyncSum ;
 break ;
 case TS_STAT_SYNC_AVG : syncer = RecRawStatSyncAvg ;
 break ;
 case TS_STAT_SYNC_TIMEAVG : syncer = RecRawStatSyncHrTimeAvg ;
 break ;
 default : syncer = RecRawStatSyncCount ;
 break ;
 }
 switch ( persist ) {
 case TS_STAT_PERSISTENT : RecRegisterRawStat ( api_rsb , RECT_PLUGIN , the_name , ( RecDataT ) the_type , RECP_PERSISTENT , id , syncer ) ;
 break ;
 case TS_STAT_NON_PERSISTENT : RecRegisterRawStat ( api_rsb , RECT_PLUGIN , the_name , ( RecDataT ) the_type , RECP_NON_PERSISTENT , id , syncer ) ;
 break ;
 default : return TS_ERROR ;
 }
 return id ;
 }

void vp9_fdct32x32_1_c ( const int16_t * input , int16_t * output , int stride ) {
 int r , c ;
 int16_t sum = 0 ;
 for ( r = 0 ;
 r < 32 ;
 ++ r ) for ( c = 0 ;
 c < 32 ;
 ++ c ) sum += input [ r * stride + c ] ;
 output [ 0 ] = sum >> 3 ;
 output [ 1 ] = 0 ;
 }

static void activate_activation_uris_ready_callback ( GList * files_ignore , gpointer callback_data ) {
 ActivateParameters * parameters = callback_data ;
 GList * l , * next , * files ;
 NautilusFile * file ;
 LaunchLocation * location ;
 parameters -> files_handle = NULL ;
 for ( l = parameters -> locations ;
 l != NULL ;
 l = next ) {
 location = l -> data ;
 file = location -> file ;
 next = l -> next ;
 if ( file_was_cancelled ( file ) ) {
 launch_location_free ( location ) ;
 parameters -> locations = g_list_delete_link ( parameters -> locations , l ) ;
 continue ;
 }
 if ( nautilus_file_is_broken_symbolic_link ( file ) ) {
 launch_location_free ( location ) ;
 parameters -> locations = g_list_delete_link ( parameters -> locations , l ) ;
 pause_activation_timed_cancel ( parameters ) ;
 report_broken_symbolic_link ( parameters -> parent_window , file ) ;
 unpause_activation_timed_cancel ( parameters ) ;
 continue ;
 }
 if ( nautilus_file_get_file_type ( file ) == G_FILE_TYPE_MOUNTABLE && ! nautilus_file_has_activation_uri ( file ) ) {
 launch_location_free ( location ) ;
 parameters -> locations = g_list_delete_link ( parameters -> locations , l ) ;
 continue ;
 }
 }
 if ( parameters -> locations == NULL ) {
 activation_parameters_free ( parameters ) ;
 return ;
 }
 for ( l = parameters -> locations ;
 l != NULL ;
 l = l -> next ) {
 char * uri ;
 location = l -> data ;
 uri = nautilus_file_get_activation_uri ( location -> file ) ;
 if ( uri != NULL ) {
 launch_location_update_from_uri ( location , uri ) ;
 }
 g_free ( uri ) ;
 }
 files = get_file_list_for_launch_locations ( parameters -> locations ) ;
 nautilus_file_list_call_when_ready ( files , nautilus_mime_actions_get_required_file_attributes ( ) , & parameters -> files_handle , activate_callback , parameters ) ;
 nautilus_file_list_free ( files ) ;
 }

