static int openpic_load ( QEMUFile * f , void * opaque , int version_id ) {
 OpenPICState * opp = ( OpenPICState * ) opaque ;
 unsigned int i ;
 if ( version_id != 1 ) {
 return - EINVAL ;
 }
 qemu_get_be32s ( f , & opp -> gcr ) ;
 qemu_get_be32s ( f , & opp -> vir ) ;
 qemu_get_be32s ( f , & opp -> pir ) ;
 qemu_get_be32s ( f , & opp -> spve ) ;
 qemu_get_be32s ( f , & opp -> tfrr ) ;
 qemu_get_be32s ( f , & opp -> nb_cpus ) ;
 for ( i = 0 ;
 i < opp -> nb_cpus ;
 i ++ ) {
 qemu_get_sbe32s ( f , & opp -> dst [ i ] . ctpr ) ;
 openpic_load_IRQ_queue ( f , & opp -> dst [ i ] . raised ) ;
 openpic_load_IRQ_queue ( f , & opp -> dst [ i ] . servicing ) ;
 qemu_get_buffer ( f , ( uint8_t * ) & opp -> dst [ i ] . outputs_active , sizeof ( opp -> dst [ i ] . outputs_active ) ) ;
 }
 for ( i = 0 ;
 i < OPENPIC_MAX_TMR ;
 i ++ ) {
 qemu_get_be32s ( f , & opp -> timers [ i ] . tccr ) ;
 qemu_get_be32s ( f , & opp -> timers [ i ] . tbcr ) ;
 }
 for ( i = 0 ;
 i < opp -> max_irq ;
 i ++ ) {
 uint32_t val ;
 val = qemu_get_be32 ( f ) ;
 write_IRQreg_idr ( opp , i , val ) ;
 val = qemu_get_be32 ( f ) ;
 write_IRQreg_ivpr ( opp , i , val ) ;
 qemu_get_be32s ( f , & opp -> src [ i ] . ivpr ) ;
 qemu_get_be32s ( f , & opp -> src [ i ] . idr ) ;
 qemu_get_be32s ( f , & opp -> src [ i ] . destmask ) ;
 qemu_get_sbe32s ( f , & opp -> src [ i ] . last_cpu ) ;
 qemu_get_sbe32s ( f , & opp -> src [ i ] . pending ) ;
 }
 return 0 ;
 }

static int vorbis_decode_frame ( AVCodecContext * avctx , void * data , int * got_frame_ptr , AVPacket * avpkt ) {
 const uint8_t * buf = avpkt -> data ;
 int buf_size = avpkt -> size ;
 vorbis_context * vc = avctx -> priv_data ;
 AVFrame * frame = data ;
 GetBitContext * gb = & vc -> gb ;
 float * channel_ptrs [ 255 ] ;
 int i , len , ret ;
 av_dlog ( NULL , "packet length %d \n" , buf_size ) ;
 frame -> nb_samples = vc -> blocksize [ 1 ] / 2 ;
 if ( ( ret = ff_get_buffer ( avctx , frame ) ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "get_buffer() failed\n" ) ;
 return ret ;
 }
 if ( vc -> audio_channels > 8 ) {
 for ( i = 0 ;
 i < vc -> audio_channels ;
 i ++ ) channel_ptrs [ i ] = ( float * ) frame -> extended_data [ i ] ;
 }
 else {
 for ( i = 0 ;
 i < vc -> audio_channels ;
 i ++ ) {
 int ch = ff_vorbis_channel_layout_offsets [ vc -> audio_channels - 1 ] [ i ] ;
 channel_ptrs [ ch ] = ( float * ) frame -> extended_data [ i ] ;
 }
 }
 init_get_bits ( gb , buf , buf_size * 8 ) ;
 if ( ( len = vorbis_parse_audio_packet ( vc , channel_ptrs ) ) <= 0 ) return len ;
 if ( ! vc -> first_frame ) {
 vc -> first_frame = 1 ;
 * got_frame_ptr = 0 ;
 return buf_size ;
 }
 av_dlog ( NULL , "parsed %d bytes %d bits, returned %d samples (*ch*bits) \n" , get_bits_count ( gb ) / 8 , get_bits_count ( gb ) % 8 , len ) ;
 frame -> nb_samples = len ;
 * got_frame_ptr = 1 ;
 return buf_size ;
 }

void config_nic_rules ( config_tree * ptree ) {
 nic_rule_node * curr_node ;
 sockaddr_u addr ;
 nic_rule_match match_type ;
 nic_rule_action action ;
 char * if_name ;
 char * pchSlash ;
 int prefixlen ;
 int addrbits ;
 curr_node = HEAD_PFIFO ( ptree -> nic_rules ) ;
 if ( curr_node != NULL && ( HAVE_OPT ( NOVIRTUALIPS ) || HAVE_OPT ( INTERFACE ) ) ) {
 msyslog ( LOG_ERR , "interfaceic rules are not allowed with --interface (-I) or --novirtualips (-L)%s" , ( input_from_file ) ? ", exiting" : "" ) ;
 if ( input_from_file ) exit ( 1 ) ;
 else return ;
 }
 for ( ;
 curr_node != NULL ;
 curr_node = curr_node -> link ) {
 prefixlen = - 1 ;
 if_name = curr_node -> if_name ;
 if ( if_name != NULL ) if_name = estrdup ( if_name ) ;
 switch ( curr_node -> match_class ) {
 default : match_type = MATCH_ALL ;
 NTP_INSIST ( 0 ) ;
 break ;
 case 0 : NTP_INSIST ( if_name != NULL ) ;
 pchSlash = strchr ( if_name , '/' ) ;
 if ( pchSlash != NULL ) * pchSlash = '\0' ;
 if ( is_ip_address ( if_name , AF_UNSPEC , & addr ) ) {
 match_type = MATCH_IFADDR ;
 if ( pchSlash != NULL ) {
 sscanf ( pchSlash + 1 , "%d" , & prefixlen ) ;
 addrbits = 8 * SIZEOF_INADDR ( AF ( & addr ) ) ;
 prefixlen = max ( - 1 , prefixlen ) ;
 prefixlen = min ( prefixlen , addrbits ) ;
 }
 }
 else {
 match_type = MATCH_IFNAME ;
 if ( pchSlash != NULL ) * pchSlash = '/' ;
 }
 break ;
 case T_All : match_type = MATCH_ALL ;
 break ;
 case T_Ipv4 : match_type = MATCH_IPV4 ;
 break ;
 case T_Ipv6 : match_type = MATCH_IPV6 ;
 break ;
 case T_Wildcard : match_type = MATCH_WILDCARD ;
 break ;
 }
 switch ( curr_node -> action ) {
 default : action = ACTION_LISTEN ;
 NTP_INSIST ( 0 ) ;
 break ;
 case T_Listen : action = ACTION_LISTEN ;
 break ;
 case T_Ignore : action = ACTION_IGNORE ;
 break ;
 case T_Drop : action = ACTION_DROP ;
 break ;
 }
 add_nic_rule ( match_type , if_name , prefixlen , action ) ;
 timer_interfacetimeout ( current_time + 2 ) ;
 if ( if_name != NULL ) free ( if_name ) ;
 }
 }

