static void print_month ( UCalendar * c , UChar * days [ ] , UBool useLongNames , int32_t fdow , UErrorCode * status ) {
 int32_t width , pad , i , day ;
 int32_t lens [ DAY_COUNT ] ;
 int32_t firstday , current ;
