int gs_nulldevice ( gs_gstate * pgs ) {
 int code = 0 ;
 bool saveLockSafety = false ;
 if ( pgs -> device == 0 || ! gx_device_is_null ( pgs -> device ) ) {
 gx_device * ndev ;
 code = gs_copydevice ( & ndev , ( const gx_device * ) & gs_null_device , pgs -> memory ) ;
 if ( code < 0 ) return code ;
 if ( gs_currentdevice_inline ( pgs ) != NULL ) saveLockSafety = gs_currentdevice_inline ( pgs ) -> LockSafetyParams ;
 rc_init ( ndev , pgs -> memory , 0 ) ;
 if ( pgs -> device != NULL ) {
 if ( ( code = dev_proc ( pgs -> device , get_profile ) ( pgs -> device , & ( ndev -> icc_struct ) ) ) < 0 ) return code ;
 rc_increment ( ndev -> icc_struct ) ;
 set_dev_proc ( ndev , get_profile , gx_default_get_profile ) ;
 }
 if ( ( code = gs_setdevice_no_erase ( pgs , ndev ) ) < 0 ) gs_free_object ( pgs -> memory , ndev , "gs_copydevice(device)" ) ;
 gs_currentdevice_inline ( pgs ) -> LockSafetyParams = saveLockSafety ;
 }
 return code ;
 }

void vp9_dec_build_inter_predictors_sb ( MACROBLOCKD * xd , int mi_row , int mi_col , BLOCK_SIZE bsize ) {
 int plane ;
 const int mi_x = mi_col * MI_SIZE ;
 const int mi_y = mi_row * MI_SIZE ;
 for ( plane = 0 ;
 plane < MAX_MB_PLANE ;
 ++ plane ) {
 const BLOCK_SIZE plane_bsize = get_plane_block_size ( bsize , & xd -> plane [ plane ] ) ;
 const int num_4x4_w = num_4x4_blocks_wide_lookup [ plane_bsize ] ;
 const int num_4x4_h = num_4x4_blocks_high_lookup [ plane_bsize ] ;
 const int bw = 4 * num_4x4_w ;
 const int bh = 4 * num_4x4_h ;
 if ( xd -> mi [ 0 ] . src_mi -> mbmi . sb_type < BLOCK_8X8 ) {
 int i = 0 , x , y ;
 assert ( bsize == BLOCK_8X8 ) ;
 for ( y = 0 ;
 y < num_4x4_h ;
 ++ y ) for ( x = 0 ;
 x < num_4x4_w ;
 ++ x ) dec_build_inter_predictors ( xd , plane , i ++ , bw , bh , * x , 4 * y , 4 , 4 , mi_x , mi_y ) ;
 }
 else {
 dec_build_inter_predictors ( xd , plane , 0 , bw , bh , 0 , 0 , bw , bh , mi_x , mi_y ) ;
 }
 }
 }

