 data_ptr += AV_RB16 ( index_ptr + i * 2 ) ;
 }
 ctx -> slice_data [ i ] . index = data_ptr ;
 ctx -> slice_data [ i ] . prev_slice_sf = 0 ;
 if ( data_ptr > buf + data_size ) {
