 CPUX86State * env = & x86_cpu -> env ;
 int ret ;
 if ( cpu -> interrupt_request & ( CPU_INTERRUPT_NMI | CPU_INTERRUPT_SMI ) ) {
 if ( cpu -> interrupt_request & CPU_INTERRUPT_NMI ) {
 qemu_mutex_lock_iothread ( ) ;
