 if ( qemuAgentGuestSync ( mon ) < 0 ) return - 1 ;
 memset ( & msg , 0 , sizeof ( msg ) ) ;
 if ( ! ( cmdstr = virJSONValueToString ( cmd , false ) ) ) goto cleanup ;
