 rc = vp8_default_zig_zag1d [ i ] ;
 z = coeff_ptr [ rc ] ;
 dq = dequant_ptr [ rc ] ;
 rounding = dq >> 1 ;
 sz = - ( z < 0 ) ;
 x = ( z + sz ) ^ sz ;
 x += rounding ;
 if ( x >= dq ) {
 y = ( ( ( ( x * quant_ptr [ rc ] ) >> 16 ) + x ) * quant_shift_ptr [ rc ] ) >> 16 ;
 x = ( y + sz ) ^ sz ;
 qcoeff_ptr [ rc ] = x ;
 dqcoeff_ptr [ rc ] = x * dq ;
 if ( y ) eob = i ;
 }
