static int create_or_remove_cgroup ( bool do_remove , struct cgroup_mount_point * mp , const char * path , int recurse ) {
 int r , saved_errno = 0 ;
 char * buf = cgroup_to_absolute_path ( mp , path , NULL ) ;
 if ( ! buf ) return - 1 ;
 if ( do_remove ) {
 if ( recurse ) r = cgroup_rmdir ( buf ) ;
 else r = rmdir ( buf ) ;
 }
 else r = mkdir ( buf , 0777 ) ;
 saved_errno = errno ;
 free ( buf ) ;
 errno = saved_errno ;
 return r ;
 }

static int create_cgroup ( struct cgroup_mount_point * mp , const char * path ) {
 return create_or_remove_cgroup ( false , mp , path , false ) ;
 }

static int read_argb_line ( CLLCContext * ctx , GetBitContext * gb , int * top_left , VLC * vlc , uint8_t * outbuf ) {
 uint8_t * dst ;
 int pred [ 4 ] ;
 int code ;
 int i ;
 OPEN_READER ( bits , gb ) ;
 dst = outbuf ;
 pred [ 0 ] = top_left [ 0 ] ;
 pred [ 1 ] = top_left [ 1 ] ;
 pred [ 2 ] = top_left [ 2 ] ;
 pred [ 3 ] = top_left [ 3 ] ;
 for ( i = 0 ;
 i < ctx -> avctx -> width ;
 i ++ ) {
 UPDATE_CACHE ( bits , gb ) ;
 GET_VLC ( code , bits , gb , vlc [ 0 ] . table , 7 , 2 ) ;
 pred [ 0 ] += code ;
 dst [ 0 ] = pred [ 0 ] ;
 if ( dst [ 0 ] ) {
 UPDATE_CACHE ( bits , gb ) ;
 GET_VLC ( code , bits , gb , vlc [ 1 ] . table , 7 , 2 ) ;
 pred [ 1 ] += code ;
 dst [ 1 ] = pred [ 1 ] ;
 UPDATE_CACHE ( bits , gb ) ;
 GET_VLC ( code , bits , gb , vlc [ 2 ] . table , 7 , 2 ) ;
 pred [ 2 ] += code ;
 dst [ 2 ] = pred [ 2 ] ;
 UPDATE_CACHE ( bits , gb ) ;
 GET_VLC ( code , bits , gb , vlc [ 3 ] . table , 7 , 2 ) ;
 pred [ 3 ] += code ;
 dst [ 3 ] = pred [ 3 ] ;
 }
 else {
 dst [ 1 ] = 0 ;
 dst [ 2 ] = 0 ;
 dst [ 3 ] = 0 ;
 }
 dst += 4 ;
 }
 CLOSE_READER ( bits , gb ) ;
 dst -= 4 * ctx -> avctx -> width ;
 top_left [ 0 ] = dst [ 0 ] ;
 if ( top_left [ 0 ] ) {
 top_left [ 1 ] = dst [ 1 ] ;
 top_left [ 2 ] = dst [ 2 ] ;
 top_left [ 3 ] = dst [ 3 ] ;
 }
 return 0 ;
 }

