static void test_rfc2231_parser ( void ) {
 const char * input = ";
 key4*=us-ascii''foo" ";
 key*2=ba%" ";
 key2*0=a" ";
 key3*0*=us-ascii'en'xyz" ";
 key*0=\"foo\"" ";
 key2*1*=b%25" ";
 key3*1=plop%" ";
 key*1=baz" ;
 const char * output [ ] = {
 "key" , "foobazba%" , "key2*" , "''ab%25" , "key3*" , "us-ascii'en'xyzplop%25" , "key4*" , "us-ascii''foo" , NULL }
 ;
