 if ( ! r -> tmp_b_block_base ) {
 int i ;
 r -> tmp_b_block_base = av_malloc ( s -> linesize * 48 ) ;
 for ( i = 0 ;
 i < 2 ;
 i ++ ) r -> tmp_b_block_y [ i ] = r -> tmp_b_block_base + i * 16 * s -> linesize ;
 for ( i = 0 ;
 i < 4 ;
 i ++ ) r -> tmp_b_block_uv [ i ] = r -> tmp_b_block_base + 32 * s -> linesize + ( i >> 1 ) * 8 * s -> uvlinesize + ( i & 1 ) * 16 ;
