 else if ( strcmp ( args [ 0 ] , "COOKIE" ) == 0 ) return auth_server_input_cookie ( conn , args + 1 ) ;
 else if ( strcmp ( args [ 0 ] , "DONE" ) == 0 ) return auth_server_input_done ( conn ) ;
