 d_ptr += 2 ;
 value = 0 ;
 if ( numbytes > 4 ) {
 value = 0xffffffff ;
 }
 else {
 for ( i = 0 ;
 i < numbytes ;
 i ++ ) {
 value = value << 8 | d_ptr [ i ] ;
 }
 }
 a = Asn1GenericNew ( ) ;
 if ( a == NULL ) return NULL ;
