 ber_bvarray_free ( erefs ) ;
 }
 }
 else {
 rs -> sr_ref = referral_rewrite ( default_referral , NULL , & op -> o_req_dn , op -> oq_search . rs_scope ) ;
 rs -> sr_err = rs -> sr_ref != NULL ? LDAP_REFERRAL : LDAP_NO_SUCH_OBJECT ;
 }
 send_ldap_result ( op , rs ) ;
 if ( rs -> sr_ref ) {
