 if ( grow_win != NULL ) {
 MAIN_WINDOW_REC * win ;
 GSList * grow_list , * shrink_list , * tmp ;
 grow_list = mainwindows_get_line ( grow_win ) ;
 shrink_list = mainwindows_get_line ( window ) ;
 for ( tmp = grow_list ;
 tmp != NULL ;
 tmp = tmp -> next ) {
 win = tmp -> data ;
 win -> last_line += count ;
 }
 for ( tmp = shrink_list ;
 tmp != NULL ;
 tmp = tmp -> next ) {
 win = tmp -> data ;
 win -> first_line += count ;
 }
 mainwindows_resize_two ( grow_list , shrink_list , count ) ;
