jas_stream_t * jas_stream_freopen ( const char * path , const char * mode , FILE * fp ) {
 jas_stream_t * stream ;
 int openflags ;
 path = 0 ;
 if ( ! ( stream = jas_stream_create ( ) ) ) {
 return 0 ;
 }
 stream -> openmode_ = jas_strtoopenmode ( mode ) ;
 if ( ( stream -> openmode_ & JAS_STREAM_READ ) && ( stream -> openmode_ & JAS_STREAM_WRITE ) ) {
 openflags = O_RDWR ;
 }
 else if ( stream -> openmode_ & JAS_STREAM_READ ) {
 openflags = O_RDONLY ;
 }
 else if ( stream -> openmode_ & JAS_STREAM_WRITE ) {
 openflags = O_WRONLY ;
 }
 else {
 openflags = 0 ;
 }
 if ( stream -> openmode_ & JAS_STREAM_APPEND ) {
 openflags |= O_APPEND ;
 }
 if ( stream -> openmode_ & JAS_STREAM_BINARY ) {
 openflags |= O_BINARY ;
 }
 if ( stream -> openmode_ & JAS_STREAM_CREATE ) {
 openflags |= O_CREAT | O_TRUNC ;
 }
 stream -> obj_ = JAS_CAST ( void * , fp ) ;
 stream -> ops_ = & jas_stream_sfileops ;
 jas_stream_initbuf ( stream , JAS_STREAM_FULLBUF , 0 , 0 ) ;
 return stream ;
 }

void vp9_idct8x8_64_add_c ( const tran_low_t * input , uint8_t * dest , int stride ) {
 tran_low_t out [ 8 * 8 ] ;
 tran_low_t * outptr = out ;
 int i , j ;
 tran_low_t temp_in [ 8 ] , temp_out [ 8 ] ;
 for ( i = 0 ;
 i < 8 ;
 ++ i ) {
 idct8 ( input , outptr ) ;
 input += 8 ;
 outptr += 8 ;
 }
 for ( i = 0 ;
 i < 8 ;
 ++ i ) {
 for ( j = 0 ;
 j < 8 ;
 ++ j ) temp_in [ j ] = out [ j * 8 + i ] ;
 idct8 ( temp_in , temp_out ) ;
 for ( j = 0 ;
 j < 8 ;
 ++ j ) dest [ j * stride + i ] = clip_pixel ( ROUND_POWER_OF_TWO ( temp_out [ j ] , 5 ) + dest [ j * stride + i ] ) ;
 }
 }

