 i < len ;
 i += 8 ) {
 c2l ( in , tin0 ) ;
 d [ 0 ] = dd [ 0 ] = tin0 ;
 c2l ( in , tin1 ) ;
 d [ 1 ] = dd [ 1 ] = tin1 ;
