 fd_head -> flags |= FD_OVERLAPCONFLICT ;
 }
 }
 }
 last_fd = fd_i ;
 }
 for ( fd_i = fd_head -> next ;
 fd_i ;
 fd_i = fd_i -> next ) {
 if ( fd_i -> tvb_data ) {
