 vp9_variance_fn_ptr_t * fn_ptr = & cpi -> fn_ptr [ bsize ] ;
 int var = 0 ;
 if ( sad_list ) {
 sad_list [ 0 ] = INT_MAX ;
 sad_list [ 1 ] = INT_MAX ;
 sad_list [ 2 ] = INT_MAX ;
 sad_list [ 3 ] = INT_MAX ;
 sad_list [ 4 ] = INT_MAX ;
 }
 switch ( method ) {
 case FAST_DIAMOND : var = vp9_fast_dia_search ( x , mvp_full , step_param , error_per_bit , 0 , sad_list , fn_ptr , 1 , ref_mv , tmp_mv ) ;
