 isofile_free ( file ) ;
 return ( ARCHIVE_FATAL ) ;
 }
 file -> boot = BOOT_CATALOG ;
 file -> content . size = LOGICAL_BLOCK_SIZE ;
 isofile_add_entry ( iso9660 , file ) ;
 isoent = isoent_new ( file ) ;
 if ( isoent == NULL ) {
