 isoent -> virtual = 1 ;
 if ( isoent_tree ( a , & isoent ) != ARCHIVE_OK ) return ( ARCHIVE_FATAL ) ;
 iso9660 -> el_torito . catalog = isoent ;
 switch ( iso9660 -> opt . boot_type ) {
