 else if ( archive_entry_size ( entry ) <= FD_1_44M_SIZE ) iso9660 -> el_torito . media_type = BOOT_MEDIA_1_44M_DISKETTE ;
 else if ( archive_entry_size ( entry ) <= FD_2_88M_SIZE ) iso9660 -> el_torito . media_type = BOOT_MEDIA_2_88M_DISKETTE ;
 else {
