 auto mem = static_cast < ts : : StringView * > ( alloca ( sizeof ( ts : : StringView ) * n ) ) ;
 count = sm -> populate_client_protocol ( mem , n ) ;
 for ( int i = 0 ;
 i < count ;
 ++ i ) result [ i ] = mem [ i ] . ptr ( ) ;
 }
 if ( actual ) {
 * actual = count ;
 }
 return TS_SUCCESS ;
 }

static inline void vc1_pred_mv ( VC1Context * v , int n , int dmv_x , int dmv_y , int mv1 , int r_x , int r_y , uint8_t * is_intra , int pred_flag , int dir ) {
