 s -> current_picture . f . motion_val [ 1 ] [ xy + v -> blocks_off ] [ 0 ] = 0 ;
 s -> current_picture . f . motion_val [ 1 ] [ xy + v -> blocks_off ] [ 1 ] = 0 ;
