 s -> current_picture . f . motion_val [ 1 ] [ xy + wrap ] [ 0 ] = 0 ;
 s -> current_picture . f . motion_val [ 1 ] [ xy + wrap + v -> blocks_off ] [ 1 ] = 0 ;
 s -> current_picture . f . motion_val [ 1 ] [ xy + wrap + 1 + v -> blocks_off ] [ 0 ] = 0 ;
