 px = field_predC [ 0 ] ;
 py = field_predC [ 1 ] ;
 }
 else if ( b_valid ) {
 px = field_predB [ 0 ] ;
 py = field_predB [ 1 ] ;
 }
 else {
 px = 0 ;
 py = 0 ;
 }
 if ( num_samefield + num_oppfield > 1 ) {
 px = mid_pred ( field_predA [ 0 ] , field_predB [ 0 ] , field_predC [ 0 ] ) ;
 py = mid_pred ( field_predA [ 1 ] , field_predB [ 1 ] , field_predC [ 1 ] ) ;
 }
 if ( ! v -> field_mode ) {
 int qx , qy , X , Y ;
 qx = ( s -> mb_x << 6 ) + ( ( n == 1 || n == 3 ) ? 32 : 0 ) ;
 qy = ( s -> mb_y << 6 ) + ( ( n == 2 || n == 3 ) ? 32 : 0 ) ;
