 else sum = FFABS ( px - field_predA [ 0 ] ) + FFABS ( py - field_predA [ 1 ] ) ;
 if ( sum > hybridmv_thresh ) {
 if ( get_bits1 ( & s -> gb ) ) {
 px = field_predA [ 0 ] ;
 py = field_predA [ 1 ] ;
 }
 else {
 px = field_predC [ 0 ] ;
 py = field_predC [ 1 ] ;
 }
 }
 else {
 if ( is_intra [ xy - 1 ] ) sum = FFABS ( px ) + FFABS ( py ) ;
 else sum = FFABS ( px - field_predC [ 0 ] ) + FFABS ( py - field_predC [ 1 ] ) ;
 if ( sum > hybridmv_thresh ) {
 if ( get_bits1 ( & s -> gb ) ) {
 px = field_predA [ 0 ] ;
 py = field_predA [ 1 ] ;
 }
 else {
 px = field_predC [ 0 ] ;
 py = field_predC [ 1 ] ;
 }
 }
 }
 }
 }
