static int synth_superframe ( AVCodecContext * ctx , AVFrame * frame , int * got_frame_ptr ) {
 WMAVoiceContext * s = ctx -> priv_data ;
 GetBitContext * gb = & s -> gb , s_gb ;
 int n , res , n_samples = 480 ;
 double lsps [ MAX_FRAMES ] [ MAX_LSPS ] ;
 const double * mean_lsf = s -> lsps == 16 ? wmavoice_mean_lsf16 [ s -> lsp_def_mode ] : wmavoice_mean_lsf10 [ s -> lsp_def_mode ] ;
 float excitation [ MAX_SIGNAL_HISTORY + MAX_SFRAMESIZE + 12 ] ;
 float synth [ MAX_LSPS + MAX_SFRAMESIZE ] ;
 float * samples ;
 memcpy ( synth , s -> synth_history , s -> lsps * sizeof ( * synth ) ) ;
 memcpy ( excitation , s -> excitation_history , s -> history_nsamples * sizeof ( * excitation ) ) ;
 if ( s -> sframe_cache_size > 0 ) {
 gb = & s_gb ;
 init_get_bits ( gb , s -> sframe_cache , s -> sframe_cache_size ) ;
 s -> sframe_cache_size = 0 ;
 }
 if ( ( res = check_bits_for_superframe ( gb , s ) ) == 1 ) {
 * got_frame_ptr = 0 ;
 return 1 ;
 }
 if ( ! get_bits1 ( gb ) ) {
 av_log_missing_feature ( ctx , "WMAPro-in-WMAVoice" , 1 ) ;
 return AVERROR_PATCHWELCOME ;
 }
 if ( get_bits1 ( gb ) ) {
 if ( ( n_samples = get_bits ( gb , 12 ) ) > 480 ) {
 av_log ( ctx , AV_LOG_ERROR , "Superframe encodes >480 samples (%d), not allowed\n" , n_samples ) ;
 return - 1 ;
 }
 }
 if ( s -> has_residual_lsps ) {
 double prev_lsps [ MAX_LSPS ] , a1 [ MAX_LSPS * 2 ] , a2 [ MAX_LSPS * 2 ] ;
 for ( n = 0 ;
 n < s -> lsps ;
 n ++ ) prev_lsps [ n ] = s -> prev_lsps [ n ] - mean_lsf [ n ] ;
 if ( s -> lsps == 10 ) {
 dequant_lsp10r ( gb , lsps [ 2 ] , prev_lsps , a1 , a2 , s -> lsp_q_mode ) ;
 }
 else dequant_lsp16r ( gb , lsps [ 2 ] , prev_lsps , a1 , a2 , s -> lsp_q_mode ) ;
 for ( n = 0 ;
 n < s -> lsps ;
 n ++ ) {
 lsps [ 0 ] [ n ] = mean_lsf [ n ] + ( a1 [ n ] - a2 [ n * 2 ] ) ;
 lsps [ 1 ] [ n ] = mean_lsf [ n ] + ( a1 [ s -> lsps + n ] - a2 [ n * 2 + 1 ] ) ;
 lsps [ 2 ] [ n ] += mean_lsf [ n ] ;
 }
 for ( n = 0 ;
 n < 3 ;
 n ++ ) stabilize_lsps ( lsps [ n ] , s -> lsps ) ;
 }
 frame -> nb_samples = 480 ;
 if ( ( res = ff_get_buffer ( ctx , frame , 0 ) ) < 0 ) {
 av_log ( ctx , AV_LOG_ERROR , "get_buffer() failed\n" ) ;
 return res ;
 }
 frame -> nb_samples = n_samples ;
 samples = ( float * ) frame -> data [ 0 ] ;
 for ( n = 0 ;
 n < 3 ;
 n ++ ) {
 if ( ! s -> has_residual_lsps ) {
 int m ;
 if ( s -> lsps == 10 ) {
 dequant_lsp10i ( gb , lsps [ n ] ) ;
 }
 else dequant_lsp16i ( gb , lsps [ n ] ) ;
 for ( m = 0 ;
 m < s -> lsps ;
 m ++ ) lsps [ n ] [ m ] += mean_lsf [ m ] ;
 stabilize_lsps ( lsps [ n ] , s -> lsps ) ;
 }
 if ( ( res = synth_frame ( ctx , gb , n , & samples [ n * MAX_FRAMESIZE ] , lsps [ n ] , n == 0 ? s -> prev_lsps : lsps [ n - 1 ] , & excitation [ s -> history_nsamples + n * MAX_FRAMESIZE ] , & synth [ s -> lsps + n * MAX_FRAMESIZE ] ) ) ) {
 * got_frame_ptr = 0 ;
 return res ;
 }
 }
 if ( get_bits1 ( gb ) ) {
 res = get_bits ( gb , 4 ) ;
 skip_bits ( gb , 10 * ( res + 1 ) ) ;
 }
 * got_frame_ptr = 1 ;
 memcpy ( s -> prev_lsps , lsps [ 2 ] , s -> lsps * sizeof ( * s -> prev_lsps ) ) ;
 memcpy ( s -> synth_history , & synth [ MAX_SFRAMESIZE ] , s -> lsps * sizeof ( * synth ) ) ;
 memcpy ( s -> excitation_history , & excitation [ MAX_SFRAMESIZE ] , s -> history_nsamples * sizeof ( * excitation ) ) ;
 if ( s -> do_apf ) memmove ( s -> zero_exc_pf , & s -> zero_exc_pf [ MAX_SFRAMESIZE ] , s -> history_nsamples * sizeof ( * s -> zero_exc_pf ) ) ;
 return 0 ;
 }

static int decode_slice ( MpegEncContext * s ) {
 const int part_mask = s -> partitioned_frame ? ( ER_AC_END | ER_AC_ERROR ) : 0x7F ;
 const int mb_size = 16 ;
 s -> last_resync_gb = s -> gb ;
 s -> first_slice_line = 1 ;
 s -> resync_mb_x = s -> mb_x ;
 s -> resync_mb_y = s -> mb_y ;
 ff_set_qscale ( s , s -> qscale ) ;
 if ( s -> avctx -> hwaccel ) {
 const uint8_t * start = s -> gb . buffer + get_bits_count ( & s -> gb ) / 8 ;
 const uint8_t * end = ff_h263_find_resync_marker ( start + 1 , s -> gb . buffer_end ) ;
 skip_bits_long ( & s -> gb , 8 * ( end - start ) ) ;
 return s -> avctx -> hwaccel -> decode_slice ( s -> avctx , start , end - start ) ;
 }
 if ( s -> partitioned_frame ) {
 const int qscale = s -> qscale ;
 if ( CONFIG_MPEG4_DECODER && s -> codec_id == AV_CODEC_ID_MPEG4 ) {
 if ( ff_mpeg4_decode_partitions ( s ) < 0 ) return - 1 ;
 }
 s -> first_slice_line = 1 ;
 s -> mb_x = s -> resync_mb_x ;
 s -> mb_y = s -> resync_mb_y ;
 ff_set_qscale ( s , qscale ) ;
 }
 for ( ;
 s -> mb_y < s -> mb_height ;
 s -> mb_y ++ ) {
 if ( s -> msmpeg4_version ) {
 if ( s -> resync_mb_y + s -> slice_height == s -> mb_y ) {
 ff_er_add_slice ( & s -> er , s -> resync_mb_x , s -> resync_mb_y , s -> mb_x - 1 , s -> mb_y , ER_MB_END ) ;
 return 0 ;
 }
 }
 if ( s -> msmpeg4_version == 1 ) {
 s -> last_dc [ 0 ] = s -> last_dc [ 1 ] = s -> last_dc [ 2 ] = 128 ;
 }
 ff_init_block_index ( s ) ;
 for ( ;
 s -> mb_x < s -> mb_width ;
 s -> mb_x ++ ) {
 int ret ;
 ff_update_block_index ( s ) ;
 if ( s -> resync_mb_x == s -> mb_x && s -> resync_mb_y + 1 == s -> mb_y ) {
 s -> first_slice_line = 0 ;
 }
 s -> mv_dir = MV_DIR_FORWARD ;
 s -> mv_type = MV_TYPE_16X16 ;
 av_dlog ( s , "%d %d %06X\n" , ret , get_bits_count ( & s -> gb ) , show_bits ( & s -> gb , 24 ) ) ;
 ret = s -> decode_mb ( s , s -> block ) ;
 if ( s -> pict_type != AV_PICTURE_TYPE_B ) ff_h263_update_motion_val ( s ) ;
 if ( ret < 0 ) {
 const int xy = s -> mb_x + s -> mb_y * s -> mb_stride ;
 if ( ret == SLICE_END ) {
 ff_MPV_decode_mb ( s , s -> block ) ;
 if ( s -> loop_filter ) ff_h263_loop_filter ( s ) ;
 ff_er_add_slice ( & s -> er , s -> resync_mb_x , s -> resync_mb_y , s -> mb_x , s -> mb_y , ER_MB_END & part_mask ) ;
 s -> padding_bug_score -- ;
 if ( ++ s -> mb_x >= s -> mb_width ) {
 s -> mb_x = 0 ;
 ff_mpeg_draw_horiz_band ( s , s -> mb_y * mb_size , mb_size ) ;
 ff_MPV_report_decode_progress ( s ) ;
 s -> mb_y ++ ;
 }
 return 0 ;
 }
 else if ( ret == SLICE_NOEND ) {
 av_log ( s -> avctx , AV_LOG_ERROR , "Slice mismatch at MB: %d\n" , xy ) ;
 ff_er_add_slice ( & s -> er , s -> resync_mb_x , s -> resync_mb_y , s -> mb_x + 1 , s -> mb_y , ER_MB_END & part_mask ) ;
 return - 1 ;
 }
 av_log ( s -> avctx , AV_LOG_ERROR , "Error at MB: %d\n" , xy ) ;
 ff_er_add_slice ( & s -> er , s -> resync_mb_x , s -> resync_mb_y , s -> mb_x , s -> mb_y , ER_MB_ERROR & part_mask ) ;
 return - 1 ;
 }
 ff_MPV_decode_mb ( s , s -> block ) ;
 if ( s -> loop_filter ) ff_h263_loop_filter ( s ) ;
 }
 ff_mpeg_draw_horiz_band ( s , s -> mb_y * mb_size , mb_size ) ;
 ff_MPV_report_decode_progress ( s ) ;
 s -> mb_x = 0 ;
 }
 assert ( s -> mb_x == 0 && s -> mb_y == s -> mb_height ) ;
 if ( s -> codec_id == AV_CODEC_ID_MPEG4 && ( s -> workaround_bugs & FF_BUG_AUTODETECT ) && get_bits_left ( & s -> gb ) >= 48 && show_bits ( & s -> gb , 24 ) == 0x4010 && ! s -> data_partitioning ) s -> padding_bug_score += 32 ;
 if ( s -> codec_id == AV_CODEC_ID_MPEG4 && ( s -> workaround_bugs & FF_BUG_AUTODETECT ) && get_bits_left ( & s -> gb ) >= 0 && get_bits_left ( & s -> gb ) < 48 && ! s -> data_partitioning ) {
 const int bits_count = get_bits_count ( & s -> gb ) ;
 const int bits_left = s -> gb . size_in_bits - bits_count ;
 if ( bits_left == 0 ) {
 s -> padding_bug_score += 16 ;
 }
 else if ( bits_left != 1 ) {
 int v = show_bits ( & s -> gb , 8 ) ;
 v |= 0x7F >> ( 7 - ( bits_count & 7 ) ) ;
 if ( v == 0x7F && bits_left <= 8 ) s -> padding_bug_score -- ;
 else if ( v == 0x7F && ( ( get_bits_count ( & s -> gb ) + 8 ) & 8 ) && bits_left <= 16 ) s -> padding_bug_score += 4 ;
