 }
 }
 if ( s -> workaround_bugs & FF_BUG_AUTODETECT ) {
 if ( s -> padding_bug_score > - 2 && ! s -> data_partitioning ) s -> workaround_bugs |= FF_BUG_NO_PADDING ;
 else s -> workaround_bugs &= ~ FF_BUG_NO_PADDING ;
 }
 if ( s -> msmpeg4_version || ( s -> workaround_bugs & FF_BUG_NO_PADDING ) ) {
