 if ( s -> msmpeg4_version && s -> pict_type == AV_PICTURE_TYPE_I ) max_extra += 17 ;
 if ( ( s -> workaround_bugs & FF_BUG_NO_PADDING ) && ( s -> err_recognition & AV_EF_BUFFER ) ) max_extra += 48 ;
 else if ( ( s -> workaround_bugs & FF_BUG_NO_PADDING ) ) max_extra += 256 * 256 * 256 * 64 ;
 if ( left > max_extra ) {
 av_log ( s -> avctx , AV_LOG_ERROR , "discarding %d junk bits at end, next would be %X\n" , left , show_bits ( & s -> gb , 24 ) ) ;
 }
 else if ( left < 0 ) {
 av_log ( s -> avctx , AV_LOG_ERROR , "overreading %d bits\n" , - left ) ;
 }
 else ff_er_add_slice ( & s -> er , s -> resync_mb_x , s -> resync_mb_y , s -> mb_x - 1 , s -> mb_y , ER_MB_END ) ;
 return 0 ;
 }
 av_log ( s -> avctx , AV_LOG_ERROR , "slice end not reached but screenspace end (%d left %06X, score= %d)\n" , get_bits_left ( & s -> gb ) , show_bits ( & s -> gb , 24 ) , s -> padding_bug_score ) ;
 ff_er_add_slice ( & s -> er , s -> resync_mb_x , s -> resync_mb_y , s -> mb_x , s -> mb_y , ER_MB_END & part_mask ) ;
 return - 1 ;
