 }
 rc -> next_key_frame_forced = 1 ;
 }
 else if ( twopass -> stats_in == twopass -> stats_in_end || rc -> frames_to_key >= cpi -> oxcf . key_freq ) {
 rc -> next_key_frame_forced = 1 ;
 }
 else {
 rc -> next_key_frame_forced = 0 ;
 }
