 decay_accumulator *= loop_decay_rate ;
 decay_accumulator = MAX ( decay_accumulator , MIN_DECAY_FACTOR ) ;
 av_decay_accumulator += decay_accumulator ;
 ++ loop_decay_counter ;
 }
 boost_score += ( decay_accumulator * frame_boost ) ;
