 }
 hashnames [ ] = {
 {
 "sha1" , GCRY_MD_SHA1 }
 , {
 "md5" , GCRY_MD_MD5 }
 , {
 "sha256" , GCRY_MD_SHA256 }
 , {
 "ripemd160" , GCRY_MD_RMD160 }
 , {
 "rmd160" , GCRY_MD_RMD160 }
 , {
 "sha384" , GCRY_MD_SHA384 }
 , {
