 , {
 "tiger" , GCRY_MD_TIGER }
 , {
 "haval" , GCRY_MD_HAVAL }
 , {
 NULL , 0 }
 }
 ;
 int algo ;
 int i ;
 for ( i = 0 ;
 hashnames [ i ] . name ;
 i ++ ) {
 if ( strlen ( hashnames [ i ] . name ) == n && ! memcmp ( hashnames [ i ] . name , s , n ) ) break ;
