 assert ( num >= 0 ) ;
 if ( num <= 0 ) return ( ( BN_ULONG ) 0 ) ;
 bl = LBITS ( w ) ;
 bh = HBITS ( w ) ;
 # ifndef OPENSSL_SMALL_FOOTPRINT while ( num & ~ 3 ) {
 mul ( rp [ 0 ] , ap [ 0 ] , bl , bh , carry ) ;
 mul ( rp [ 1 ] , ap [ 1 ] , bl , bh , carry ) ;
 mul ( rp [ 2 ] , ap [ 2 ] , bl , bh , carry ) ;
 mul ( rp [ 3 ] , ap [ 3 ] , bl , bh , carry ) ;
 ap += 4 ;
 rp += 4 ;
 num -= 4 ;
 }
 # endif while ( num ) {
 mul ( rp [ 0 ] , ap [ 0 ] , bl , bh , carry ) ;
 ap ++ ;
 rp ++ ;
 num -- ;
 }
 return ( carry ) ;
 }

