 if ( lspf [ 9 ] <= .70 || lspf [ 9 ] >= .97 ) return - 1 ;
 for ( i = 3 ;
 i < 10 ;
 i ++ ) if ( fabs ( lspf [ i ] - lspf [ i - 2 ] ) < .08 ) return - 1 ;
 }
 else {
 if ( lspf [ 9 ] <= .66 || lspf [ 9 ] >= .985 ) return - 1 ;
 for ( i = 4 ;
 i < 10 ;
 i ++ ) if ( fabs ( lspf [ i ] - lspf [ i - 4 ] ) < .0931 ) return - 1 ;
 }
 }
