 }

void generate_filename ( const char * pattern , char * out , size_t q_len , unsigned int d_w , unsigned int d_h , unsigned int frame_in ) {
 const char * p = pattern ;
 char * q = out ;
 do {
 char * next_pat = strchr ( p , '%' ) ;
 if ( p == next_pat ) {
 size_t pat_len ;
 q [ q_len - 1 ] = '\0' ;
 switch ( p [ 1 ] ) {
 case 'w' : snprintf ( q , q_len - 1 , "%d" , d_w ) ;
 break ;
 case 'h' : snprintf ( q , q_len - 1 , "%d" , d_h ) ;
 break ;
 case '1' : snprintf ( q , q_len - 1 , "%d" , frame_in ) ;
 break ;
 case '2' : snprintf ( q , q_len - 1 , "%02d" , frame_in ) ;
 break ;
 case '3' : snprintf ( q , q_len - 1 , "%03d" , frame_in ) ;
 break ;
 case '4' : snprintf ( q , q_len - 1 , "%04d" , frame_in ) ;
 break ;
 case '5' : snprintf ( q , q_len - 1 , "%05d" , frame_in ) ;
 break ;
 case '6' : snprintf ( q , q_len - 1 , "%06d" , frame_in ) ;
 break ;
 case '7' : snprintf ( q , q_len - 1 , "%07d" , frame_in ) ;
 break ;
 case '8' : snprintf ( q , q_len - 1 , "%08d" , frame_in ) ;
 break ;
 case '9' : snprintf ( q , q_len - 1 , "%09d" , frame_in ) ;
 break ;
 default : die ( "Unrecognized pattern %%%c\n" , p [ 1 ] ) ;
 break ;
 }
 pat_len = strlen ( q ) ;
 if ( pat_len >= q_len - 1 ) die ( "Output filename too long.\n" ) ;
 q += pat_len ;
 p += 2 ;
 q_len -= pat_len ;
 }
 else {
 size_t copy_len ;
 if ( ! next_pat ) copy_len = strlen ( p ) ;
 else copy_len = next_pat - p ;
 if ( copy_len >= q_len - 1 ) die ( "Output filename too long.\n" ) ;
 memcpy ( q , p , copy_len ) ;
 q [ copy_len ] = '\0' ;
 q += copy_len ;
 p += copy_len ;
 q_len -= copy_len ;
 }
 }
 while ( * p ) ;
 }

enum ImapAuthRes imap_auth_login ( struct ImapData * idata , const char * method ) {
 char q_user [ SHORT_STRING ] , q_pass [ SHORT_STRING ] ;
 char buf [ STRING ] ;
 int rc ;
 if ( mutt_bit_isset ( idata -> capabilities , LOGINDISABLED ) ) {
 mutt_message ( _ ( "LOGIN disabled on this server." ) ) ;
 return IMAP_AUTH_UNAVAIL ;
 }
 if ( mutt_account_getuser ( & idata -> conn -> account ) < 0 ) return IMAP_AUTH_FAILURE ;
 if ( mutt_account_getpass ( & idata -> conn -> account ) < 0 ) return IMAP_AUTH_FAILURE ;
 mutt_message ( _ ( "Logging in..." ) ) ;
 imap_quote_string ( q_user , sizeof ( q_user ) , idata -> conn -> account . user ) ;
 imap_quote_string ( q_pass , sizeof ( q_pass ) , idata -> conn -> account . pass ) ;
 if ( DebugLevel < IMAP_LOG_PASS ) mutt_debug ( 2 , "Sending LOGIN command for %s...\n" , idata -> conn -> account . user ) ;
 snprintf ( buf , sizeof ( buf ) , "LOGIN %s %s" , q_user , q_pass ) ;
 rc = imap_exec ( idata , buf , IMAP_CMD_FAIL_OK | IMAP_CMD_PASS ) ;
 if ( ! rc ) {
