static inline void sub_left_prediction_bgr32 ( HYuvContext * s , uint8_t * dst , const uint8_t * src , int w , int * red , int * green , int * blue , int * alpha ) {
 int i ;
 int r , g , b , a ;
 r = * red ;
 g = * green ;
 b = * blue ;
 a = * alpha ;
 for ( i = 0 ;
 i < FFMIN ( w , 4 ) ;
 i ++ ) {
