 type = bp [ 1 ] ;
 ND_PRINT ( ( ndo , " %s" , tok2str ( pimv1_type_str , "[type %u]" , type ) ) ) ;
 switch ( type ) {
 case PIMV1_TYPE_QUERY : if ( ND_TTEST ( bp [ 8 ] ) ) {
 switch ( bp [ 8 ] >> 4 ) {
 case 0 : ND_PRINT ( ( ndo , " Dense-mode" ) ) ;
 break ;
 case 1 : ND_PRINT ( ( ndo , " Sparse-mode" ) ) ;
 break ;
 case 2 : ND_PRINT ( ( ndo , " Sparse-Dense-mode" ) ) ;
