 memmove ( cx_data , ctx -> pending_cx_data , ctx -> pending_cx_data_sz ) ;
 ctx -> pending_cx_data = cx_data ;
 cx_data += ctx -> pending_cx_data_sz ;
 cx_data_sz -= ctx -> pending_cx_data_sz ;
 if ( cx_data_sz < ctx -> cx_data_sz / 2 ) {
 ctx -> base . err_detail = "Compressed data buffer too small" ;
 return VPX_CODEC_ERROR ;
 }
 }
 while ( cx_data_sz >= ctx -> cx_data_sz / 2 && - 1 != vp9_get_compressed_data ( cpi , & lib_flags , & size , cx_data , & dst_time_stamp , & dst_end_time_stamp , ! img ) ) {
 if ( size ) {
 vpx_codec_cx_pkt_t pkt ;
 # if CONFIG_SPATIAL_SVC if ( is_two_pass_svc ( cpi ) ) cpi -> svc . layer_context [ cpi -> svc . spatial_layer_id ] . layer_size += size ;
 # endif if ( ! cpi -> common . show_frame # if CONFIG_SPATIAL_SVC || ( is_two_pass_svc ( cpi ) && cpi -> svc . spatial_layer_id < cpi -> svc . number_spatial_layers - 1 ) # endif ) {
 if ( ctx -> pending_cx_data == 0 ) ctx -> pending_cx_data = cx_data ;
 ctx -> pending_cx_data_sz += size ;
 ctx -> pending_frame_sizes [ ctx -> pending_frame_count ++ ] = size ;
 ctx -> pending_frame_magnitude |= size ;
 cx_data += size ;
 cx_data_sz -= size ;
 continue ;
 }
 pkt . kind = VPX_CODEC_CX_FRAME_PKT ;
 pkt . data . frame . pts = ticks_to_timebase_units ( timebase , dst_time_stamp ) ;
 pkt . data . frame . duration = ( unsigned long ) ticks_to_timebase_units ( timebase , dst_end_time_stamp - dst_time_stamp ) ;
 pkt . data . frame . flags = get_frame_pkt_flags ( cpi , lib_flags ) ;
 if ( ctx -> pending_cx_data ) {
 ctx -> pending_frame_sizes [ ctx -> pending_frame_count ++ ] = size ;
 ctx -> pending_frame_magnitude |= size ;
 ctx -> pending_cx_data_sz += size ;
 size += write_superframe_index ( ctx ) ;
 pkt . data . frame . buf = ctx -> pending_cx_data ;
 pkt . data . frame . sz = ctx -> pending_cx_data_sz ;
 ctx -> pending_cx_data = NULL ;
 ctx -> pending_cx_data_sz = 0 ;
 ctx -> pending_frame_count = 0 ;
 ctx -> pending_frame_magnitude = 0 ;
 }
 else {
 pkt . data . frame . buf = cx_data ;
 pkt . data . frame . sz = size ;
 }
 pkt . data . frame . partition_id = - 1 ;
 vpx_codec_pkt_list_add ( & ctx -> pkt_list . head , & pkt ) ;
 cx_data += size ;
 cx_data_sz -= size ;
 # if CONFIG_SPATIAL_SVC if ( is_two_pass_svc ( cpi ) ) {
 vpx_codec_cx_pkt_t pkt ;
 int i ;
 vp9_zero ( pkt ) ;
 pkt . kind = VPX_CODEC_SPATIAL_SVC_LAYER_SIZES ;
 for ( i = 0 ;
 i < cpi -> svc . number_spatial_layers ;
 ++ i ) {
 pkt . data . layer_sizes [ i ] = cpi -> svc . layer_context [ i ] . layer_size ;
 cpi -> svc . layer_context [ i ] . layer_size = 0 ;
 }
 vpx_codec_pkt_list_add ( & ctx -> pkt_list . head , & pkt ) ;
 }
 # endif }
 }
 }
 return res ;
 }

