static void pk_transaction_get_files ( PkTransaction * transaction , GVariant * params , GDBusMethodInvocation * context ) {
 gboolean ret ;
 guint length ;
 g_autoptr ( GError ) error = NULL ;
 g_autofree gchar * * package_ids = NULL ;
 g_autofree gchar * package_ids_temp = NULL ;
 g_return_if_fail ( PK_IS_TRANSACTION ( transaction ) ) ;
 g_return_if_fail ( transaction -> priv -> tid != NULL ) ;
 g_variant_get ( params , "(^a&s)" , & package_ids ) ;
 package_ids_temp = pk_package_ids_to_string ( package_ids ) ;
 g_debug ( "GetFiles method called: %s" , package_ids_temp ) ;
 if ( ! pk_backend_is_implemented ( transaction -> priv -> backend , PK_ROLE_ENUM_GET_FILES ) ) {
 g_set_error ( & error , PK_TRANSACTION_ERROR , PK_TRANSACTION_ERROR_NOT_SUPPORTED , "GetFiles not supported by backend" ) ;
 pk_transaction_set_state ( transaction , PK_TRANSACTION_STATE_ERROR ) ;
 goto out ;
 }
 length = g_strv_length ( package_ids ) ;
 if ( length > PK_TRANSACTION_MAX_PACKAGES_TO_PROCESS ) {
 g_set_error ( & error , PK_TRANSACTION_ERROR , PK_TRANSACTION_ERROR_NUMBER_OF_PACKAGES_INVALID , "Too many packages to process (%i/%i)" , length , PK_TRANSACTION_MAX_PACKAGES_TO_PROCESS ) ;
 pk_transaction_set_state ( transaction , PK_TRANSACTION_STATE_ERROR ) ;
 goto out ;
 }
 ret = pk_package_ids_check ( package_ids ) ;
 if ( ! ret ) {
 g_set_error ( & error , PK_TRANSACTION_ERROR , PK_TRANSACTION_ERROR_PACKAGE_ID_INVALID , "The package id's '%s' are not valid" , package_ids_temp ) ;
 pk_transaction_set_state ( transaction , PK_TRANSACTION_STATE_ERROR ) ;
 goto out ;
 }
 transaction -> priv -> cached_package_ids = g_strdupv ( package_ids ) ;
 pk_transaction_set_role ( transaction , PK_ROLE_ENUM_GET_FILES ) ;
 pk_transaction_set_state ( transaction , PK_TRANSACTION_STATE_READY ) ;
 out : pk_transaction_dbus_return ( context , error ) ;
 }

static int evport_add ( void * arg , struct event * ev ) {
 struct evport_data * evpd = arg ;
 struct fd_info * fdi ;
 int factor ;
 check_evportop ( evpd ) ;
 if ( ev -> ev_events & EV_SIGNAL ) return ( evsignal_add ( ev ) ) ;
 factor = 1 ;
 while ( ev -> ev_fd >= factor * evpd -> ed_nevents ) factor *= 2 ;
 if ( factor > 1 ) {
 if ( - 1 == grow ( evpd , factor ) ) {
 return ( - 1 ) ;
 }
 }
 fdi = & evpd -> ed_fds [ ev -> ev_fd ] ;
 if ( ev -> ev_events & EV_READ ) fdi -> fdi_revt = ev ;
 if ( ev -> ev_events & EV_WRITE ) fdi -> fdi_wevt = ev ;
 return reassociate ( evpd , fdi , ev -> ev_fd ) ;
 }

