static int dissect_type_bitmap ( proto_tree * rr_tree , tvbuff_t * tvb , int cur_offset , int rr_len ) {
 int mask , blockbase , blocksize ;
 int i , initial_offset , rr_type ;
 guint8 bits ;
 initial_offset = cur_offset ;
 while ( rr_len != 0 ) {
 blockbase = tvb_get_guint8 ( tvb , cur_offset ) ;
 blocksize = tvb_get_guint8 ( tvb , cur_offset + 1 ) ;
 cur_offset += 2 ;
 rr_len -= 2 ;
 rr_type = blockbase * 256 ;
 for ( ;
 blocksize ;
 blocksize -- ) {
 bits = tvb_get_guint8 ( tvb , cur_offset ) ;
 mask = 1 << 7 ;
 for ( i = 0 ;
 i < 8 ;
 i ++ ) {
 if ( bits & mask ) {
 proto_tree_add_uint_format ( rr_tree , hf_dns_rr_type , tvb , cur_offset , 1 , rr_type , "RR type in bit map: %s" , val_to_str_ext ( rr_type , & dns_types_description_vals_ext , "Unknown (%d)" ) ) ;
 }
 mask >>= 1 ;
 rr_type ++ ;
 }
 cur_offset += 1 ;
 rr_len -= 1 ;
 }
 }
 return ( initial_offset - cur_offset ) ;
 }

static uint64_t pxa2xx_rtc_read ( void * opaque , hwaddr addr , unsigned size ) {
 PXA2xxRTCState * s = ( PXA2xxRTCState * ) opaque ;
 switch ( addr ) {
 case RTTR : return s -> rttr ;
 case RTSR : return s -> rtsr ;
 case RTAR : return s -> rtar ;
 case RDAR1 : return s -> rdar1 ;
 case RDAR2 : return s -> rdar2 ;
 case RYAR1 : return s -> ryar1 ;
 case RYAR2 : return s -> ryar2 ;
 case SWAR1 : return s -> swar1 ;
 case SWAR2 : return s -> swar2 ;
 case PIAR : return s -> piar ;
 case RCNR : return s -> last_rcnr + ( ( qemu_get_clock_ms ( rtc_clock ) - s -> last_hz ) << 15 ) / ( 1000 * ( ( s -> rttr & 0xffff ) + 1 ) ) ;
 case RDCR : return s -> last_rdcr + ( ( qemu_get_clock_ms ( rtc_clock ) - s -> last_hz ) << 15 ) / ( 1000 * ( ( s -> rttr & 0xffff ) + 1 ) ) ;
 case RYCR : return s -> last_rycr ;
 case SWCR : if ( s -> rtsr & ( 1 << 12 ) ) return s -> last_swcr + ( qemu_get_clock_ms ( rtc_clock ) - s -> last_sw ) / 10 ;
 else return s -> last_swcr ;
 default : printf ( "%s: Bad register " REG_FMT "\n" , __FUNCTION__ , addr ) ;
 break ;
 }
 return 0 ;
 }

