 wmem_free ( NULL , tmp_str ) ;
 }
 if ( hfinfo -> bitmask != 0 ) g_error ( "Field '%s' (%s) is an %s but has a bitmask\n" , hfinfo -> name , hfinfo -> abbrev , ftype_name ( hfinfo -> type ) ) ;
 break ;
 case FT_STRING : case FT_STRINGZ : case FT_UINT_STRING : case FT_STRINGZPAD : switch ( hfinfo -> display ) {
 case STR_ASCII : case STR_UNICODE : break ;
 default : tmp_str = val_to_str_wmem ( NULL , hfinfo -> display , hf_display , "(Unknown: 0x%x)" ) ;
 g_error ( "Field '%s' (%s) is an string value (%s)" " but is being displayed as %s\n" , hfinfo -> name , hfinfo -> abbrev , ftype_name ( hfinfo -> type ) , tmp_str ) ;
 wmem_free ( NULL , tmp_str ) ;
 }
 if ( hfinfo -> bitmask != 0 ) g_error ( "Field '%s' (%s) is an %s but has a bitmask\n" , hfinfo -> name , hfinfo -> abbrev , ftype_name ( hfinfo -> type ) ) ;
 if ( hfinfo -> strings != NULL ) g_error ( "Field '%s' (%s) is an %s but has a strings value\n" , hfinfo -> name , hfinfo -> abbrev , ftype_name ( hfinfo -> type ) ) ;
 break ;
 case FT_IPv4 : switch ( hfinfo -> display ) {
 case BASE_NONE : case BASE_NETMASK : break ;
 default : tmp_str = val_to_str_wmem ( NULL , hfinfo -> display , hf_display , "(Unknown: 0x%x)" ) ;
 g_error ( "Field '%s' (%s) is an IPv4 value (%s)" " but is being displayed as %s\n" , hfinfo -> name , hfinfo -> abbrev , ftype_name ( hfinfo -> type ) , tmp_str ) ;
 wmem_free ( NULL , tmp_str ) ;
 break ;
 }
 break ;
 default : if ( hfinfo -> display != BASE_NONE ) {
 tmp_str = val_to_str_wmem ( NULL , hfinfo -> display , hf_display , "(Bit count: %d)" ) ;
 g_error ( "Field '%s' (%s) is an %s but is being displayed as %s instead of BASE_NONE\n" , hfinfo -> name , hfinfo -> abbrev , ftype_name ( hfinfo -> type ) , tmp_str ) ;
 wmem_free ( NULL , tmp_str ) ;
 }
 if ( hfinfo -> bitmask != 0 ) g_error ( "Field '%s' (%s) is an %s but has a bitmask\n" , hfinfo -> name , hfinfo -> abbrev , ftype_name ( hfinfo -> type ) ) ;
 if ( hfinfo -> strings != NULL ) g_error ( "Field '%s' (%s) is an %s but has a strings value\n" , hfinfo -> name , hfinfo -> abbrev , ftype_name ( hfinfo -> type ) ) ;
 break ;
 }
 }

static void t42_parse_sfnts ( T42_Face face , T42_Loader loader ) {
 T42_Parser parser = & loader -> parser ;
 FT_Memory memory = parser -> root . memory ;
 FT_Byte * cur ;
 FT_Byte * limit = parser -> root . limit ;
 FT_Error error ;
 FT_Int num_tables = 0 ;
 FT_ULong count , ttf_size = 0 ;
 FT_Long n , string_size , old_string_size , real_size ;
 FT_Byte * string_buf = NULL ;
 FT_Bool allocated = 0 ;
 T42_Load_Status status ;
 T1_Skip_Spaces ( parser ) ;
 if ( parser -> root . cursor >= limit || * parser -> root . cursor ++ != '[' ) {
 FT_ERROR ( ( "t42_parse_sfnts: can't find begin of sfnts vector\n" ) ) ;
 error = FT_THROW ( Invalid_File_Format ) ;
 goto Fail ;
 }
 T1_Skip_Spaces ( parser ) ;
 status = BEFORE_START ;
 string_size = 0 ;
 old_string_size = 0 ;
 count = 0 ;
 while ( parser -> root . cursor < limit ) {
 cur = parser -> root . cursor ;
 if ( * cur == ']' ) {
 parser -> root . cursor ++ ;
 goto Exit ;
 }
 else if ( * cur == '<' ) {
 T1_Skip_PS_Token ( parser ) ;
 if ( parser -> root . error ) goto Exit ;
 string_size = ( FT_Long ) ( ( parser -> root . cursor - cur - 2 + 1 ) / 2 ) ;
 if ( FT_REALLOC ( string_buf , old_string_size , string_size ) ) goto Fail ;
 allocated = 1 ;
 parser -> root . cursor = cur ;
 ( void ) T1_ToBytes ( parser , string_buf , string_size , & real_size , 1 ) ;
 old_string_size = string_size ;
 string_size = real_size ;
 }
 else if ( ft_isdigit ( * cur ) ) {
 if ( allocated ) {
 FT_ERROR ( ( "t42_parse_sfnts: " "can't handle mixed binary and hex strings\n" ) ) ;
 error = FT_THROW ( Invalid_File_Format ) ;
 goto Fail ;
 }
 string_size = T1_ToInt ( parser ) ;
 if ( string_size < 0 ) {
 FT_ERROR ( ( "t42_parse_sfnts: invalid string size\n" ) ) ;
 error = FT_THROW ( Invalid_File_Format ) ;
 goto Fail ;
 }
 T1_Skip_PS_Token ( parser ) ;
 if ( parser -> root . error ) return ;
 string_buf = parser -> root . cursor + 1 ;
 if ( limit - parser -> root . cursor < string_size ) {
 FT_ERROR ( ( "t42_parse_sfnts: too many binary data\n" ) ) ;
 error = FT_THROW ( Invalid_File_Format ) ;
 goto Fail ;
 }
 else parser -> root . cursor += string_size + 1 ;
 }
 if ( ! string_buf ) {
 FT_ERROR ( ( "t42_parse_sfnts: invalid data in sfnts array\n" ) ) ;
 error = FT_THROW ( Invalid_File_Format ) ;
 goto Fail ;
 }
 if ( ( string_size & 1 ) && string_buf [ string_size - 1 ] == 0 ) string_size -- ;
 if ( ! string_size ) {
 FT_ERROR ( ( "t42_parse_sfnts: invalid string\n" ) ) ;
 error = FT_THROW ( Invalid_File_Format ) ;
 goto Fail ;
 }
 for ( n = 0 ;
 n < string_size ;
 n ++ ) {
 switch ( status ) {
 case BEFORE_START : if ( count < 12 ) {
 face -> ttf_data [ count ++ ] = string_buf [ n ] ;
 continue ;
 }
 else {
 num_tables = 16 * face -> ttf_data [ 4 ] + face -> ttf_data [ 5 ] ;
 status = BEFORE_TABLE_DIR ;
 ttf_size = 12 + 16 * num_tables ;
 if ( FT_REALLOC ( face -> ttf_data , 12 , ttf_size ) ) goto Fail ;
 }
 case BEFORE_TABLE_DIR : if ( count < ttf_size ) {
 face -> ttf_data [ count ++ ] = string_buf [ n ] ;
 continue ;
 }
 else {
 int i ;
 FT_ULong len ;
 for ( i = 0 ;
 i < num_tables ;
 i ++ ) {
 FT_Byte * p = face -> ttf_data + 12 + 16 * i + 12 ;
 len = FT_PEEK_ULONG ( p ) ;
 ttf_size += ( len + 3 ) & ~ 3 ;
 }
 status = OTHER_TABLES ;
 face -> ttf_size = ttf_size ;
 if ( FT_REALLOC ( face -> ttf_data , 12 + 16 * num_tables , ttf_size + 1 ) ) goto Fail ;
 }
 case OTHER_TABLES : if ( count >= ttf_size ) {
 FT_ERROR ( ( "t42_parse_sfnts: too many binary data\n" ) ) ;
 error = FT_THROW ( Invalid_File_Format ) ;
 goto Fail ;
 }
 face -> ttf_data [ count ++ ] = string_buf [ n ] ;
 }
 }
 T1_Skip_Spaces ( parser ) ;
 }
 error = FT_THROW ( Invalid_File_Format ) ;
 Fail : parser -> root . error = error ;
 Exit : if ( allocated ) FT_FREE ( string_buf ) ;
 }

