 if ( render -> allocated_mv_blocks < 1 || render -> allocated_data_blocks < render -> allocated_mv_blocks * mb_block_count || render -> start_mv_blocks_num >= render -> allocated_mv_blocks || render -> next_free_data_block_num > render -> allocated_data_blocks - mb_block_count * ( render -> allocated_mv_blocks - render -> start_mv_blocks_num ) ) {
