 }
 else if ( savings > 0 ) {
 printf ( " all-unassigned sequences from prefix 0x%02lx state %ld use %ld bytes\n" , ( unsigned long ) ( ( b << 8 ) | i ) , ( long ) state , ( long ) savings ) ;
 belowSavings += savings ;
