 int error_code = SLURM_SUCCESS ;
 DEF_TIMERS ;
 requeue_msg_t * req_ptr = ( requeue_msg_t * ) msg -> data ;
 slurmctld_lock_t fed_read_lock = {
 NO_LOCK , NO_LOCK , NO_LOCK , NO_LOCK , READ_LOCK }
 ;
