 cp = getenv ( "COLORTERM" ) ;
 if ( NULL != cp ) {
 addenv ( "COLORTERM" , cp ) ;
 }
 # ifndef USE_PAM cp = getdef_str ( "ENV_TZ" ) ;
 if ( NULL != cp ) {
 addenv ( ( '/' == * cp ) ? tz ( cp ) : cp , NULL ) ;
