 break ;
 case STR_STATUS_ALL : stroke_status ( this , msg , out , TRUE , TRUE ) ;
 break ;
 case STR_STATUS_ALL_NOBLK : stroke_status ( this , msg , out , TRUE , FALSE ) ;
 break ;
 case STR_ADD_CONN : stroke_add_conn ( this , msg ) ;
