 if ( field == 1 ) {
 offset = 0 ;
 pix_stride <<= 1 ;
 }
 else if ( field == 2 ) {
 offset = pix_stride ;
 pix_stride <<= 1 ;
 }
 else {
 offset = 0 ;
 }
 if ( s -> bpp == 1 ) {
 const uint8_t * pix = ( const uint8_t * ) frame_data + offset ;
 for ( y = 0 ;
 y < p -> height * skip ;
 y += skip ) {
 for ( x = 0 ;
 x < p -> width ;
 x ++ ) {
 buf [ x ] = pix [ x ] - s -> diff_offset ;
 }
