 for ( y = 0 ;
 y < p -> height * skip ;
 y += skip ) {
 for ( x = 0 ;
 x < p -> width ;
 x ++ ) {
 buf [ x ] = pix [ x ] - s -> diff_offset ;
 }
 buf += p -> coef_stride ;
 pix += pix_stride ;
