static unsigned int delete_node ( pdf_cmap * cmap , unsigned int current ) {
 cmap_splay * tree = cmap -> tree ;
 unsigned int parent ;
 unsigned int replacement ;
 assert ( current != EMPTY ) ;
 parent = tree [ current ] . parent ;
 if ( tree [ current ] . right == EMPTY ) {
 if ( parent == EMPTY ) {
 replacement = cmap -> ttop = tree [ current ] . left ;
 }
 else if ( tree [ parent ] . left == current ) {
 replacement = tree [ parent ] . left = tree [ current ] . left ;
 }
 else {
 assert ( tree [ parent ] . right == current ) ;
 replacement = tree [ parent ] . right = tree [ current ] . left ;
 }
 if ( replacement != EMPTY ) tree [ replacement ] . parent = parent ;
 else replacement = parent ;
 }
 else if ( tree [ current ] . left == EMPTY ) {
 if ( parent == EMPTY ) {
 replacement = cmap -> ttop = tree [ current ] . right ;
 }
 else if ( tree [ parent ] . left == current ) {
 replacement = tree [ parent ] . left = tree [ current ] . right ;
 }
 else {
 assert ( tree [ parent ] . right == current ) ;
 replacement = tree [ parent ] . right = tree [ current ] . right ;
 }
 if ( replacement != EMPTY ) tree [ replacement ] . parent = parent ;
 else replacement = parent ;
 }
 else {
 int amputee = current ;
 replacement = tree [ current ] . left ;
 while ( tree [ replacement ] . right != EMPTY ) {
 amputee = replacement ;
 replacement = tree [ replacement ] . right ;
 }
 if ( amputee == current ) {
 tree [ amputee ] . left = tree [ replacement ] . left ;
 if ( tree [ amputee ] . left != EMPTY ) tree [ tree [ amputee ] . left ] . parent = amputee ;
 }
 else {
 tree [ amputee ] . right = tree [ replacement ] . left ;
 if ( tree [ amputee ] . right != EMPTY ) tree [ tree [ amputee ] . right ] . parent = amputee ;
 }
 tree [ replacement ] . parent = parent ;
 if ( parent == EMPTY ) {
 tree [ replacement ] . parent = EMPTY ;
 cmap -> ttop = replacement ;
 }
 else if ( tree [ parent ] . left == current ) tree [ parent ] . left = replacement ;
 else {
 assert ( tree [ parent ] . right == current ) ;
 tree [ parent ] . right = replacement ;
 }
 tree [ replacement ] . left = tree [ current ] . left ;
 if ( tree [ replacement ] . left != EMPTY ) tree [ tree [ replacement ] . left ] . parent = replacement ;
 tree [ replacement ] . right = tree [ current ] . right ;
 if ( tree [ replacement ] . right != EMPTY ) tree [ tree [ replacement ] . right ] . parent = replacement ;
 }
 cmap -> tlen -- ;
 if ( current != cmap -> tlen ) {
 if ( replacement == cmap -> tlen ) replacement = current ;
 tree [ current ] = tree [ cmap -> tlen ] ;
 parent = tree [ current ] . parent ;
 if ( parent == EMPTY ) cmap -> ttop = current ;
 else if ( tree [ parent ] . left == cmap -> tlen ) tree [ parent ] . left = current ;
 else {
 assert ( tree [ parent ] . right == cmap -> tlen ) ;
 tree [ parent ] . right = current ;
 }
 if ( tree [ current ] . left != EMPTY ) {
 assert ( tree [ tree [ current ] . left ] . parent == cmap -> tlen ) ;
 tree [ tree [ current ] . left ] . parent = current ;
 }
 if ( tree [ current ] . right != EMPTY ) {
 assert ( tree [ tree [ current ] . right ] . parent == cmap -> tlen ) ;
 tree [ tree [ current ] . right ] . parent = current ;
 }
 }
 return replacement ;
 }

static int qemuMonitorJSONExtractPtyPaths ( virJSONValuePtr reply , virHashTablePtr paths ) {
 virJSONValuePtr data ;
 int ret = - 1 ;
 int i ;
 if ( ! ( data = virJSONValueObjectGet ( reply , "return" ) ) ) {
 qemuReportError ( VIR_ERR_INTERNAL_ERROR , "%s" , _ ( "character device reply was missing return data" ) ) ;
 goto cleanup ;
 }
 if ( data -> type != VIR_JSON_TYPE_ARRAY ) {
 qemuReportError ( VIR_ERR_INTERNAL_ERROR , "%s" , _ ( "character device information was not an array" ) ) ;
 goto cleanup ;
 }
 for ( i = 0 ;
 i < virJSONValueArraySize ( data ) ;
 i ++ ) {
 virJSONValuePtr entry = virJSONValueArrayGet ( data , i ) ;
 const char * type ;
 const char * id ;
 if ( ! entry ) {
 qemuReportError ( VIR_ERR_INTERNAL_ERROR , "%s" , _ ( "character device information was missing array element" ) ) ;
 goto cleanup ;
 }
 if ( ! ( type = virJSONValueObjectGetString ( entry , "filename" ) ) ) {
 qemuReportError ( VIR_ERR_INTERNAL_ERROR , "%s" , _ ( "character device information was missing filename" ) ) ;
 goto cleanup ;
 }
 if ( ! ( id = virJSONValueObjectGetString ( entry , "label" ) ) ) {
 qemuReportError ( VIR_ERR_INTERNAL_ERROR , "%s" , _ ( "character device information was missing filename" ) ) ;
 goto cleanup ;
 }
 if ( STRPREFIX ( type , "pty:" ) ) {
 char * path = strdup ( type + strlen ( "pty:" ) ) ;
 if ( ! path ) {
 virReportOOMError ( ) ;
 goto cleanup ;
 }
 if ( virHashAddEntry ( paths , id , path ) < 0 ) {
 qemuReportError ( VIR_ERR_OPERATION_FAILED , _ ( "failed to save chardev path '%s'" ) , path ) ;
 VIR_FREE ( path ) ;
 goto cleanup ;
 }
 }
 }
 ret = 0 ;
 cleanup : return ret ;
 }

