 s -> dsp . put_signed_pixels_clamped ( v -> block [ v -> topleft_blk_idx ] [ 0 ] , s -> dest [ 0 ] - 16 * s -> linesize - 16 , stride_y ) ;
 s -> dsp . put_signed_pixels_clamped ( v -> block [ v -> topleft_blk_idx ] [ 1 ] , s -> dest [ 0 ] - 16 * s -> linesize - 8 , stride_y ) ;
 s -> dsp . put_signed_pixels_clamped ( v -> block [ v -> topleft_blk_idx ] [ 2 ] , s -> dest [ 0 ] - v_dist * s -> linesize - 16 , stride_y ) ;
 s -> dsp . put_signed_pixels_clamped ( v -> block [ v -> topleft_blk_idx ] [ 3 ] , s -> dest [ 0 ] - v_dist * s -> linesize - 8 , stride_y ) ;
 s -> dsp . put_signed_pixels_clamped ( v -> block [ v -> topleft_blk_idx ] [ 4 ] , s -> dest [ 1 ] - 8 * s -> uvlinesize - 8 , s -> uvlinesize ) ;
 s -> dsp . put_signed_pixels_clamped ( v -> block [ v -> topleft_blk_idx ] [ 5 ] , s -> dest [ 2 ] - 8 * s -> uvlinesize - 8 , s -> uvlinesize ) ;
 }
 if ( s -> mb_x == s -> mb_width - 1 ) {
 top_mb_pos = ( s -> mb_y - 1 ) * s -> mb_stride + s -> mb_x ;
 fieldtx = v -> fieldtx_plane [ top_mb_pos ] ;
 stride_y = s -> linesize << fieldtx ;
 v_dist = fieldtx ? 15 : 8 ;
 s -> dsp . put_signed_pixels_clamped ( v -> block [ v -> top_blk_idx ] [ 0 ] , s -> dest [ 0 ] - 16 * s -> linesize , stride_y ) ;
 s -> dsp . put_signed_pixels_clamped ( v -> block [ v -> top_blk_idx ] [ 1 ] , s -> dest [ 0 ] - 16 * s -> linesize + 8 , stride_y ) ;
 s -> dsp . put_signed_pixels_clamped ( v -> block [ v -> top_blk_idx ] [ 2 ] , s -> dest [ 0 ] - v_dist * s -> linesize , stride_y ) ;
 s -> dsp . put_signed_pixels_clamped ( v -> block [ v -> top_blk_idx ] [ 3 ] , s -> dest [ 0 ] - v_dist * s -> linesize + 8 , stride_y ) ;
 s -> dsp . put_signed_pixels_clamped ( v -> block [ v -> top_blk_idx ] [ 4 ] , s -> dest [ 1 ] - 8 * s -> uvlinesize , s -> uvlinesize ) ;
