 const BLOCK_SIZE bsize = mbmi -> sb_type ;
 const int allow_hp = cm -> allow_high_precision_mv ;
 const int is_inter = is_inter_block ( mbmi ) ;
 const int is_compound = has_second_ref ( mbmi ) ;
 int skip , ref ;
 if ( seg -> update_map ) {
