 }
 else stats_config ( STATS_FREQ_FILE , curr_var -> value . s ) ;
 break ;
 case T_Ident : sys_ident = curr_var -> value . s ;
 break ;
 case T_WanderThreshold : case T_Nonvolatile : wander_threshold = curr_var -> value . d ;
 break ;
 case T_Leapfile : stats_config ( STATS_LEAP_FILE , curr_var -> value . s ) ;
 break ;
