 dcfg -> cache_trans_min = ( apr_size_t ) intval ;
 }
 charval = apr_table_get ( vartable , "maxlen" ) ;
 if ( charval != NULL ) {
 intval = apr_atoi64 ( charval ) ;
 if ( errno == ERANGE ) {
 return apr_psprintf ( cmd -> pool , "ModSecurity: SecCacheTransformations maxlen out of range: %s" , charval ) ;
