 generate_json ( buffer , Vstate , state , rb_ary_entry ( obj , i ) ) ;
 }
 state -> depth = -- depth ;
 if ( array_nl ) {
 fbuffer_append ( buffer , array_nl , array_nl_len ) ;
 if ( indent ) {
