 }
 LIBSSH2_FREE ( session , key_state -> data ) ;
 }
 dh_gex_clean_exit : key_state -> state = libssh2_NB_state_idle ;
 _libssh2_bn_free ( key_state -> g ) ;
 key_state -> g = NULL ;
 _libssh2_bn_free ( key_state -> p ) ;
