 list = g_list_next ( list ) ;
 }
 if ( callsinfo != NULL ) break ;
 }
 listGraph = g_list_next ( listGraph ) ;
 }
 if ( callsinfo == NULL ) return 0 ;
 }
 else return 0 ;
 if ( callsinfo == NULL ) {
 callsinfo = ( voip_calls_info_t * ) g_malloc0 ( sizeof ( voip_calls_info_t ) ) ;
