 if ( ( isSignal ( "ro" , pi -> signalReq ) || isSignal ( "bz" , pi -> signalReq ) ) && ( ( callsinfo -> call_state == VOIP_CALL_SETUP ) || ( callsinfo -> call_state == VOIP_RINGING ) ) ) {
