 }
 comment = g_strdup_printf ( "MGCP %s %s%s" , tmp_mgcpinfo -> endpointId , ( pi -> mgcp_type == MGCP_REQUEST ) ? "Request" : "Response" , pi -> is_duplicate ? " Duplicate" : "" ) ;
