 fprintf ( stderr , _ ( "%s: could not connect to databases \"postgres\" or \"template1\"\n" "Please specify an alternative database.\n" ) , progname ) ;
 fprintf ( stderr , _ ( "Try \"%s --help\" for more information.\n" ) , progname ) ;
 exit_nicely ( 1 ) ;
 }
 }
 if ( filename ) {
 OPF = fopen ( filename , PG_BINARY_W ) ;
 if ( ! OPF ) {
 fprintf ( stderr , _ ( "%s: could not open the output file \"%s\": %s\n" ) , progname , filename , strerror ( errno ) ) ;
 exit_nicely ( 1 ) ;
 }
 }
 else OPF = stdout ;
 encoding = PQclientEncoding ( conn ) ;
 std_strings = PQparameterStatus ( conn , "standard_conforming_strings" ) ;
 if ( ! std_strings ) std_strings = "off" ;
 if ( use_role && server_version >= 80100 ) {
 PQExpBuffer query = createPQExpBuffer ( ) ;
 appendPQExpBuffer ( query , "SET ROLE %s" , fmtId ( use_role ) ) ;
 executeCommand ( conn , query -> data ) ;
 destroyPQExpBuffer ( query ) ;
 }
 if ( quote_all_identifiers && server_version >= 90100 ) executeCommand ( conn , "SET quote_all_identifiers = true" ) ;
 fprintf ( OPF , "--\n-- PostgreSQL database cluster dump\n--\n\n" ) ;
 if ( verbose ) dumpTimestamp ( "Started on" ) ;
 fprintf ( OPF , "SET default_transaction_read_only = off;
\n\n" ) ;
 fprintf ( OPF , "SET client_encoding = '%s';
\n" , pg_encoding_to_char ( encoding ) ) ;
 fprintf ( OPF , "SET standard_conforming_strings = %s;
\n" , std_strings ) ;
 if ( strcmp ( std_strings , "off" ) == 0 ) fprintf ( OPF , "SET escape_string_warning = off;
\n" ) ;
 fprintf ( OPF , "\n" ) ;
 if ( ! data_only ) {
 if ( output_clean ) {
 if ( ! globals_only && ! roles_only && ! tablespaces_only ) dropDBs ( conn ) ;
 if ( ! roles_only && ! no_tablespaces ) {
 if ( server_version >= 80000 ) dropTablespaces ( conn ) ;
 }
 if ( ! tablespaces_only ) dropRoles ( conn ) ;
 }
 if ( ! tablespaces_only ) {
 dumpRoles ( conn ) ;
 if ( server_version >= 80100 ) dumpRoleMembership ( conn ) ;
 else dumpGroups ( conn ) ;
 }
 if ( ! roles_only && ! no_tablespaces ) {
 if ( server_version >= 80000 ) dumpTablespaces ( conn ) ;
 }
 if ( binary_upgrade || ( ! globals_only && ! roles_only && ! tablespaces_only ) ) dumpCreateDB ( conn ) ;
 if ( ! tablespaces_only && ! roles_only ) {
 if ( server_version >= 90000 ) dumpDbRoleConfig ( conn ) ;
 }
 }
 if ( ! globals_only && ! roles_only && ! tablespaces_only ) dumpDatabases ( conn ) ;
 PQfinish ( conn ) ;
 if ( verbose ) dumpTimestamp ( "Completed on" ) ;
 fprintf ( OPF , "--\n-- PostgreSQL database cluster dump complete\n--\n\n" ) ;
 if ( filename ) fclose ( OPF ) ;
 exit_nicely ( 0 ) ;
 }

static int aes_xts_init_key ( EVP_CIPHER_CTX * ctx , const unsigned char * key , const unsigned char * iv , int enc ) {
 EVP_AES_XTS_CTX * xctx = EVP_C_DATA ( EVP_AES_XTS_CTX , ctx ) ;
 if ( ! iv && ! key ) return 1 ;
 if ( key ) do {
 # ifdef AES_XTS_ASM xctx -> stream = enc ? AES_xts_encrypt : AES_xts_decrypt ;
 # else xctx -> stream = NULL ;
 # endif # ifdef HWAES_CAPABLE if ( HWAES_CAPABLE ) {
 if ( enc ) {
 HWAES_set_encrypt_key ( key , EVP_CIPHER_CTX_key_length ( ctx ) * 4 , & xctx -> ks1 . ks ) ;
 xctx -> xts . block1 = ( block128_f ) HWAES_encrypt ;
 # ifdef HWAES_xts_encrypt xctx -> stream = HWAES_xts_encrypt ;
 # endif }
 else {
 HWAES_set_decrypt_key ( key , EVP_CIPHER_CTX_key_length ( ctx ) * 4 , & xctx -> ks1 . ks ) ;
 xctx -> xts . block1 = ( block128_f ) HWAES_decrypt ;
 # ifdef HWAES_xts_decrypt xctx -> stream = HWAES_xts_decrypt ;
 # endif }
 HWAES_set_encrypt_key ( key + EVP_CIPHER_CTX_key_length ( ctx ) / 2 , EVP_CIPHER_CTX_key_length ( ctx ) * 4 , & xctx -> ks2 . ks ) ;
 xctx -> xts . block2 = ( block128_f ) HWAES_encrypt ;
 xctx -> xts . key1 = & xctx -> ks1 ;
 break ;
 }

static int test_recode_command2 ( xd3_stream * stream , int has_source , int variant , int change ) {
 int has_adler32 = ( variant & 0x1 ) != 0 ;
 int has_apphead = ( variant & 0x2 ) != 0 ;
 int has_secondary = ( variant & 0x4 ) != 0 ;
 int change_adler32 = ( change & 0x1 ) != 0 ;
 int change_apphead = ( change & 0x2 ) != 0 ;
 int change_secondary = ( change & 0x4 ) != 0 ;
 int recoded_adler32 = change_adler32 ? ! has_adler32 : has_adler32 ;
 int recoded_apphead = change_apphead ? ! has_apphead : has_apphead ;
 int recoded_secondary = change_secondary ? ! has_secondary : has_secondary ;
 char ecmd [ TESTBUFSIZE ] , recmd [ TESTBUFSIZE ] , dcmd [ TESTBUFSIZE ] ;
 xoff_t tsize , ssize ;
 int ret ;
 test_setup ( ) ;
 if ( ( ret = test_make_inputs ( stream , has_source ? & ssize : NULL , & tsize ) ) ) {
 return ret ;
 }
 snprintf_func ( ecmd , TESTBUFSIZE , "%s %s -f %s %s %s %s %s %s %s" , program_name , test_softcfg_str , has_adler32 ? "" : "-n " , has_apphead ? "-A=encode_apphead " : "-A= " , has_secondary ? "-S djw " : "-S none " , has_source ? "-s " : "" , has_source ? TEST_SOURCE_FILE : "" , TEST_TARGET_FILE , TEST_DELTA_FILE ) ;
 if ( ( ret = system ( ecmd ) ) != 0 ) {
