static int vapic_post_load ( void * opaque , int version_id ) {
 VAPICROMState * s = opaque ;
 uint8_t * zero ;
 if ( s -> state == VAPIC_INACTIVE && s -> rom_state_paddr != 0 ) {
 s -> state = VAPIC_STANDBY ;
 }
 if ( s -> state != VAPIC_INACTIVE ) {
 if ( vapic_prepare ( s ) < 0 ) {
 return - 1 ;
 }
 }
 if ( s -> state == VAPIC_ACTIVE ) {
 if ( smp_cpus == 1 ) {
 run_on_cpu ( ENV_GET_CPU ( first_cpu ) , do_vapic_enable , s ) ;
 }
 else {
 zero = g_malloc0 ( s -> rom_state . vapic_size ) ;
 cpu_physical_memory_rw ( s -> vapic_paddr , zero , s -> rom_state . vapic_size , 1 ) ;
 g_free ( zero ) ;
 }
 }
 return 0 ;
 }

static int check_nnp_nosuid ( const struct linux_binprm * bprm , const struct task_security_struct * old_tsec , const struct task_security_struct * new_tsec ) {
 int nnp = ( bprm -> unsafe & LSM_UNSAFE_NO_NEW_PRIVS ) ;
 int nosuid = ! mnt_may_suid ( bprm -> file -> f_path . mnt ) ;
 int rc ;
 if ( ! nnp && ! nosuid ) return 0 ;
 if ( new_tsec -> sid == old_tsec -> sid ) return 0 ;
 rc = security_bounded_transition ( old_tsec -> sid , new_tsec -> sid ) ;
 if ( rc ) {
 if ( nnp ) return - EPERM ;
 else return - EACCES ;
 }
 return 0 ;
 }

