static int unpack ( const uint8_t * src , const uint8_t * src_end , uint8_t * dst , int width , int height ) {
 uint8_t * dst_end = dst + width * height ;
 int size , size1 , size2 , offset , run ;
 uint8_t * dst_start = dst ;
 if ( src [ 0 ] & 0x01 ) src += 5 ;
 else src += 2 ;
 if ( src + 3 > src_end ) return AVERROR_INVALIDDATA ;
 size = AV_RB24 ( src ) ;
 src += 3 ;
 while ( size > 0 && src < src_end ) {
 size1 = ( src [ 0 ] & 3 ) ;
 if ( src [ 0 ] & 0x80 ) {
 if ( src [ 0 ] & 0x40 ) {
 if ( src [ 0 ] & 0x20 ) {
 if ( src [ 0 ] < 0xFC ) size1 = ( ( ( src [ 0 ] & 31 ) + 1 ) << 2 ) ;
 src ++ ;
 size2 = 0 ;
 }
 else {
 offset = ( ( src [ 0 ] & 0x10 ) << 12 ) + AV_RB16 ( & src [ 1 ] ) + 1 ;
 size2 = ( ( src [ 0 ] & 0xC ) << 6 ) + src [ 3 ] + 5 ;
 src += 4 ;
 }
 }
 else {
 size1 = ( ( src [ 1 ] & 0xC0 ) >> 6 ) ;
 offset = ( AV_RB16 ( & src [ 1 ] ) & 0x3FFF ) + 1 ;
 size2 = ( src [ 0 ] & 0x3F ) + 4 ;
 src += 3 ;
 }
 }
 else {
 offset = ( ( src [ 0 ] & 0x60 ) << 3 ) + src [ 1 ] + 1 ;
 size2 = ( ( src [ 0 ] & 0x1C ) >> 2 ) + 3 ;
 src += 2 ;
 }
 if ( size1 > src_end - src ) break ;
 if ( size1 > 0 ) {
 size -= size1 ;
 run = FFMIN ( size1 , dst_end - dst ) ;
 memcpy ( dst , src , run ) ;
 dst += run ;
 src += run ;
 }
 if ( size2 > 0 ) {
 if ( dst - dst_start < offset ) return 0 ;
 size -= size2 ;
 run = FFMIN ( size2 , dst_end - dst ) ;
 av_memcpy_backptr ( dst , offset , run ) ;
 dst += run ;
 }
 }
 return 0 ;
 }

int rawv6_rcv ( struct sock * sk , struct sk_buff * skb ) {
 struct inet_sock * inet = inet_sk ( sk ) ;
 struct raw6_sock * rp = raw6_sk ( sk ) ;
 if ( ! xfrm6_policy_check ( sk , XFRM_POLICY_IN , skb ) ) {
 atomic_inc ( & sk -> sk_drops ) ;
 kfree_skb ( skb ) ;
 return NET_RX_DROP ;
 }
 if ( ! rp -> checksum ) skb -> ip_summed = CHECKSUM_UNNECESSARY ;
 if ( skb -> ip_summed == CHECKSUM_COMPLETE ) {
 skb_postpull_rcsum ( skb , skb_network_header ( skb ) , skb_network_header_len ( skb ) ) ;
 if ( ! csum_ipv6_magic ( & ipv6_hdr ( skb ) -> saddr , & ipv6_hdr ( skb ) -> daddr , skb -> len , inet -> inet_num , skb -> csum ) ) skb -> ip_summed = CHECKSUM_UNNECESSARY ;
 }
 if ( ! skb_csum_unnecessary ( skb ) ) skb -> csum = ~ csum_unfold ( csum_ipv6_magic ( & ipv6_hdr ( skb ) -> saddr , & ipv6_hdr ( skb ) -> daddr , skb -> len , inet -> inet_num , 0 ) ) ;
 if ( inet -> hdrincl ) {
 if ( skb_checksum_complete ( skb ) ) {
 atomic_inc ( & sk -> sk_drops ) ;
 kfree_skb ( skb ) ;
 return NET_RX_DROP ;
 }
 }
 rawv6_rcv_skb ( sk , skb ) ;
 return 0 ;
 }

