static void deep_count_more_files_callback ( GObject * source_object , GAsyncResult * res , gpointer user_data ) {
 DeepCountState * state ;
 NautilusDirectory * directory ;
 GList * files , * l ;
 GFileInfo * info ;
 state = user_data ;
 if ( state -> directory == NULL ) {
 deep_count_state_free ( state ) ;
 return ;
 }
 directory = nautilus_directory_ref ( state -> directory ) ;
 g_assert ( directory -> details -> deep_count_in_progress != NULL ) ;
 g_assert ( directory -> details -> deep_count_in_progress == state ) ;
 files = g_file_enumerator_next_files_finish ( state -> enumerator , res , NULL ) ;
 for ( l = files ;
 l != NULL ;
 l = l -> next ) {
 info = l -> data ;
 deep_count_one ( state , info ) ;
 g_object_unref ( info ) ;
 }
 if ( files == NULL ) {
 g_file_enumerator_close_async ( state -> enumerator , 0 , NULL , NULL , NULL ) ;
 g_object_unref ( state -> enumerator ) ;
 state -> enumerator = NULL ;
 deep_count_next_dir ( state ) ;
 }
 else {
 g_file_enumerator_next_files_async ( state -> enumerator , DIRECTORY_LOAD_ITEMS_PER_CALLBACK , G_PRIORITY_LOW , state -> cancellable , deep_count_more_files_callback , state ) ;
 }
 g_list_free ( files ) ;
 nautilus_directory_unref ( directory ) ;
 }

static void cmd_cycle ( const char * data , SERVER_REC * server , WI_ITEM_REC * item ) {
 CHANNEL_REC * chanrec ;
 char * channame , * msg , * joindata ;
 void * free_arg ;
 g_return_if_fail ( data != NULL ) ;
 if ( ! IS_SERVER ( server ) || ! server -> connected ) cmd_return_error ( CMDERR_NOT_CONNECTED ) ;
 if ( ! cmd_get_params ( data , & free_arg , 2 | PARAM_FLAG_OPTCHAN , item , & channame , & msg ) ) return ;
 if ( * channame == '\0' ) cmd_param_error ( CMDERR_NOT_ENOUGH_PARAMS ) ;
 chanrec = channel_find ( server , channame ) ;
 if ( chanrec == NULL ) cmd_param_error ( CMDERR_CHAN_NOT_FOUND ) ;
 joindata = chanrec -> get_join_data ( chanrec ) ;
 window_bind_add ( window_item_window ( chanrec ) , chanrec -> server -> tag , chanrec -> name ) ;
 signal_emit ( "command part" , 3 , data , server , item ) ;
 if ( g_slist_find ( channels , chanrec ) != NULL ) {
 chanrec -> left = TRUE ;
 channel_destroy ( chanrec ) ;
 }
 server -> channels_join ( server , joindata , FALSE ) ;
 g_free ( joindata ) ;
 cmd_params_free ( free_arg ) ;
 }

