 uid_t uid = g_slurm_auth_get_uid ( msg -> auth_cred , slurmctld_config . auth_info ) ;
 char * name = NULL ;
 START_TIMER ;
 debug2 ( "Processing RPC: REQUEST_UPDATE_BLOCK from uid=%d" , uid ) ;
