 if ( ! status ) {
 dissect_scsi_rsp ( tvb , pinfo , parent_tree , itlq , itl , 0 ) ;
 }
 else {
 dissect_scsi_rsp ( tvb , pinfo , parent_tree , itlq , itl , 0x02 ) ;
 }
 return tvb_captured_length ( tvb ) ;
 }
 itlq = ( itlq_nexus_t * ) wmem_tree_lookup32_le ( usb_ms_conv_info -> itlq , pinfo -> num ) ;
 if ( ! itlq ) {
 return tvb_captured_length ( tvb ) ;
 }
 itl = ( itl_nexus_t * ) wmem_tree_lookup32 ( usb_ms_conv_info -> itl , itlq -> lun ) ;
 if ( ! itl ) {
 return tvb_captured_length ( tvb ) ;
 }
 dissect_scsi_payload ( tvb , pinfo , parent_tree , is_request , itlq , itl , 0 ) ;
 return tvb_captured_length ( tvb ) ;
 }

static void nvic_writel ( nvic_state * s , uint32_t offset , uint32_t value ) {
 ARMCPU * cpu ;
 uint32_t oldval ;
 switch ( offset ) {
 case 0x10 : oldval = s -> systick . control ;
 s -> systick . control &= 0xfffffff8 ;
 s -> systick . control |= value & 7 ;
 if ( ( oldval ^ value ) & SYSTICK_ENABLE ) {
 int64_t now = qemu_get_clock_ns ( vm_clock ) ;
 if ( value & SYSTICK_ENABLE ) {
 if ( s -> systick . tick ) {
 s -> systick . tick += now ;
 qemu_mod_timer ( s -> systick . timer , s -> systick . tick ) ;
 }
 else {
 systick_reload ( s , 1 ) ;
 }
 }
 else {
 qemu_del_timer ( s -> systick . timer ) ;
 s -> systick . tick -= now ;
 if ( s -> systick . tick < 0 ) s -> systick . tick = 0 ;
 }
 }
 else if ( ( oldval ^ value ) & SYSTICK_CLKSOURCE ) {
 systick_reload ( s , 1 ) ;
 }
 break ;
 case 0x14 : s -> systick . reload = value ;
 break ;
 case 0x18 : systick_reload ( s , 1 ) ;
 s -> systick . control &= ~ SYSTICK_COUNTFLAG ;
 break ;
 case 0xd04 : if ( value & ( 1 << 31 ) ) {
 armv7m_nvic_set_pending ( s , ARMV7M_EXCP_NMI ) ;
 }
 if ( value & ( 1 << 28 ) ) {
 armv7m_nvic_set_pending ( s , ARMV7M_EXCP_PENDSV ) ;
 }
 else if ( value & ( 1 << 27 ) ) {
 s -> gic . irq_state [ ARMV7M_EXCP_PENDSV ] . pending = 0 ;
 gic_update ( & s -> gic ) ;
 }
 if ( value & ( 1 << 26 ) ) {
 armv7m_nvic_set_pending ( s , ARMV7M_EXCP_SYSTICK ) ;
 }
 else if ( value & ( 1 << 25 ) ) {
 s -> gic . irq_state [ ARMV7M_EXCP_SYSTICK ] . pending = 0 ;
 gic_update ( & s -> gic ) ;
 }
 break ;
 case 0xd08 : cpu = ARM_CPU ( current_cpu ) ;
 cpu -> env . v7m . vecbase = value & 0xffffff80 ;
 break ;
 case 0xd0c : if ( ( value >> 16 ) == 0x05fa ) {
 if ( value & 2 ) {
 qemu_log_mask ( LOG_UNIMP , "VECTCLRACTIVE unimplemented\n" ) ;
 }
 if ( value & 5 ) {
 qemu_log_mask ( LOG_UNIMP , "AIRCR system reset unimplemented\n" ) ;
 }
 }
 break ;
 case 0xd10 : case 0xd14 : qemu_log_mask ( LOG_UNIMP , "NVIC: SCR and CCR unimplemented\n" ) ;
 break ;
 case 0xd24 : s -> gic . irq_state [ ARMV7M_EXCP_MEM ] . enabled = ( value & ( 1 << 16 ) ) != 0 ;
 s -> gic . irq_state [ ARMV7M_EXCP_BUS ] . enabled = ( value & ( 1 << 17 ) ) != 0 ;
 s -> gic . irq_state [ ARMV7M_EXCP_USAGE ] . enabled = ( value & ( 1 << 18 ) ) != 0 ;
 break ;
 case 0xd28 : case 0xd2c : case 0xd30 : case 0xd34 : case 0xd38 : case 0xd3c : qemu_log_mask ( LOG_UNIMP , "NVIC: fault status registers unimplemented\n" ) ;
 break ;
 case 0xf00 : if ( ( value & 0x1ff ) < s -> num_irq ) {
 gic_set_pending_private ( & s -> gic , 0 , value & 0x1ff ) ;
 }
 break ;
 default : qemu_log_mask ( LOG_GUEST_ERROR , "NVIC: Bad write offset 0x%x\n" , offset ) ;
 }
 }

int jbig2_decode_halftone_region ( Jbig2Ctx * ctx , Jbig2Segment * segment , Jbig2HalftoneRegionParams * params , const byte * data , const size_t size , Jbig2Image * image , Jbig2ArithCx * GB_stats ) {
 uint32_t HBPP ;
 uint32_t HNUMPATS ;
 uint8_t * * GI ;
 Jbig2Image * HSKIP = NULL ;
 Jbig2PatternDict * HPATS ;
 uint32_t i ;
 uint32_t mg , ng ;
 int32_t x , y ;
 uint8_t gray_val ;
 memset ( image -> data , params -> HDEFPIXEL , image -> stride * image -> height ) ;
 if ( params -> HENABLESKIP == 1 ) {
 jbig2_error ( ctx , JBIG2_SEVERITY_WARNING , segment -> number , "unhandled option HENABLESKIP" ) ;
 }
 HPATS = jbig2_decode_ht_region_get_hpats ( ctx , segment ) ;
 if ( ! HPATS ) {
 jbig2_error ( ctx , JBIG2_SEVERITY_WARNING , segment -> number , "no pattern dictionary found, skipping halftone image" ) ;
 return - 1 ;
 }
 HNUMPATS = HPATS -> n_patterns ;
 HBPP = 0 ;
 while ( HNUMPATS > ( 1U << ++ HBPP ) ) ;
 GI = jbig2_decode_gray_scale_image ( ctx , segment , data , size , params -> HMMR , params -> HGW , params -> HGH , HBPP , params -> HENABLESKIP , HSKIP , params -> HTEMPLATE , GB_stats ) ;
 if ( ! GI ) {
 jbig2_error ( ctx , JBIG2_SEVERITY_WARNING , segment -> number , "unable to acquire gray-scale image, skipping halftone image" ) ;
 return - 1 ;
 }
 for ( mg = 0 ;
 mg < params -> HGH ;
 ++ mg ) {
 for ( ng = 0 ;
 ng < params -> HGW ;
 ++ ng ) {
 x = ( params -> HGX + mg * params -> HRY + ng * params -> HRX ) >> 8 ;
 y = ( params -> HGY + mg * params -> HRX - ng * params -> HRY ) >> 8 ;
 gray_val = GI [ ng ] [ mg ] ;
 if ( gray_val >= HNUMPATS ) {
 jbig2_error ( ctx , JBIG2_SEVERITY_WARNING , segment -> number , "gray-scale image uses value %d which larger than pattern dictionary" , gray_val ) ;
 gray_val = HNUMPATS - 1 ;
 }
 jbig2_image_compose ( ctx , image , HPATS -> patterns [ gray_val ] , x , y , params -> op ) ;
 }
 }
 for ( i = 0 ;
 i < params -> HGW ;
 ++ i ) {
 jbig2_free ( ctx -> allocator , GI [ i ] ) ;
 }
 jbig2_free ( ctx -> allocator , GI ) ;
 return 0 ;
 }

