 dot = dot / ( dot + 0.6 * optimal_gain ) ;
 }
 else dot = 0.625 ;
 for ( n = 0 ;
 n < size ;
 n ++ ) out [ n ] = best_hist_ptr [ n ] + dot * ( in [ n ] - best_hist_ptr [ n ] ) ;
 return 0 ;
 }

