static int vc1_decode_intra_block ( VC1Context * v , int16_t block [ 64 ] , int n , int coded , int mquant , int codingset ) {
 GetBitContext * gb = & v -> s . gb ;
 MpegEncContext * s = & v -> s ;
 int dc_pred_dir = 0 ;
 int i ;
 int16_t * dc_val ;
 int16_t * ac_val , * ac_val2 ;
