 int use_pred = s -> ac_pred ;
 int scale ;
 int q1 , q2 = 0 ;
 s -> dsp . clear_block ( block ) ;
 mquant = ( mquant < 1 ) ? 0 : ( ( mquant > 31 ) ? 31 : mquant ) ;
 s -> y_dc_scale = s -> y_dc_scale_table [ mquant ] ;
 s -> c_dc_scale = s -> c_dc_scale_table [ mquant ] ;
 if ( n < 4 ) {
 dcdiff = get_vlc2 ( & s -> gb , ff_msmp4_dc_luma_vlc [ s -> dc_table_index ] . table , DC_VLC_BITS , 3 ) ;
 }
 else {
 dcdiff = get_vlc2 ( & s -> gb , ff_msmp4_dc_chroma_vlc [ s -> dc_table_index ] . table , DC_VLC_BITS , 3 ) ;
 }
 if ( dcdiff < 0 ) {
 av_log ( s -> avctx , AV_LOG_ERROR , "Illegal DC VLC\n" ) ;
 return - 1 ;
 }
 if ( dcdiff ) {
 if ( dcdiff == 119 ) {
 if ( mquant == 1 ) dcdiff = get_bits ( gb , 10 ) ;
 else if ( mquant == 2 ) dcdiff = get_bits ( gb , 9 ) ;
 else dcdiff = get_bits ( gb , 8 ) ;
 }
 else {
 if ( mquant == 1 ) dcdiff = ( dcdiff << 2 ) + get_bits ( gb , 2 ) - 3 ;
 else if ( mquant == 2 ) dcdiff = ( dcdiff << 1 ) + get_bits1 ( gb ) - 1 ;
 }
 if ( get_bits1 ( gb ) ) dcdiff = - dcdiff ;
 }
 dcdiff += vc1_pred_dc ( & v -> s , v -> overlap , mquant , n , a_avail , c_avail , & dc_val , & dc_pred_dir ) ;
 * dc_val = dcdiff ;
 if ( n < 4 ) {
 block [ 0 ] = dcdiff * s -> y_dc_scale ;
 }
 else {
 block [ 0 ] = dcdiff * s -> c_dc_scale ;
 }
 i = 1 ;
 if ( ! a_avail ) dc_pred_dir = 1 ;
 if ( ! c_avail ) dc_pred_dir = 0 ;
 if ( ! a_avail && ! c_avail ) use_pred = 0 ;
 ac_val = s -> ac_val [ 0 ] [ 0 ] + s -> block_index [ n ] * 16 ;
 ac_val2 = ac_val ;
 scale = mquant * 2 + v -> halfpq ;
 if ( dc_pred_dir ) ac_val -= 16 ;
 else ac_val -= 16 * s -> block_wrap [ n ] ;
 q1 = s -> current_picture . f . qscale_table [ mb_pos ] ;
 if ( dc_pred_dir && c_avail && mb_pos ) q2 = s -> current_picture . f . qscale_table [ mb_pos - 1 ] ;
 if ( ! dc_pred_dir && a_avail && mb_pos >= s -> mb_stride ) q2 = s -> current_picture . f . qscale_table [ mb_pos - s -> mb_stride ] ;
 if ( dc_pred_dir && n == 1 ) q2 = q1 ;
 if ( ! dc_pred_dir && n == 2 ) q2 = q1 ;
 if ( n == 3 ) q2 = q1 ;
 if ( coded ) {
 int last = 0 , skip , value ;
 int k ;
 while ( ! last ) {
 vc1_decode_ac_coeff ( v , & last , & skip , & value , codingset ) ;
 i += skip ;
 if ( i > 63 ) break ;
 if ( v -> fcm == PROGRESSIVE ) block [ v -> zz_8x8 [ 0 ] [ i ++ ] ] = value ;
 else {
 if ( use_pred && ( v -> fcm == ILACE_FRAME ) ) {
 if ( ! dc_pred_dir ) block [ v -> zz_8x8 [ 2 ] [ i ++ ] ] = value ;
 else block [ v -> zz_8x8 [ 3 ] [ i ++ ] ] = value ;
 }
 else {
 block [ v -> zzi_8x8 [ i ++ ] ] = value ;
 }
 }
 }
 if ( use_pred ) {
 if ( q2 && q1 != q2 ) {
 q1 = q1 * 2 + ( ( q1 == v -> pq ) ? v -> halfpq : 0 ) - 1 ;
 q2 = q2 * 2 + ( ( q2 == v -> pq ) ? v -> halfpq : 0 ) - 1 ;
 if ( q1 < 1 ) return AVERROR_INVALIDDATA ;
 if ( dc_pred_dir ) {
 for ( k = 1 ;
 k < 8 ;
 k ++ ) block [ k << v -> left_blk_sh ] += ( ac_val [ k ] * q2 * ff_vc1_dqscale [ q1 - 1 ] + 0x20000 ) >> 18 ;
 }
 else {
 for ( k = 1 ;
 k < 8 ;
 k ++ ) block [ k << v -> top_blk_sh ] += ( ac_val [ k + 8 ] * q2 * ff_vc1_dqscale [ q1 - 1 ] + 0x20000 ) >> 18 ;
 }
 }
 else {
 if ( dc_pred_dir ) {
 for ( k = 1 ;
 k < 8 ;
 k ++ ) block [ k << v -> left_blk_sh ] += ac_val [ k ] ;
 }
 else {
 for ( k = 1 ;
 k < 8 ;
 k ++ ) block [ k << v -> top_blk_sh ] += ac_val [ k + 8 ] ;
 }
 }
 }
 for ( k = 1 ;
 k < 8 ;
 k ++ ) {
 ac_val2 [ k ] = block [ k << v -> left_blk_sh ] ;
 ac_val2 [ k + 8 ] = block [ k << v -> top_blk_sh ] ;
 }
 for ( k = 1 ;
 k < 64 ;
 k ++ ) if ( block [ k ] ) {
 block [ k ] *= scale ;
 if ( ! v -> pquantizer ) block [ k ] += ( block [ k ] < 0 ) ? - mquant : mquant ;
 }
 if ( use_pred ) i = 63 ;
 }
 else {
 int k ;
 memset ( ac_val2 , 0 , 16 * 2 ) ;
 if ( dc_pred_dir ) {
 if ( use_pred ) {
 memcpy ( ac_val2 , ac_val , 8 * 2 ) ;
 if ( q2 && q1 != q2 ) {
 q1 = q1 * 2 + ( ( q1 == v -> pq ) ? v -> halfpq : 0 ) - 1 ;
 q2 = q2 * 2 + ( ( q2 == v -> pq ) ? v -> halfpq : 0 ) - 1 ;
 if ( q1 < 1 ) return AVERROR_INVALIDDATA ;
 for ( k = 1 ;
 k < 8 ;
 k ++ ) ac_val2 [ k ] = ( ac_val2 [ k ] * q2 * ff_vc1_dqscale [ q1 - 1 ] + 0x20000 ) >> 18 ;
 }
 }
 }
 else {
 if ( use_pred ) {
 memcpy ( ac_val2 + 8 , ac_val + 8 , 8 * 2 ) ;
 if ( q2 && q1 != q2 ) {
 q1 = q1 * 2 + ( ( q1 == v -> pq ) ? v -> halfpq : 0 ) - 1 ;
 q2 = q2 * 2 + ( ( q2 == v -> pq ) ? v -> halfpq : 0 ) - 1 ;
 if ( q1 < 1 ) return AVERROR_INVALIDDATA ;
 for ( k = 1 ;
 k < 8 ;
 k ++ ) ac_val2 [ k + 8 ] = ( ac_val2 [ k + 8 ] * q2 * ff_vc1_dqscale [ q1 - 1 ] + 0x20000 ) >> 18 ;
 }
 }
 }
 if ( use_pred ) {
 if ( dc_pred_dir ) {
 for ( k = 1 ;
 k < 8 ;
 k ++ ) {
 block [ k << v -> left_blk_sh ] = ac_val2 [ k ] * scale ;
 if ( ! v -> pquantizer && block [ k << v -> left_blk_sh ] ) block [ k << v -> left_blk_sh ] += ( block [ k << v -> left_blk_sh ] < 0 ) ? - mquant : mquant ;
 }
 }
 else {
 for ( k = 1 ;
 k < 8 ;
 k ++ ) {
 block [ k << v -> top_blk_sh ] = ac_val2 [ k + 8 ] * scale ;
 if ( ! v -> pquantizer && block [ k << v -> top_blk_sh ] ) block [ k << v -> top_blk_sh ] += ( block [ k << v -> top_blk_sh ] < 0 ) ? - mquant : mquant ;
 }
 }
 i = 63 ;
 }
 }
 s -> block_last_index [ n ] = i ;
