 s -> csr [ 14 ] = padr [ 2 ] ;
 s -> rdra = PHYSADDR ( s , rdra ) ;
 s -> tdra = PHYSADDR ( s , tdra ) ;
 CSR_RCVRC ( s ) = CSR_RCVRL ( s ) ;
 CSR_XMTRC ( s ) = CSR_XMTRL ( s ) ;
 trace_pcnet_ss32_rdra_tdra ( s , BCR_SSIZE32 ( s ) , s -> rdra , CSR_RCVRL ( s ) , s -> tdra , CSR_XMTRL ( s ) ) ;
