 }
 for ( i = 0 ;
 i < 2 ;
 i ++ ) {
 test_ok = 0 ;
 req = evhttp_request_new ( http_chunked_request_done , NULL ) ;
 evhttp_add_header ( req -> output_headers , "Host" , "somehost" ) ;
 if ( evhttp_make_request ( evcon , req , EVHTTP_REQ_GET , "/chunked" ) == - 1 ) {
 fprintf ( stdout , "FAILED\n" ) ;
 exit ( 1 ) ;
 }
 event_dispatch ( ) ;
 if ( test_ok != 1 ) {
