 if ( ( oldflags & FSCONTEXT_MNT ) && old -> sid != new -> sid ) goto mismatch ;
 if ( ( oldflags & CONTEXT_MNT ) && old -> mntpoint_sid != new -> mntpoint_sid ) goto mismatch ;
 if ( ( oldflags & DEFCONTEXT_MNT ) && old -> def_sid != new -> def_sid ) goto mismatch ;
 if ( oldflags & ROOTCONTEXT_MNT ) {
 struct inode_security_struct * oldroot = backing_inode_security ( oldsb -> s_root ) ;
 struct inode_security_struct * newroot = backing_inode_security ( newsb -> s_root ) ;
 if ( oldroot -> sid != newroot -> sid ) goto mismatch ;
 }
 return 0 ;
 mismatch : printk ( KERN_WARNING "SELinux: mount invalid. Same superblock, " "different security settings for (dev %s, " "type %s)\n" , newsb -> s_id , newsb -> s_type -> name ) ;
 return - EBUSY ;
 }

