 if ( ! OBJ_find_sigid_by_algs ( & snid , hnid , EVP_PKEY_id ( pkey ) ) ) return - 1 ;
 X509_ALGOR_set0 ( alg2 , OBJ_nid2obj ( snid ) , V_ASN1_UNDEF , 0 ) ;
