 int i , ret ;
 int offset = 0 ;
 int chidx = 0 ;
 if ( buf_size < avctx -> block_align ) return buf_size ;
 if ( q -> discarded_packets >= 2 ) {
 frame -> nb_samples = q -> samples_per_channel ;
 if ( ( ret = ff_get_buffer ( avctx , frame , 0 ) ) < 0 ) {
