static int decode_ext_header ( Wmv2Context * w ) {
 MpegEncContext * const s = & w -> s ;
 GetBitContext gb ;
 int fps ;
 int code ;
 if ( s -> avctx -> extradata_size < 4 ) return - 1 ;
 init_get_bits ( & gb , s -> avctx -> extradata , 32 ) ;
 fps = get_bits ( & gb , 5 ) ;
 s -> bit_rate = get_bits ( & gb , 11 ) * 1024 ;
 w -> mspel_bit = get_bits1 ( & gb ) ;
 s -> loop_filter = get_bits1 ( & gb ) ;
 w -> abt_flag = get_bits1 ( & gb ) ;
 w -> j_type_bit = get_bits1 ( & gb ) ;
 w -> top_left_mv_flag = get_bits1 ( & gb ) ;
 w -> per_mb_rl_bit = get_bits1 ( & gb ) ;
 code = get_bits ( & gb , 3 ) ;
 if ( code == 0 ) return - 1 ;
 s -> slice_height = s -> mb_height / code ;
 if ( s -> avctx -> debug & FF_DEBUG_PICT_INFO ) {
 av_log ( s -> avctx , AV_LOG_DEBUG , "fps:%d, br:%d, qpbit:%d, abt_flag:%d, j_type_bit:%d, tl_mv_flag:%d, mbrl_bit:%d, code:%d, loop_filter:%d, slices:%d\n" , fps , s -> bit_rate , w -> mspel_bit , w -> abt_flag , w -> j_type_bit , w -> top_left_mv_flag , w -> per_mb_rl_bit , code , s -> loop_filter , code ) ;
 }
 return 0 ;
 }

static int decode_frame ( AVCodecContext * avctx , void * data , int * got_frame , AVPacket * avpkt ) {
 int h , w , ret ;
 AVFrame * pic = data ;
 const uint8_t * psrc = avpkt -> data ;
 uint16_t * y , * u , * v ;
 int aligned_width = ( ( avctx -> width + 47 ) / 48 ) * 48 ;
 int stride = aligned_width * 8 / 3 ;
 if ( avpkt -> size < stride * avctx -> height ) {
 av_log ( avctx , AV_LOG_ERROR , "packet too small\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 if ( ( ret = ff_get_buffer ( avctx , pic , 0 ) ) < 0 ) return ret ;
 y = ( uint16_t * ) pic -> data [ 0 ] ;
 u = ( uint16_t * ) pic -> data [ 1 ] ;
 v = ( uint16_t * ) pic -> data [ 2 ] ;
 pic -> pict_type = AV_PICTURE_TYPE_I ;
 pic -> key_frame = 1 ;
 # define READ_PIXELS ( a , b , c ) do {
 val = av_le2ne32 ( * src ++ ) ;
 * a ++ = val & 0x3FF ;
 * b ++ = ( val >> 10 ) & 0x3FF ;
 * c ++ = ( val >> 20 ) & 0x3FF ;
 }
 while ( 0 ) for ( h = 0 ;
 h < avctx -> height ;
 h ++ ) {
 const uint32_t * src = ( const uint32_t * ) psrc ;
 uint32_t val ;
 for ( w = 0 ;
 w < avctx -> width - 5 ;
 w += 6 ) {
 READ_PIXELS ( u , y , v ) ;
 READ_PIXELS ( y , u , y ) ;
 READ_PIXELS ( v , y , u ) ;
 READ_PIXELS ( y , v , y ) ;
 }
 if ( w < avctx -> width - 1 ) {
 READ_PIXELS ( u , y , v ) ;
 val = av_le2ne32 ( * src ++ ) ;
 * y ++ = val & 0x3FF ;
 }
 if ( w < avctx -> width - 3 ) {
 * u ++ = ( val >> 10 ) & 0x3FF ;
 * y ++ = ( val >> 20 ) & 0x3FF ;
 val = av_le2ne32 ( * src ++ ) ;
 * v ++ = val & 0x3FF ;
 * y ++ = ( val >> 10 ) & 0x3FF ;
 }
 psrc += stride ;
 y += pic -> linesize [ 0 ] / 2 - avctx -> width ;
 u += pic -> linesize [ 1 ] / 2 - avctx -> width / 2 ;
 v += pic -> linesize [ 2 ] / 2 - avctx -> width / 2 ;
 }
 * got_frame = 1 ;
 return avpkt -> size ;
 }

