 case INTRA_NULL : if ( ! curr_cell . tree ) {
 curr_cell . mv_ptr = 0 ;
 curr_cell . tree = 1 ;
 }
 else {
 RESYNC_BITSTREAM ;
 code = get_bits ( & ctx -> gb , 2 ) ;
 if ( code >= 2 ) {
 av_log ( avctx , AV_LOG_ERROR , "Invalid VQ_NULL code: %d\n" , code ) ;
 return AVERROR_INVALIDDATA ;
 }
 if ( code == 1 ) av_log ( avctx , AV_LOG_ERROR , "SkipCell procedure not implemented yet!\n" ) ;
 CHECK_CELL if ( ! curr_cell . mv_ptr ) return AVERROR_INVALIDDATA ;
 copy_cell ( ctx , plane , & curr_cell ) ;
 return 0 ;
 }
 break ;
 case INTER_DATA : if ( ! curr_cell . tree ) {
 unsigned mv_idx ;
 if ( ! ctx -> need_resync ) ctx -> next_cell_data = & ctx -> gb . buffer [ ( get_bits_count ( & ctx -> gb ) + 7 ) >> 3 ] ;
 mv_idx = * ( ctx -> next_cell_data ++ ) ;
 if ( mv_idx >= ctx -> num_vectors ) {
 av_log ( avctx , AV_LOG_ERROR , "motion vector index out of range\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 curr_cell . mv_ptr = & ctx -> mc_vectors [ mv_idx << 1 ] ;
 curr_cell . tree = 1 ;
 UPDATE_BITPOS ( 8 ) ;
 }
 else {
 if ( ! ctx -> need_resync ) ctx -> next_cell_data = & ctx -> gb . buffer [ ( get_bits_count ( & ctx -> gb ) + 7 ) >> 3 ] ;
 CHECK_CELL bytes_used = decode_cell ( ctx , avctx , plane , & curr_cell , ctx -> next_cell_data , ctx -> last_byte ) ;
 if ( bytes_used < 0 ) return AVERROR_INVALIDDATA ;
 UPDATE_BITPOS ( bytes_used << 3 ) ;
 ctx -> next_cell_data += bytes_used ;
 return 0 ;
 }
 break ;
 }
 }
 return 0 ;
 }

