 "y" , "w" , "d" , "h" , "m" , "s" }
 ;
 static const u_int seconds [ ] = {
 31536000 , 604800 , 86400 , 3600 , 60 , 1 }
 ;
 const char * * l = lengths ;
 const u_int * s = seconds ;
 if ( secs == 0 ) {
 ND_PRINT ( ( ndo , "0s" ) ) ;
