 }
 s ++ ;
 l ++ ;
 }
 }

int dtls1_send_server_hello ( SSL * s ) {
 unsigned char * buf ;
 unsigned char * p , * d ;
 int i ;
 unsigned int sl ;
 unsigned long l ;
 if ( s -> state == SSL3_ST_SW_SRVR_HELLO_A ) {
 buf = ( unsigned char * ) s -> init_buf -> data ;
 p = s -> s3 -> server_random ;
 ssl_fill_hello_random ( s , 1 , p , SSL3_RANDOM_SIZE ) ;
 d = p = & ( buf [ DTLS1_HM_HEADER_LENGTH ] ) ;
 * ( p ++ ) = s -> version >> 8 ;
 * ( p ++ ) = s -> version & 0xff ;
 memcpy ( p , s -> s3 -> server_random , SSL3_RANDOM_SIZE ) ;
 p += SSL3_RANDOM_SIZE ;
 if ( ! ( s -> ctx -> session_cache_mode & SSL_SESS_CACHE_SERVER ) ) s -> session -> session_id_length = 0 ;
 sl = s -> session -> session_id_length ;
 if ( sl > sizeof s -> session -> session_id ) {
 SSLerr ( SSL_F_DTLS1_SEND_SERVER_HELLO , ERR_R_INTERNAL_ERROR ) ;
 return - 1 ;
 }
 * ( p ++ ) = sl ;
 memcpy ( p , s -> session -> session_id , sl ) ;
 p += sl ;
 if ( s -> s3 -> tmp . new_cipher == NULL ) return - 1 ;
 i = ssl3_put_cipher_by_char ( s -> s3 -> tmp . new_cipher , p ) ;
 p += i ;
 # ifdef OPENSSL_NO_COMP * ( p ++ ) = 0 ;
 # else if ( s -> s3 -> tmp . new_compression == NULL ) * ( p ++ ) = 0 ;
 else * ( p ++ ) = s -> s3 -> tmp . new_compression -> id ;
 # endif # ifndef OPENSSL_NO_TLSEXT if ( ssl_prepare_serverhello_tlsext ( s ) <= 0 ) {
 SSLerr ( SSL_F_DTLS1_SEND_SERVER_HELLO , SSL_R_SERVERHELLO_TLSEXT ) ;
 return - 1 ;
 }
 if ( ( p = ssl_add_serverhello_tlsext ( s , p , buf + SSL3_RT_MAX_PLAIN_LENGTH ) ) == NULL ) {
 SSLerr ( SSL_F_DTLS1_SEND_SERVER_HELLO , ERR_R_INTERNAL_ERROR ) ;
 return - 1 ;
 }
 # endif l = ( p - d ) ;
 d = buf ;
 d = dtls1_set_message_header ( s , d , SSL3_MT_SERVER_HELLO , l , 0 , l ) ;
 s -> state = SSL3_ST_SW_SRVR_HELLO_B ;
 s -> init_num = p - buf ;
 s -> init_off = 0 ;
 dtls1_buffer_message ( s , 0 ) ;
 }
 return ( dtls1_do_write ( s , SSL3_RT_HANDSHAKE ) ) ;
 }

static void cl_hash ( register count_int chsize , GifCtx * ctx ) {
 register count_int * htab_p = ctx -> htab + chsize ;
 register long i ;
 register long m1 = - 1 ;
 i = chsize - 16 ;
 do {
 * ( htab_p - 16 ) = m1 ;
 * ( htab_p - 15 ) = m1 ;
 * ( htab_p - 14 ) = m1 ;
 * ( htab_p - 13 ) = m1 ;
 * ( htab_p - 12 ) = m1 ;
 * ( htab_p - 11 ) = m1 ;
 * ( htab_p - 10 ) = m1 ;
 * ( htab_p - 9 ) = m1 ;
 * ( htab_p - 8 ) = m1 ;
 * ( htab_p - 7 ) = m1 ;
 * ( htab_p - 6 ) = m1 ;
 * ( htab_p - 5 ) = m1 ;
 * ( htab_p - 4 ) = m1 ;
 * ( htab_p - 3 ) = m1 ;
 * ( htab_p - 2 ) = m1 ;
 * ( htab_p - 1 ) = m1 ;
 htab_p -= 16 ;
 }
 while ( ( i -= 16 ) >= 0 ) ;
 for ( i += 16 ;
 i > 0 ;
 -- i ) {
 * -- htab_p = m1 ;
 }
 }

