 for ( i = 0 ;
 i < int_fb_list -> num_internal_frame_buffers ;
 ++ i ) {
 if ( ! int_fb_list -> int_fb [ i ] . in_use ) break ;
 }
 if ( i == int_fb_list -> num_internal_frame_buffers ) return - 1 ;
 if ( int_fb_list -> int_fb [ i ] . size < min_size ) {
