static int vorbis_parse_id_hdr ( vorbis_context * vc ) {
 GetBitContext * gb = & vc -> gb ;
 unsigned bl0 , bl1 ;
 if ( ( get_bits ( gb , 8 ) != 'v' ) || ( get_bits ( gb , 8 ) != 'o' ) || ( get_bits ( gb , 8 ) != 'r' ) || ( get_bits ( gb , 8 ) != 'b' ) || ( get_bits ( gb , 8 ) != 'i' ) || ( get_bits ( gb , 8 ) != 's' ) ) {
 av_log ( vc -> avctx , AV_LOG_ERROR , " Vorbis id header packet corrupt (no vorbis signature). \n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 vc -> version = get_bits_long ( gb , 32 ) ;
 vc -> audio_channels = get_bits ( gb , 8 ) ;
 if ( vc -> audio_channels <= 0 ) {
 av_log ( vc -> avctx , AV_LOG_ERROR , "Invalid number of channels\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 vc -> audio_samplerate = get_bits_long ( gb , 32 ) ;
 if ( vc -> audio_samplerate <= 0 ) {
 av_log ( vc -> avctx , AV_LOG_ERROR , "Invalid samplerate\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 vc -> bitrate_maximum = get_bits_long ( gb , 32 ) ;
 vc -> bitrate_nominal = get_bits_long ( gb , 32 ) ;
 vc -> bitrate_minimum = get_bits_long ( gb , 32 ) ;
 bl0 = get_bits ( gb , 4 ) ;
 bl1 = get_bits ( gb , 4 ) ;
 vc -> blocksize [ 0 ] = ( 1 << bl0 ) ;
 vc -> blocksize [ 1 ] = ( 1 << bl1 ) ;
 if ( bl0 > 13 || bl0 < 6 || bl1 > 13 || bl1 < 6 || bl1 < bl0 ) {
 av_log ( vc -> avctx , AV_LOG_ERROR , " Vorbis id header packet corrupt (illegal blocksize). \n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 vc -> win [ 0 ] = ff_vorbis_vwin [ bl0 - 6 ] ;
 vc -> win [ 1 ] = ff_vorbis_vwin [ bl1 - 6 ] ;
 if ( ( get_bits1 ( gb ) ) == 0 ) {
 av_log ( vc -> avctx , AV_LOG_ERROR , " Vorbis id header packet corrupt (framing flag not set). \n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 vc -> channel_residues = av_malloc ( ( vc -> blocksize [ 1 ] / 2 ) * vc -> audio_channels * sizeof ( * vc -> channel_residues ) ) ;
 vc -> saved = av_mallocz ( ( vc -> blocksize [ 1 ] / 4 ) * vc -> audio_channels * sizeof ( * vc -> saved ) ) ;
 if ( ! vc -> channel_residues || ! vc -> saved ) return AVERROR ( ENOMEM ) ;
 vc -> previous_window = 0 ;
 ff_mdct_init ( & vc -> mdct [ 0 ] , bl0 , 1 , - 1.0 ) ;
 ff_mdct_init ( & vc -> mdct [ 1 ] , bl1 , 1 , - 1.0 ) ;
 av_dlog ( NULL , " vorbis version %d \n audio_channels %d \n audio_samplerate %d \n bitrate_max %d \n bitrate_nom %d \n bitrate_min %d \n blk_0 %d blk_1 %d \n " , vc -> version , vc -> audio_channels , vc -> audio_samplerate , vc -> bitrate_maximum , vc -> bitrate_nominal , vc -> bitrate_minimum , vc -> blocksize [ 0 ] , vc -> blocksize [ 1 ] ) ;
 return 0 ;
 }

static teReqs _tocEntryRequired ( TocEntry * te , teSection curSection , RestoreOptions * ropt ) {
 teReqs res = REQ_SCHEMA | REQ_DATA ;
 if ( strcmp ( te -> desc , "ENCODING" ) == 0 || strcmp ( te -> desc , "STDSTRINGS" ) == 0 ) return REQ_SPECIAL ;
 if ( ropt -> aclsSkip && _tocEntryIsACL ( te ) ) return 0 ;
 if ( ropt -> no_security_labels && strcmp ( te -> desc , "SECURITY LABEL" ) == 0 ) return 0 ;
 switch ( curSection ) {
 case SECTION_PRE_DATA : if ( ! ( ropt -> dumpSections & DUMP_PRE_DATA ) ) return 0 ;
 break ;
 case SECTION_DATA : if ( ! ( ropt -> dumpSections & DUMP_DATA ) ) return 0 ;
 break ;
 case SECTION_POST_DATA : if ( ! ( ropt -> dumpSections & DUMP_POST_DATA ) ) return 0 ;
 break ;
 default : return 0 ;
 }
 if ( ropt -> schemaNames . head != NULL ) {
 if ( ! te -> namespace ) return 0 ;
 if ( ! ( simple_string_list_member ( & ropt -> schemaNames , te -> namespace ) ) ) return 0 ;
 }
 if ( ropt -> selTypes ) {
 if ( strcmp ( te -> desc , "TABLE" ) == 0 || strcmp ( te -> desc , "TABLE DATA" ) == 0 || strcmp ( te -> desc , "VIEW" ) == 0 || strcmp ( te -> desc , "FOREIGN TABLE" ) == 0 || strcmp ( te -> desc , "MATERIALIZED VIEW" ) == 0 || strcmp ( te -> desc , "MATERIALIZED VIEW DATA" ) == 0 || strcmp ( te -> desc , "SEQUENCE" ) == 0 || strcmp ( te -> desc , "SEQUENCE SET" ) == 0 ) {
 if ( ! ropt -> selTable ) return 0 ;
 if ( ropt -> tableNames . head != NULL && ( ! ( simple_string_list_member ( & ropt -> tableNames , te -> tag ) ) ) ) return 0 ;
 }
 else if ( strcmp ( te -> desc , "INDEX" ) == 0 ) {
 if ( ! ropt -> selIndex ) return 0 ;
 if ( ropt -> indexNames . head != NULL && ( ! ( simple_string_list_member ( & ropt -> indexNames , te -> tag ) ) ) ) return 0 ;
 }
 else if ( strcmp ( te -> desc , "FUNCTION" ) == 0 ) {
 if ( ! ropt -> selFunction ) return 0 ;
 if ( ropt -> functionNames . head != NULL && ( ! ( simple_string_list_member ( & ropt -> functionNames , te -> tag ) ) ) ) return 0 ;
 }
 else if ( strcmp ( te -> desc , "TRIGGER" ) == 0 ) {
 if ( ! ropt -> selTrigger ) return 0 ;
 if ( ropt -> triggerNames . head != NULL && ( ! ( simple_string_list_member ( & ropt -> triggerNames , te -> tag ) ) ) ) return 0 ;
 }
 else return 0 ;
 }
 if ( ! te -> hadDumper ) {
 if ( strcmp ( te -> desc , "SEQUENCE SET" ) == 0 || strcmp ( te -> desc , "BLOB" ) == 0 || ( strcmp ( te -> desc , "ACL" ) == 0 && strncmp ( te -> tag , "LARGE OBJECT " , 13 ) == 0 ) || ( strcmp ( te -> desc , "COMMENT" ) == 0 && strncmp ( te -> tag , "LARGE OBJECT " , 13 ) == 0 ) || ( strcmp ( te -> desc , "SECURITY LABEL" ) == 0 && strncmp ( te -> tag , "LARGE OBJECT " , 13 ) == 0 ) ) res = res & REQ_DATA ;
 else res = res & ~ REQ_DATA ;
 }
 if ( ( strcmp ( te -> desc , "<Init>" ) == 0 ) && ( strcmp ( te -> tag , "Max OID" ) == 0 ) ) return 0 ;
 if ( ropt -> schemaOnly ) res = res & REQ_SCHEMA ;
 if ( ropt -> dataOnly ) res = res & REQ_DATA ;
 if ( ! te -> defn || strlen ( te -> defn ) == 0 ) res = res & ~ REQ_SCHEMA ;
 if ( ropt -> idWanted && ! ropt -> idWanted [ te -> dumpId - 1 ] ) return 0 ;
 return res ;
 }

int pdf_tos_make_trm ( fz_context * ctx , pdf_text_object_state * tos , pdf_text_state * text , pdf_font_desc * fontdesc , int cid , fz_matrix * trm ) {
 fz_matrix tsm ;
 tsm . a = text -> size * text -> scale ;
 tsm . b = 0 ;
 tsm . c = 0 ;
 tsm . d = text -> size ;
 tsm . e = 0 ;
 tsm . f = text -> rise ;
 if ( fontdesc -> wmode == 0 ) {
 pdf_hmtx h = pdf_lookup_hmtx ( ctx , fontdesc , cid ) ;
 float w0 = h . w * 0.001f ;
 tos -> char_tx = ( w0 * text -> size + text -> char_space ) * text -> scale ;
 tos -> char_ty = 0 ;
 }
 if ( fontdesc -> wmode == 1 ) {
 pdf_vmtx v = pdf_lookup_vmtx ( ctx , fontdesc , cid ) ;
 float w1 = v . w * 0.001f ;
 tsm . e -= v . x * fabsf ( text -> size ) * 0.001f ;
 tsm . f -= v . y * text -> size * 0.001f ;
 tos -> char_tx = 0 ;
 tos -> char_ty = w1 * text -> size + text -> char_space ;
 }
 fz_concat ( trm , & tsm , & tos -> tm ) ;
 tos -> cid = cid ;
 tos -> gid = pdf_font_cid_to_gid ( ctx , fontdesc , cid ) ;
 tos -> fontdesc = fontdesc ;
 fz_expand_rect ( fz_bound_glyph ( ctx , fontdesc -> font , tos -> gid , trm , & tos -> char_bbox ) , 1 ) ;
 return tos -> gid ;
 }

