 jpc_fix_t * dstptr ;
 register jpc_fix_t * srcptr2 ;
 register jpc_fix_t * dstptr2 ;
 register int n ;
 register int i ;
 int m ;
 int hstartcol ;
 if ( bufsize > QMFB_SPLITBUFSIZE ) {
 if ( ! ( buf = jas_alloc2 ( bufsize , sizeof ( jpc_fix_t ) ) ) ) {
 abort ( ) ;
 }
 }
 if ( numrows >= 2 ) {
 hstartcol = ( numrows + 1 - parity ) >> 1 ;
 m = numrows - hstartcol ;
 n = m ;
 dstptr = buf ;
 srcptr = & a [ ( 1 - parity ) * stride ] ;
 while ( n -- > 0 ) {
 dstptr2 = dstptr ;
 srcptr2 = srcptr ;
 for ( i = 0 ;
 i < JPC_QMFB_COLGRPSIZE ;
 ++ i ) {
 * dstptr2 = * srcptr2 ;
 ++ dstptr2 ;
 ++ srcptr2 ;
 }
 dstptr += JPC_QMFB_COLGRPSIZE ;
 srcptr += stride << 1 ;
 }
 dstptr = & a [ ( 1 - parity ) * stride ] ;
 srcptr = & a [ ( 2 - parity ) * stride ] ;
 n = numrows - m - ( ! parity ) ;
 while ( n -- > 0 ) {
 dstptr2 = dstptr ;
 srcptr2 = srcptr ;
 for ( i = 0 ;
 i < JPC_QMFB_COLGRPSIZE ;
 ++ i ) {
 * dstptr2 = * srcptr2 ;
 ++ dstptr2 ;
 ++ srcptr2 ;
 }
 dstptr += stride ;
 srcptr += stride << 1 ;
 }
 dstptr = & a [ hstartcol * stride ] ;
 srcptr = buf ;
 n = m ;
 while ( n -- > 0 ) {
 dstptr2 = dstptr ;
 srcptr2 = srcptr ;
 for ( i = 0 ;
 i < JPC_QMFB_COLGRPSIZE ;
 ++ i ) {
 * dstptr2 = * srcptr2 ;
 ++ dstptr2 ;
 ++ srcptr2 ;
 }
 dstptr += stride ;
 srcptr += JPC_QMFB_COLGRPSIZE ;
 }
 }
 if ( buf != splitbuf ) {
