static int tgv_decode_frame ( AVCodecContext * avctx , void * data , int * got_frame , AVPacket * avpkt ) {
 const uint8_t * buf = avpkt -> data ;
 int buf_size = avpkt -> size ;
 TgvContext * s = avctx -> priv_data ;
 const uint8_t * buf_end = buf + buf_size ;
 int chunk_type , ret ;
 chunk_type = AV_RL32 ( & buf [ 0 ] ) ;
 buf += EA_PREAMBLE_SIZE ;
 if ( chunk_type == kVGT_TAG ) {
 int pal_count , i ;
 if ( buf + 12 > buf_end ) {
 av_log ( avctx , AV_LOG_WARNING , "truncated header\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 s -> width = AV_RL16 ( & buf [ 0 ] ) ;
 s -> height = AV_RL16 ( & buf [ 2 ] ) ;
 if ( s -> avctx -> width != s -> width || s -> avctx -> height != s -> height ) {
 avcodec_set_dimensions ( s -> avctx , s -> width , s -> height ) ;
 cond_release_buffer ( & s -> frame ) ;
 cond_release_buffer ( & s -> last_frame ) ;
 }
 pal_count = AV_RL16 ( & buf [ 6 ] ) ;
 buf += 12 ;
 for ( i = 0 ;
 i < pal_count && i < AVPALETTE_COUNT && buf + 2 < buf_end ;
 i ++ ) {
 s -> palette [ i ] = AV_RB24 ( buf ) ;
 buf += 3 ;
 }
 }
 if ( ( ret = av_image_check_size ( s -> width , s -> height , 0 , avctx ) ) < 0 ) return ret ;
 FFSWAP ( AVFrame , s -> frame , s -> last_frame ) ;
 if ( ! s -> frame . data [ 0 ] ) {
 s -> frame . reference = 1 ;
 s -> frame . buffer_hints = FF_BUFFER_HINTS_VALID ;
 s -> frame . linesize [ 0 ] = s -> width ;
 s -> frame . data [ 0 ] = av_malloc ( s -> width * s -> height ) ;
 if ( ! s -> frame . data [ 0 ] ) return AVERROR ( ENOMEM ) ;
 s -> frame . data [ 1 ] = av_malloc ( AVPALETTE_SIZE ) ;
 if ( ! s -> frame . data [ 1 ] ) {
 av_freep ( & s -> frame . data [ 0 ] ) ;
 return AVERROR ( ENOMEM ) ;
 }
 }
 memcpy ( s -> frame . data [ 1 ] , s -> palette , AVPALETTE_SIZE ) ;
 if ( chunk_type == kVGT_TAG ) {
 s -> frame . key_frame = 1 ;
 s -> frame . pict_type = AV_PICTURE_TYPE_I ;
 if ( unpack ( buf , buf_end , s -> frame . data [ 0 ] , s -> avctx -> width , s -> avctx -> height ) < 0 ) {
 av_log ( avctx , AV_LOG_WARNING , "truncated intra frame\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 }
 else {
 if ( ! s -> last_frame . data [ 0 ] ) {
 av_log ( avctx , AV_LOG_WARNING , "inter frame without corresponding intra frame\n" ) ;
 return buf_size ;
 }
 s -> frame . key_frame = 0 ;
 s -> frame . pict_type = AV_PICTURE_TYPE_P ;
 if ( tgv_decode_inter ( s , buf , buf_end ) < 0 ) {
 av_log ( avctx , AV_LOG_WARNING , "truncated inter frame\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 }
 * got_frame = 1 ;
 * ( AVFrame * ) data = s -> frame ;
 return buf_size ;
 }

static gchar * logcat_log ( const struct dumper_t * dumper , guint32 seconds , gint milliseconds , gint pid , gint tid , gchar priority , const gchar * tag , const gchar * log ) {
 gchar time_buffer [ 15 ] ;
 time_t datetime ;
 datetime = ( time_t ) seconds ;
 switch ( dumper -> type ) {
 case DUMP_BRIEF : return g_strdup_printf ( "%c/%-8s(%5i): %s\n" , priority , tag , pid , log ) ;
 case DUMP_PROCESS : return g_strdup_printf ( "%c(%5i) %s (%s)\n" , priority , pid , log , "" ) ;
 case DUMP_TAG : return g_strdup_printf ( "%c/%-8s: %s\n" , priority , tag , log ) ;
 case DUMP_THREAD : return g_strdup_printf ( "%c(%5i:0x%02x) %s\n" , priority , pid , tid , log ) ;
 case DUMP_TIME : strftime ( time_buffer , sizeof ( time_buffer ) , "%m-%d %H:%M:%S" , gmtime ( & datetime ) ) ;
 return g_strdup_printf ( "%s.%03i %c/%-8s(%5i): %s\n" , time_buffer , milliseconds , priority , tag , pid , log ) ;
 case DUMP_THREADTIME : strftime ( time_buffer , sizeof ( time_buffer ) , "%m-%d %H:%M:%S" , gmtime ( & datetime ) ) ;
 return g_strdup_printf ( "%s.%03i %5i %5i %c %-8s: %s\n" , time_buffer , milliseconds , pid , tid , priority , tag , log ) ;
 case DUMP_LONG : strftime ( time_buffer , sizeof ( time_buffer ) , "%m-%d %H:%M:%S" , gmtime ( & datetime ) ) ;
 return g_strdup_printf ( "[ %s.%03i %5i:0x%02x %c/%s ]\n%s\n\n" , time_buffer , milliseconds , pid , tid , priority , tag , log ) ;
 default : return NULL ;
 }
 }

