 int mode ;
 int i ;
 int8_t dc [ 6 ] ;
 mode = bytestream2_get_byte ( & s -> gb ) ;
 if ( mode > 12 ) {
 GetBitContext gb ;
 init_get_bits ( & gb , s -> gb . buffer , FFMIN ( s -> gb . buffer_end - s -> gb . buffer , mode ) * 8 ) ;
 for ( i = 0 ;
 i < 6 ;
 i ++ ) tgq_decode_block ( s , s -> block [ i ] , & gb ) ;
 tgq_idct_put_mb ( s , s -> block , mb_x , mb_y ) ;
 bytestream2_skip ( & s -> gb , mode ) ;
 }
 else {
 if ( mode == 3 ) {
