static void rgb_to_cmyk ( fz_context * ctx , const fz_colorspace * cs , const float * rgb , float * cmyk ) {
 float c , m , y , k ;
 c = 1 - rgb [ 0 ] ;
 m = 1 - rgb [ 1 ] ;
 y = 1 - rgb [ 2 ] ;
 k = fz_min ( c , fz_min ( m , y ) ) ;
 cmyk [ 0 ] = c - k ;
 cmyk [ 1 ] = m - k ;
 cmyk [ 2 ] = y - k ;
 cmyk [ 3 ] = k ;
 }

