 JAS_DBGLOG ( 10 , ( "starting rate allocation\n" ) ) ;
 tile = enc -> curtile ;
 for ( lyrno = 1 ;
 lyrno < numlyrs - 1 ;
 ++ lyrno ) {
 if ( cumlens [ lyrno - 1 ] > cumlens [ lyrno ] ) {
 abort ( ) ;
 }
 }
 if ( ! ( out = jas_stream_memopen ( 0 , 0 ) ) ) {
 return - 1 ;
 }
 mnrdslope = DBL_MAX ;
 mxrdslope = 0 ;
 endcomps = & tile -> tcmpts [ tile -> numtcmpts ] ;
 for ( comp = tile -> tcmpts ;
 comp != endcomps ;
 ++ comp ) {
 endlvls = & comp -> rlvls [ comp -> numrlvls ] ;
 for ( lvl = comp -> rlvls ;
 lvl != endlvls ;
 ++ lvl ) {
 if ( ! lvl -> bands ) {
 continue ;
 }
 endbands = & lvl -> bands [ lvl -> numbands ] ;
 for ( band = lvl -> bands ;
 band != endbands ;
 ++ band ) {
 if ( ! band -> data ) {
 continue ;
 }
 for ( prcno = 0 , prc = band -> prcs ;
 prcno < lvl -> numprcs ;
 ++ prcno , ++ prc ) {
 if ( ! prc -> cblks ) {
 continue ;
 }
 endcblks = & prc -> cblks [ prc -> numcblks ] ;
 for ( cblk = prc -> cblks ;
 cblk != endcblks ;
 ++ cblk ) {
 calcrdslopes ( cblk ) ;
 endpasses = & cblk -> passes [ cblk -> numpasses ] ;
 for ( pass = cblk -> passes ;
 pass != endpasses ;
 ++ pass ) {
 if ( pass -> rdslope > 0 ) {
 if ( pass -> rdslope < mnrdslope ) {
 mnrdslope = pass -> rdslope ;
 }
 if ( pass -> rdslope > mxrdslope ) {
 mxrdslope = pass -> rdslope ;
 }
 }
 }
 }
 }
 }
 }
 }
 JAS_DBGLOG ( 10 , ( "min rdslope = %f max rdslope = %f\n" , mnrdslope , mxrdslope ) ) ;
 jpc_init_t2state ( enc , 1 ) ;
 for ( lyrno = 0 ;
 lyrno < numlyrs ;
 ++ lyrno ) {
 lo = mnrdslope ;
 hi = mxrdslope ;
 success = 0 ;
 goodthresh = 0 ;
 numiters = 0 ;
 do {
 cumlen = cumlens [ lyrno ] ;
 if ( cumlen == UINT_FAST32_MAX ) {
 assert ( lyrno == numlyrs - 1 ) ;
 goodthresh = - 1 ;
 success = 1 ;
 break ;
 }
 thresh = ( lo + hi ) / 2 ;
