 if ( avctx -> codec_id == AV_CODEC_ID_AURA ) {
 y_table = u_table ;
 u_table = v_table ;
 }
 if ( buf_size != 48 + s -> height * ( s -> width * 3 / 4 ) ) {
 av_log ( avctx , AV_LOG_ERROR , "got a buffer with %d bytes when %d were expected\n" , buf_size , 48 + s -> height * ( s -> width * 3 / 4 ) ) ;
 return AVERROR_INVALIDDATA ;
 }
 stream_ptr = 48 ;
 if ( ( ret = ff_get_buffer ( avctx , frame , 0 ) ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "get_buffer() failed\n" ) ;
 return ret ;
 }
 y_plane = frame -> data [ 0 ] ;
 u_plane = frame -> data [ 1 ] ;
 v_plane = frame -> data [ 2 ] ;
 for ( y_ptr = 0 , u_ptr = 0 , v_ptr = 0 ;
 y_ptr < ( s -> height * frame -> linesize [ 0 ] ) ;
 y_ptr += frame -> linesize [ 0 ] - s -> width , u_ptr += frame -> linesize [ 1 ] - s -> width / 4 , v_ptr += frame -> linesize [ 2 ] - s -> width / 4 ) {
 cur_byte = buf [ stream_ptr ++ ] ;
