 Buf buffer ;
 DEF_TIMERS ;
 START_TIMER ;
 debug2 ( "Processing RPC: REQUEST_BURST_BUFFER_INFO from uid=%d" , uid ) ;
 buffer = init_buf ( BUF_SIZE ) ;
 if ( validate_super_user ( uid ) ) uid = 0 ;
