 SubStream * s = & m -> substream [ substr ] ;
 unsigned int i , out_ch = 0 ;
 int32_t * data_32 ;
 int16_t * data_16 ;
 int ret ;
 int is32 = ( m -> avctx -> sample_fmt == AV_SAMPLE_FMT_S32 ) ;
 if ( m -> avctx -> channels != s -> max_matrix_channel + 1 ) {
 av_log ( m -> avctx , AV_LOG_ERROR , "channel count mismatch\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 if ( ! s -> blockpos ) {
 av_log ( avctx , AV_LOG_ERROR , "No samples to output.\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 frame -> nb_samples = s -> blockpos ;
 if ( ( ret = ff_get_buffer ( avctx , frame , 0 ) ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "get_buffer() failed\n" ) ;
 return ret ;
 }
 data_32 = ( int32_t * ) frame -> data [ 0 ] ;
 data_16 = ( int16_t * ) frame -> data [ 0 ] ;
 for ( i = 0 ;
 i < s -> blockpos ;
 i ++ ) {
 for ( out_ch = 0 ;
 out_ch <= s -> max_matrix_channel ;
 out_ch ++ ) {
 int mat_ch = s -> ch_assign [ out_ch ] ;
 int32_t sample = m -> sample_buffer [ i ] [ mat_ch ] << s -> output_shift [ mat_ch ] ;
 s -> lossless_check_data ^= ( sample & 0xffffff ) << mat_ch ;
 if ( is32 ) * data_32 ++ = sample << 8 ;
 else * data_16 ++ = sample >> 8 ;
 }
 }
 * got_frame_ptr = 1 ;
 return 0 ;
 }

static int _evdns_nameserver_add_impl ( unsigned long int address , int port ) {
 const struct nameserver * server = server_head , * const started_at = server_head ;
 struct nameserver * ns ;
 int err = 0 ;
 if ( server ) {
 do {
 if ( server -> address == address ) return 3 ;
 server = server -> next ;
 }
 while ( server != started_at ) ;
 }
 ns = ( struct nameserver * ) malloc ( sizeof ( struct nameserver ) ) ;
 if ( ! ns ) return - 1 ;
 memset ( ns , 0 , sizeof ( struct nameserver ) ) ;
 evtimer_set ( & ns -> timeout_event , nameserver_prod_callback , ns ) ;
 ns -> socket = socket ( PF_INET , SOCK_DGRAM , 0 ) ;
 if ( ns -> socket < 0 ) {
 err = 1 ;
 goto out1 ;
 }
 evutil_make_socket_nonblocking ( ns -> socket ) ;
 ns -> address = address ;
 ns -> port = htons ( port ) ;
 ns -> state = 1 ;
 event_set ( & ns -> event , ns -> socket , EV_READ | EV_PERSIST , nameserver_ready_callback , ns ) ;
 if ( event_add ( & ns -> event , NULL ) < 0 ) {
 err = 2 ;
 goto out2 ;
 }
 log ( EVDNS_LOG_DEBUG , "Added nameserver %s" , debug_ntoa ( address ) ) ;
 if ( ! server_head ) {
 ns -> next = ns -> prev = ns ;
 server_head = ns ;
 }
 else {
 ns -> next = server_head -> next ;
 ns -> prev = server_head ;
 server_head -> next = ns ;
 if ( server_head -> prev == server_head ) {
 server_head -> prev = ns ;
 }
 }
 global_good_nameservers ++ ;
 return 0 ;
 out2 : CLOSE_SOCKET ( ns -> socket ) ;
 out1 : free ( ns ) ;
 log ( EVDNS_LOG_WARN , "Unable to add nameserver %s: error %d" , debug_ntoa ( address ) , err ) ;
 return err ;
 }

int _evsignal_set_handler ( struct event_base * base , int evsignal , void ( * handler ) ( int ) ) {
 # ifdef HAVE_SIGACTION struct sigaction sa ;
 # else ev_sighandler_t sh ;
 # endif struct evsignal_info * sig = & base -> sig ;
 void * p ;
 if ( evsignal >= sig -> sh_old_max ) {
 int new_max = evsignal + 1 ;
 event_debug ( ( "%s: evsignal (%d) >= sh_old_max (%d), resizing" , __func__ , evsignal , sig -> sh_old_max ) ) ;
 p = realloc ( sig -> sh_old , new_max * sizeof ( * sig -> sh_old ) ) ;
 if ( p == NULL ) {
 event_warn ( "realloc" ) ;
 return ( - 1 ) ;
 }
 memset ( ( char * ) p + sig -> sh_old_max * sizeof ( * sig -> sh_old ) , 0 , ( new_max - sig -> sh_old_max ) * sizeof ( * sig -> sh_old ) ) ;
 sig -> sh_old_max = new_max ;
 sig -> sh_old = p ;
 }
 sig -> sh_old [ evsignal ] = malloc ( sizeof * sig -> sh_old [ evsignal ] ) ;
 if ( sig -> sh_old [ evsignal ] == NULL ) {
 event_warn ( "malloc" ) ;
 return ( - 1 ) ;
 }
 # ifdef HAVE_SIGACTION memset ( & sa , 0 , sizeof ( sa ) ) ;
 sa . sa_handler = handler ;
 sa . sa_flags |= SA_RESTART ;
 sigfillset ( & sa . sa_mask ) ;
 if ( sigaction ( evsignal , & sa , sig -> sh_old [ evsignal ] ) == - 1 ) {
 event_warn ( "sigaction" ) ;
 free ( sig -> sh_old [ evsignal ] ) ;
 return ( - 1 ) ;
 }
 # else if ( ( sh = signal ( evsignal , handler ) ) == SIG_ERR ) {
 event_warn ( "signal" ) ;
 free ( sig -> sh_old [ evsignal ] ) ;
 return ( - 1 ) ;
 }
 * sig -> sh_old [ evsignal ] = sh ;
 # endif return ( 0 ) ;
 }

