 struct process process ;
 memset ( & process , 0 , sizeof ( process ) ) ;
 process . client = client ;
 if ( argv [ 0 ] == NULL ) {
 notice ( "empty command from user %s" , user ) ;
 client -> error ( client , ERROR_BAD_COMMAND , "Invalid command token" ) ;
