 notice ( "access denied: user %s, command %s%s%s" , user , command , ( subcommand == NULL ) ? "" : " " , ( subcommand == NULL ) ? "" : subcommand ) ;
 client -> error ( client , ERROR_ACCESS , "Access denied" ) ;
 goto done ;
 }
 if ( help ) {
