 if ( ok ) {
 if ( WIFEXITED ( process . status ) ) process . status = ( signed int ) WEXITSTATUS ( process . status ) ;
 else process . status = - 1 ;
 client -> finish ( client , process . output , process . status ) ;
 }
 status = process . status ;
 done : free ( command ) ;
 free ( subcommand ) ;
 free ( helpsubcommand ) ;
