static char * php_zip_make_relative_path ( char * path , int path_len ) {
 char * path_begin = path ;
 size_t i ;
 if ( path_len < 1 || path == NULL ) {
 return NULL ;
 }
 if ( IS_SLASH ( path [ 0 ] ) ) {
 return path + 1 ;
 }
 i = path_len ;
 while ( 1 ) {
 while ( i > 0 && ! IS_SLASH ( path [ i ] ) ) {
 i -- ;
 }
 if ( ! i ) {
 return path ;
 }
 if ( i >= 2 && ( path [ i - 1 ] == '.' || path [ i - 1 ] == ':' ) ) {
 path_begin = path + i + 1 ;
 break ;
 }
 i -- ;
 }
 return path_begin ;
 }

