 if ( ! ( s -> flags & FLAG_INTERFRAME ) ) s -> flags |= FLAG_KEYFRAME ;
 }
 else s -> flags = FLAG_KEYFRAME ;
 }
 else s -> flags = FLAG_KEYFRAME ;
