static void set_good_speed_feature ( VP9_COMP * cpi , VP9_COMMON * cm , SPEED_FEATURES * sf , int speed ) {
 const int boosted = frame_is_boosted ( cpi ) ;
 sf -> adaptive_rd_thresh = 1 ;
 sf -> allow_skip_recode = 1 ;
 if ( speed >= 1 ) {
 sf -> use_square_partition_only = ! frame_is_intra_only ( cm ) ;
 sf -> less_rectangular_check = 1 ;
 if ( MIN ( cm -> width , cm -> height ) >= 720 ) sf -> disable_split_mask = cm -> show_frame ? DISABLE_ALL_SPLIT : DISABLE_ALL_INTER_SPLIT ;
 else sf -> disable_split_mask = DISABLE_COMPOUND_SPLIT ;
 sf -> use_rd_breakout = 1 ;
 sf -> adaptive_motion_search = 1 ;
 sf -> mv . auto_mv_step_size = 1 ;
 sf -> adaptive_rd_thresh = 2 ;
 sf -> mv . subpel_iters_per_step = 1 ;
 sf -> mode_skip_start = 10 ;
 sf -> adaptive_pred_interp_filter = 1 ;
 sf -> recode_loop = ALLOW_RECODE_KFARFGF ;
 sf -> intra_y_mode_mask [ TX_32X32 ] = INTRA_DC_H_V ;
 sf -> intra_uv_mode_mask [ TX_32X32 ] = INTRA_DC_H_V ;
 sf -> intra_y_mode_mask [ TX_16X16 ] = INTRA_DC_H_V ;
 sf -> intra_uv_mode_mask [ TX_16X16 ] = INTRA_DC_H_V ;
 sf -> tx_size_search_breakout = 1 ;
 if ( MIN ( cm -> width , cm -> height ) >= 720 ) sf -> partition_search_breakout_dist_thr = ( 1 << 23 ) ;
 else sf -> partition_search_breakout_dist_thr = ( 1 << 21 ) ;
 sf -> partition_search_breakout_rate_thr = 500 ;
 }
 if ( speed >= 2 ) {
 sf -> tx_size_search_method = frame_is_boosted ( cpi ) ? USE_FULL_RD : USE_LARGESTALL ;
 if ( MIN ( cm -> width , cm -> height ) >= 720 ) {
 sf -> lf_motion_threshold = LOW_MOTION_THRESHOLD ;
 sf -> last_partitioning_redo_frequency = 3 ;
 sf -> disable_split_mask = cm -> show_frame ? DISABLE_ALL_SPLIT : DISABLE_ALL_INTER_SPLIT ;
 sf -> adaptive_pred_interp_filter = 0 ;
 }
 else {
 sf -> disable_split_mask = LAST_AND_INTRA_SPLIT_ONLY ;
 sf -> last_partitioning_redo_frequency = 2 ;
 sf -> lf_motion_threshold = NO_MOTION_THRESHOLD ;
 }
 sf -> reference_masking = 1 ;
 sf -> mode_search_skip_flags = FLAG_SKIP_INTRA_DIRMISMATCH | FLAG_SKIP_INTRA_BESTINTER | FLAG_SKIP_COMP_BESTINTRA | FLAG_SKIP_INTRA_LOWVAR ;
 sf -> disable_filter_search_var_thresh = 100 ;
 sf -> comp_inter_joint_search_thresh = BLOCK_SIZES ;
 sf -> auto_min_max_partition_size = CONSTRAIN_NEIGHBORING_MIN_MAX ;
 sf -> use_lastframe_partitioning = LAST_FRAME_PARTITION_LOW_MOTION ;
 sf -> adjust_partitioning_from_last_frame = 1 ;
 if ( MIN ( cm -> width , cm -> height ) >= 720 ) sf -> partition_search_breakout_dist_thr = ( 1 << 24 ) ;
 else sf -> partition_search_breakout_dist_thr = ( 1 << 22 ) ;
 sf -> partition_search_breakout_rate_thr = 700 ;
 }
 if ( speed >= 3 ) {
 sf -> tx_size_search_method = frame_is_intra_only ( cm ) ? USE_FULL_RD : USE_LARGESTALL ;
 if ( MIN ( cm -> width , cm -> height ) >= 720 ) {
 sf -> disable_split_mask = DISABLE_ALL_SPLIT ;
 }
 else {
 sf -> max_intra_bsize = BLOCK_32X32 ;
 sf -> disable_split_mask = DISABLE_ALL_INTER_SPLIT ;
 }
 sf -> adaptive_pred_interp_filter = 0 ;
 sf -> adaptive_mode_search = 1 ;
 sf -> cb_partition_search = ! boosted ;
 sf -> cb_pred_filter_search = 1 ;
 sf -> alt_ref_search_fp = 1 ;
 sf -> motion_field_mode_search = ! boosted ;
 sf -> lf_motion_threshold = LOW_MOTION_THRESHOLD ;
 sf -> last_partitioning_redo_frequency = 2 ;
 sf -> recode_loop = ALLOW_RECODE_KFMAXBW ;
 sf -> adaptive_rd_thresh = 3 ;
 sf -> mode_skip_start = 6 ;
 sf -> intra_y_mode_mask [ TX_32X32 ] = INTRA_DC ;
 sf -> intra_uv_mode_mask [ TX_32X32 ] = INTRA_DC ;
 sf -> adaptive_interp_filter_search = 1 ;
 if ( MIN ( cm -> width , cm -> height ) >= 720 ) sf -> partition_search_breakout_dist_thr = ( 1 << 25 ) ;
 else sf -> partition_search_breakout_dist_thr = ( 1 << 23 ) ;
 sf -> partition_search_breakout_rate_thr = 1000 ;
 }
 if ( speed >= 4 ) {
 sf -> use_square_partition_only = 1 ;
 sf -> tx_size_search_method = USE_LARGESTALL ;
 sf -> disable_split_mask = DISABLE_ALL_SPLIT ;
 sf -> adaptive_rd_thresh = 4 ;
 sf -> mode_search_skip_flags |= FLAG_SKIP_COMP_REFMISMATCH | FLAG_EARLY_TERMINATE ;
 sf -> disable_filter_search_var_thresh = 200 ;
 sf -> use_lastframe_partitioning = LAST_FRAME_PARTITION_ALL ;
 sf -> use_lp32x32fdct = 1 ;
 sf -> use_fast_coef_updates = ONE_LOOP_REDUCED ;
 sf -> use_fast_coef_costing = 1 ;
 if ( MIN ( cm -> width , cm -> height ) >= 720 ) sf -> partition_search_breakout_dist_thr = ( 1 << 26 ) ;
 else sf -> partition_search_breakout_dist_thr = ( 1 << 24 ) ;
 sf -> partition_search_breakout_rate_thr = 1500 ;
 }
 if ( speed >= 5 ) {
 int i ;
 sf -> partition_search_type = FIXED_PARTITION ;
 sf -> optimize_coefficients = 0 ;
 sf -> mv . search_method = HEX ;
 sf -> disable_filter_search_var_thresh = 500 ;
 for ( i = 0 ;
 i < TX_SIZES ;
 ++ i ) {
 sf -> intra_y_mode_mask [ i ] = INTRA_DC ;
 sf -> intra_uv_mode_mask [ i ] = INTRA_DC ;
 }
 cpi -> allow_encode_breakout = ENCODE_BREAKOUT_ENABLED ;
 }
 if ( speed >= 6 ) {
 sf -> mv . reduce_first_step_size = 1 ;
 }
 }

int gx_device_delete_output_file ( const gx_device * dev , const char * fname ) {
 gs_parsed_file_name_t parsed ;
 const char * fmt ;
 char * pfname = ( char * ) gs_alloc_bytes ( dev -> memory , gp_file_name_sizeof , "gx_device_delete_output_file(pfname)" ) ;
 int code ;
 if ( pfname == NULL ) {
 code = gs_note_error ( gs_error_VMerror ) ;
 goto done ;
 }
 code = gx_parse_output_file_name ( & parsed , & fmt , fname , strlen ( fname ) , dev -> memory ) ;
 if ( code < 0 ) {
 goto done ;
 }
 if ( parsed . iodev && ! strcmp ( parsed . iodev -> dname , "%stdout%" ) ) goto done ;
 if ( fmt ) {
 long count1 = dev -> PageCount + 1 ;
 while ( * fmt != 'l' && * fmt != '%' ) -- fmt ;
 if ( * fmt == 'l' ) gs_sprintf ( pfname , parsed . fname , count1 ) ;
 else gs_sprintf ( pfname , parsed . fname , ( int ) count1 ) ;
 }
 else if ( parsed . len && strchr ( parsed . fname , '%' ) ) gs_sprintf ( pfname , parsed . fname ) ;
 else pfname [ 0 ] = 0 ;
 if ( pfname [ 0 ] ) {
 parsed . fname = pfname ;
 parsed . len = strlen ( parsed . fname ) ;
 }
 if ( parsed . iodev ) code = parsed . iodev -> procs . delete_file ( ( gx_io_device * ) ( & parsed . iodev ) , ( const char * ) parsed . fname ) ;
 else code = gs_note_error ( gs_error_invalidfileaccess ) ;
 done : if ( pfname != NULL ) gs_free_object ( dev -> memory , pfname , "gx_device_delete_output_file(pfname)" ) ;
 return ( code ) ;
 }

static void extrapolate_isf ( float isf [ LP_ORDER_16k ] ) {
 float diff_isf [ LP_ORDER - 2 ] , diff_mean ;
 float corr_lag [ 3 ] ;
 float est , scale ;
 int i , j , i_max_corr ;
 isf [ LP_ORDER_16k - 1 ] = isf [ LP_ORDER - 1 ] ;
 for ( i = 0 ;
 i < LP_ORDER - 2 ;
 i ++ ) diff_isf [ i ] = isf [ i + 1 ] - isf [ i ] ;
 diff_mean = 0.0 ;
 for ( i = 2 ;
 i < LP_ORDER - 2 ;
 i ++ ) diff_mean += diff_isf [ i ] * ( 1.0f / ( LP_ORDER - 4 ) ) ;
 i_max_corr = 0 ;
 for ( i = 0 ;
 i < 3 ;
 i ++ ) {
 corr_lag [ i ] = auto_correlation ( diff_isf , diff_mean , i + 2 ) ;
 if ( corr_lag [ i ] > corr_lag [ i_max_corr ] ) i_max_corr = i ;
 }
 i_max_corr ++ ;
 for ( i = LP_ORDER - 1 ;
 i < LP_ORDER_16k - 1 ;
 i ++ ) isf [ i ] = isf [ i - 1 ] + isf [ i - 1 - i_max_corr ] - isf [ i - 2 - i_max_corr ] ;
 est = 7965 + ( isf [ 2 ] - isf [ 3 ] - isf [ 4 ] ) / 6.0 ;
 scale = 0.5 * ( FFMIN ( est , 7600 ) - isf [ LP_ORDER - 2 ] ) / ( isf [ LP_ORDER_16k - 2 ] - isf [ LP_ORDER - 2 ] ) ;
 for ( i = LP_ORDER - 1 , j = 0 ;
 i < LP_ORDER_16k - 1 ;
 i ++ , j ++ ) diff_isf [ j ] = scale * ( isf [ i ] - isf [ i - 1 ] ) ;
 for ( i = 1 ;
 i < LP_ORDER_16k - LP_ORDER ;
 i ++ ) if ( diff_isf [ i ] + diff_isf [ i - 1 ] < 5.0 ) {
 if ( diff_isf [ i ] > diff_isf [ i - 1 ] ) {
 diff_isf [ i - 1 ] = 5.0 - diff_isf [ i ] ;
 }
 else diff_isf [ i ] = 5.0 - diff_isf [ i - 1 ] ;
 }
 for ( i = LP_ORDER - 1 , j = 0 ;
 i < LP_ORDER_16k - 1 ;
 i ++ , j ++ ) isf [ i ] = isf [ i - 1 ] + diff_isf [ j ] * ( 1.0f / ( 1 << 15 ) ) ;
 for ( i = 0 ;
 i < LP_ORDER_16k - 1 ;
 i ++ ) isf [ i ] *= 0.8 ;
 }

static void vga_draw_line24_be ( VGACommonState * s1 , uint8_t * d , const uint8_t * s , int width ) {
 int w ;
 uint32_t r , g , b ;
 w = width ;
 do {
 r = s [ 0 ] ;
 g = s [ 1 ] ;
 b = s [ 2 ] ;
 ( ( uint32_t * ) d ) [ 0 ] = rgb_to_pixel32 ( r , g , b ) ;
 s += 3 ;
 d += 4 ;
 }
 while ( -- w != 0 ) ;
 }

