 for ( j = 0 ;
 j < 4 ;
 ++ j ) {
 if ( sads [ j ] < best_sad ) {
 const MV mv = {
 ref_mv -> row + neighbors [ j ] . row , ref_mv -> col + neighbors [ j ] . col }
 ;
 sads [ j ] += mvsad_err_cost ( x , & mv , & fcenter_mv , error_per_bit ) ;
 if ( sads [ j ] < best_sad ) {
 best_sad = sads [ j ] ;
 best_site = j ;
 }
 }
 }
 }
 else {
 for ( j = 0 ;
 j < 4 ;
 ++ j ) {
 const MV mv = {
 ref_mv -> row + neighbors [ j ] . row , ref_mv -> col + neighbors [ j ] . col }
 ;
