 patres = pdf_dict_get ( ctx , csi -> rdb , PDF_NAME_Pattern ) ;
 if ( ! patres ) fz_throw ( ctx , FZ_ERROR_SYNTAX , "cannot find Pattern dictionary" ) ;
 patobj = pdf_dict_gets ( ctx , patres , csi -> name ) ;
 if ( ! patobj ) fz_throw ( ctx , FZ_ERROR_SYNTAX , "cannot find Pattern resource '%s'" , csi -> name ) ;
 type = pdf_dict_get ( ctx , patobj , PDF_NAME_PatternType ) ;
 if ( pdf_to_int ( ctx , type ) == 1 ) {
 if ( proc -> op_SC_pattern && proc -> op_sc_pattern ) {
 pdf_pattern * pat = pdf_load_pattern ( ctx , csi -> doc , patobj ) ;
 fz_try ( ctx ) {
 if ( stroke ) proc -> op_SC_pattern ( ctx , proc , csi -> name , pat , csi -> top , csi -> stack ) ;
 else proc -> op_sc_pattern ( ctx , proc , csi -> name , pat , csi -> top , csi -> stack ) ;
 }
 fz_always ( ctx ) pdf_drop_pattern ( ctx , pat ) ;
 fz_catch ( ctx ) fz_rethrow ( ctx ) ;
 }
 }
 else if ( pdf_to_int ( ctx , type ) == 2 ) {
 if ( proc -> op_SC_shade && proc -> op_sc_shade ) {
 fz_shade * shade = pdf_load_shading ( ctx , csi -> doc , patobj ) ;
 fz_try ( ctx ) {
 if ( stroke ) proc -> op_SC_shade ( ctx , proc , csi -> name , shade ) ;
 else proc -> op_sc_shade ( ctx , proc , csi -> name , shade ) ;
 }
 fz_always ( ctx ) fz_drop_shade ( ctx , shade ) ;
 fz_catch ( ctx ) fz_rethrow ( ctx ) ;
 }
 }
 else {
 fz_throw ( ctx , FZ_ERROR_SYNTAX , "unknown pattern type: %d" , pdf_to_int ( ctx , type ) ) ;
 }
 }
 else {
 if ( proc -> op_SC_color && proc -> op_sc_color ) {
 if ( stroke ) proc -> op_SC_color ( ctx , proc , csi -> top , csi -> stack ) ;
 else proc -> op_sc_color ( ctx , proc , csi -> top , csi -> stack ) ;
 }
 }
 }

static int read_patterns ( AVCodecContext * avctx , GetBitContext * gb , Bundle * b ) {
 int t , v ;
 const uint8_t * dec_end ;
 CHECK_READ_VAL ( gb , b , t ) ;
 dec_end = b -> cur_dec + t ;
 if ( dec_end > b -> data_end ) {
 av_log ( avctx , AV_LOG_ERROR , "Too many pattern values\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 while ( b -> cur_dec < dec_end ) {
 v = GET_HUFF ( gb , b -> tree ) ;
 v |= GET_HUFF ( gb , b -> tree ) << 4 ;
 * b -> cur_dec ++ = v ;
 }
 return 0 ;
 }

int kvm_arch_handle_exit ( CPUState * cs , struct kvm_run * run ) {
 X86CPU * cpu = X86_CPU ( cs ) ;
 uint64_t code ;
 int ret ;
 switch ( run -> exit_reason ) {
 case KVM_EXIT_HLT : DPRINTF ( "handle_hlt\n" ) ;
 qemu_mutex_lock_iothread ( ) ;
 ret = kvm_handle_halt ( cpu ) ;
 qemu_mutex_unlock_iothread ( ) ;
 break ;
 case KVM_EXIT_SET_TPR : ret = 0 ;
 break ;
 case KVM_EXIT_TPR_ACCESS : qemu_mutex_lock_iothread ( ) ;
 ret = kvm_handle_tpr_access ( cpu ) ;
 qemu_mutex_unlock_iothread ( ) ;
 break ;
 case KVM_EXIT_FAIL_ENTRY : code = run -> fail_entry . hardware_entry_failure_reason ;
 fprintf ( stderr , "KVM: entry failed, hardware error 0x%" PRIx64 "\n" , code ) ;
 if ( host_supports_vmx ( ) && code == VMX_INVALID_GUEST_STATE ) {
 fprintf ( stderr , "\nIf you're running a guest on an Intel machine without " "unrestricted mode\n" "support, the failure can be most likely due to the guest " "entering an invalid\n" "state for Intel VT. For example, the guest maybe running " "in big real mode\n" "which is not supported on less recent Intel processors." "\n\n" ) ;
 }
 ret = - 1 ;
 break ;
 case KVM_EXIT_EXCEPTION : fprintf ( stderr , "KVM: exception %d exit (error code 0x%x)\n" , run -> ex . exception , run -> ex . error_code ) ;
 ret = - 1 ;
 break ;
 case KVM_EXIT_DEBUG : DPRINTF ( "kvm_exit_debug\n" ) ;
 qemu_mutex_lock_iothread ( ) ;
 ret = kvm_handle_debug ( cpu , & run -> debug . arch ) ;
 qemu_mutex_unlock_iothread ( ) ;
 break ;
 case KVM_EXIT_HYPERV : ret = kvm_hv_handle_exit ( cpu , & run -> hyperv ) ;
 break ;
 case KVM_EXIT_IOAPIC_EOI : ioapic_eoi_broadcast ( run -> eoi . vector ) ;
 ret = 0 ;
 break ;
 default : fprintf ( stderr , "KVM: unknown exit reason %d\n" , run -> exit_reason ) ;
 ret = - 1 ;
 break ;
 }
 return ret ;
 }

const char * keydb_get_resource_name ( KEYDB_HANDLE hd ) {
 int idx ;
 const char * s = NULL ;
 if ( ! hd ) return NULL ;
 if ( hd -> found >= 0 && hd -> found < hd -> used ) idx = hd -> found ;
 else if ( hd -> current >= 0 && hd -> current < hd -> used ) idx = hd -> current ;
 else idx = 0 ;
 switch ( hd -> active [ idx ] . type ) {
 case KEYDB_RESOURCE_TYPE_NONE : s = NULL ;
 break ;
 case KEYDB_RESOURCE_TYPE_KEYRING : s = keyring_get_resource_name ( hd -> active [ idx ] . u . kr ) ;
