 DPRINTF ( "xhci: output ep%d.%d context: %08x %08x %08x %08x %08x\n" , i / 2 , i % 2 , ep_ctx [ 0 ] , ep_ctx [ 1 ] , ep_ctx [ 2 ] , ep_ctx [ 3 ] , ep_ctx [ 4 ] ) ;
