 if ( PyString_GET_SIZE ( self ) == 0 ) return PyBool_FromLong ( 0 ) ;
 e = p + PyString_GET_SIZE ( self ) ;
 cased = 0 ;
 previous_is_cased = 0 ;
 for ( ;
 p < e ;
 p ++ ) {
 register const unsigned char ch = * p ;
 if ( isupper ( ch ) ) {
 if ( previous_is_cased ) return PyBool_FromLong ( 0 ) ;
 previous_is_cased = 1 ;
 cased = 1 ;
