 av_dlog ( s -> avctx , "%d %d %d %d\n" , pic_arg -> linesize [ 0 ] , pic_arg -> linesize [ 1 ] , s -> linesize , s -> uvlinesize ) ;
 if ( direct ) {
 i = ff_find_unused_picture ( s , 1 ) ;
 if ( i < 0 ) return i ;
 pic = & s -> picture [ i ] . f ;
 pic -> reference = 3 ;
 for ( i = 0 ;
 i < 4 ;
 i ++ ) {
 pic -> data [ i ] = pic_arg -> data [ i ] ;
 pic -> linesize [ i ] = pic_arg -> linesize [ i ] ;
 }
 if ( ff_alloc_picture ( s , ( Picture * ) pic , 1 ) < 0 ) {
 return - 1 ;
 }
 }
 else {
 i = ff_find_unused_picture ( s , 0 ) ;
 if ( i < 0 ) return i ;
 pic = & s -> picture [ i ] . f ;
 pic -> reference = 3 ;
 if ( ff_alloc_picture ( s , ( Picture * ) pic , 0 ) < 0 ) {
 return - 1 ;
 }
 if ( pic -> data [ 0 ] + INPLACE_OFFSET == pic_arg -> data [ 0 ] && pic -> data [ 1 ] + INPLACE_OFFSET == pic_arg -> data [ 1 ] && pic -> data [ 2 ] + INPLACE_OFFSET == pic_arg -> data [ 2 ] ) {
 }
 else {
 int h_chroma_shift , v_chroma_shift ;
 av_pix_fmt_get_chroma_sub_sample ( s -> avctx -> pix_fmt , & h_chroma_shift , & v_chroma_shift ) ;
 for ( i = 0 ;
 i < 3 ;
 i ++ ) {
 int src_stride = pic_arg -> linesize [ i ] ;
 int dst_stride = i ? s -> uvlinesize : s -> linesize ;
 int h_shift = i ? h_chroma_shift : 0 ;
 int v_shift = i ? v_chroma_shift : 0 ;
 int w = s -> width >> h_shift ;
 int h = s -> height >> v_shift ;
 uint8_t * src = pic_arg -> data [ i ] ;
 uint8_t * dst = pic -> data [ i ] ;
 if ( ! s -> avctx -> rc_buffer_size ) dst += INPLACE_OFFSET ;
 if ( src_stride == dst_stride ) memcpy ( dst , src , src_stride * h ) ;
 else {
 while ( h -- ) {
 memcpy ( dst , src , w ) ;
 dst += dst_stride ;
 src += src_stride ;
 }
 }
 }
 }
 }
 copy_picture_attributes ( s , pic , pic_arg ) ;
 pic -> display_picture_number = display_picture_number ;
 pic -> pts = pts ;
 }
 for ( i = 1 ;
 i < MAX_PICTURE_COUNT ;
 i ++ ) s -> input_picture [ i - 1 ] = s -> input_picture [ i ] ;
 s -> input_picture [ encoding_delay ] = ( Picture * ) pic ;
