 }
 }
 return - 1 ;
 }
 else {
 if ( cpu_memory_rw_debug ( env , ip , opcode , sizeof ( opcode ) , 0 ) < 0 ) {
 return - 1 ;
 }
 for ( i = 0 ;
 i < ARRAY_SIZE ( tpr_instr ) ;
 i ++ ) {
