 p -> target_energy = 1081109975 * pow ( 10 , dbov / 10.0 ) * 0.75 ;
 memset ( p -> target_refl_coef , 0 , p -> order * sizeof ( * p -> target_refl_coef ) ) ;
 for ( i = 0 ;
