 make_lpc_coefs ( p -> lpc_coef , p -> refl_coef , p -> order ) ;
 for ( i = 0 ;
 i < p -> order ;
 i ++ ) e *= 1.0 - p -> refl_coef [ i ] * p -> refl_coef [ i ] ;
