 band < p -> total_subbands ;
 band ++ ) {
 index = category [ band ] ;
 if ( category [ band ] < 7 ) {
 if ( unpack_SQVH ( q , p , category [ band ] , subband_coef_index , subband_coef_sign ) ) {
 index = 7 ;
 for ( j = 0 ;
 j < p -> total_subbands ;
 j ++ ) category [ band + j ] = 7 ;
 }
 }
 if ( index >= 7 ) {
