 if ( s -> top_field_first ) s -> current_picture_ptr -> f . repeat_pict = 4 ;
 else s -> current_picture_ptr -> f . repeat_pict = 2 ;
 }
 else if ( s -> progressive_frame ) {
 s -> current_picture_ptr -> f . repeat_pict = 1 ;
