 if ( s -> picture_structure == PICT_BOTTOM_FIELD ) {
 s -> current_picture . f . data [ i ] += s -> current_picture_ptr -> f . linesize [ i ] ;
 }
 }
 }
 if ( avctx -> hwaccel ) {
