static PyObject * string_repeat ( register PyStringObject * a , register Py_ssize_t n ) {
 register Py_ssize_t i ;
 register Py_ssize_t j ;
 register Py_ssize_t size ;
 register PyStringObject * op ;
 size_t nbytes ;
 if ( n < 0 ) n = 0 ;
 if ( n && Py_SIZE ( a ) > PY_SSIZE_T_MAX / n ) {
 PyErr_SetString ( PyExc_OverflowError , "repeated string is too long" ) ;
 return NULL ;
 }
 size = Py_SIZE ( a ) * n ;
 if ( size == Py_SIZE ( a ) && PyString_CheckExact ( a ) ) {
 Py_INCREF ( a ) ;
 return ( PyObject * ) a ;
 }
 nbytes = ( size_t ) size ;
 if ( nbytes + PyStringObject_SIZE <= nbytes ) {
 PyErr_SetString ( PyExc_OverflowError , "repeated string is too long" ) ;
 return NULL ;
 }
 op = ( PyStringObject * ) PyObject_MALLOC ( PyStringObject_SIZE + nbytes ) ;
 if ( op == NULL ) return PyErr_NoMemory ( ) ;
 ( void ) PyObject_INIT_VAR ( op , & PyString_Type , size ) ;
 op -> ob_shash = - 1 ;
 op -> ob_sstate = SSTATE_NOT_INTERNED ;
 op -> ob_sval [ size ] = '\0' ;
 if ( Py_SIZE ( a ) == 1 && n > 0 ) {
 memset ( op -> ob_sval , a -> ob_sval [ 0 ] , n ) ;
 return ( PyObject * ) op ;
 }
 i = 0 ;
 if ( i < size ) {
 Py_MEMCPY ( op -> ob_sval , a -> ob_sval , Py_SIZE ( a ) ) ;
 i = Py_SIZE ( a ) ;
 }
 while ( i < size ) {
 j = ( i <= size - i ) ? i : size - i ;
 Py_MEMCPY ( op -> ob_sval + i , op -> ob_sval , j ) ;
 i += j ;
 }
 return ( PyObject * ) op ;
 }

