static void pxa2xx_ssp_write ( void * opaque , hwaddr addr , uint64_t value64 , unsigned size ) {
 PXA2xxSSPState * s = ( PXA2xxSSPState * ) opaque ;
 uint32_t value = value64 ;
 switch ( addr ) {
 case SSCR0 : s -> sscr [ 0 ] = value & 0xc7ffffff ;
 s -> enable = value & SSCR0_SSE ;
 if ( value & SSCR0_MOD ) printf ( "%s: Attempt to use network mode\n" , __FUNCTION__ ) ;
 if ( s -> enable && SSCR0_DSS ( value ) < 4 ) printf ( "%s: Wrong data size: %i bits\n" , __FUNCTION__ , SSCR0_DSS ( value ) ) ;
 if ( ! ( value & SSCR0_SSE ) ) {
 s -> sssr = 0 ;
 s -> ssitr = 0 ;
 s -> rx_level = 0 ;
 }
 pxa2xx_ssp_fifo_update ( s ) ;
 break ;
 case SSCR1 : s -> sscr [ 1 ] = value ;
 if ( value & ( SSCR1_LBM | SSCR1_EFWR ) ) printf ( "%s: Attempt to use SSP test mode\n" , __FUNCTION__ ) ;
 pxa2xx_ssp_fifo_update ( s ) ;
 break ;
 case SSPSP : s -> sspsp = value ;
 break ;
 case SSTO : s -> ssto = value ;
 break ;
 case SSITR : s -> ssitr = value & SSITR_INT ;
 pxa2xx_ssp_int_update ( s ) ;
 break ;
 case SSSR : s -> sssr &= ~ ( value & SSSR_RW ) ;
 pxa2xx_ssp_int_update ( s ) ;
 break ;
 case SSDR : if ( SSCR0_UWIRE ( s -> sscr [ 0 ] ) ) {
 if ( s -> sscr [ 1 ] & SSCR1_MWDS ) value &= 0xffff ;
 else value &= 0xff ;
 }
 else value &= ( 1 << SSCR0_DSS ( s -> sscr [ 0 ] ) ) - 1 ;
 if ( s -> enable ) {
 uint32_t readval ;
 readval = ssi_transfer ( s -> bus , value ) ;
 if ( s -> rx_level < 0x10 ) {
 s -> rx_fifo [ ( s -> rx_start + s -> rx_level ++ ) & 0xf ] = readval ;
 }
 else {
 s -> sssr |= SSSR_ROR ;
 }
 }
 pxa2xx_ssp_fifo_update ( s ) ;
 break ;
 case SSTSA : s -> sstsa = value ;
 break ;
 case SSRSA : s -> ssrsa = value ;
 break ;
 case SSACD : s -> ssacd = value ;
 break ;
 default : printf ( "%s: Bad register " REG_FMT "\n" , __FUNCTION__ , addr ) ;
 break ;
 }
 }

static void pxa2xx_ssp_fifo_update ( PXA2xxSSPState * s ) {
 s -> sssr &= ~ ( 0xf << 12 ) ;
 s -> sssr &= ~ ( 0xf << 8 ) ;
 s -> sssr &= ~ SSSR_TFS ;
 s -> sssr &= ~ SSSR_TNF ;
 if ( s -> enable ) {
 s -> sssr |= ( ( s -> rx_level - 1 ) & 0xf ) << 12 ;
 if ( s -> rx_level >= SSCR1_RFT ( s -> sscr [ 1 ] ) ) s -> sssr |= SSSR_RFS ;
 else s -> sssr &= ~ SSSR_RFS ;
 if ( s -> rx_level ) s -> sssr |= SSSR_RNE ;
 else s -> sssr &= ~ SSSR_RNE ;
 s -> sssr |= SSSR_TFS ;
 s -> sssr |= SSSR_TNF ;
 }
 pxa2xx_ssp_int_update ( s ) ;
 }

