 if ( ! bits ) {
 t = 1 - ( get_bits1 ( gb ) << 1 ) ;
 }
 else {
 t = get_bits ( gb , bits ) | 1 << bits ;
 sign = - get_bits1 ( gb ) ;
 t = ( t ^ sign ) - sign ;
 }
