 coef_idx [ coef_count ++ ] = ccoef ;
 }
 }
 break ;
 case 1 : mode_list [ list_pos ] = 2 ;
 for ( i = 0 ;
 i < 3 ;
 i ++ ) {
 ccoef += 4 ;
 coef_list [ list_end ] = ccoef ;
 mode_list [ list_end ++ ] = 2 ;
 }
 break ;
 case 3 : if ( ! bits ) {
 t = 1 - ( get_bits1 ( gb ) << 1 ) ;
 }
