 case X509_V_ERR_DEPTH_ZERO_SELF_SIGNED_CERT : case X509_V_ERR_SELF_SIGNED_CERT_IN_CHAIN : case X509_V_ERR_UNABLE_TO_GET_ISSUER_CERT_LOCALLY : case X509_V_ERR_UNABLE_TO_VERIFY_LEAF_SIGNATURE : case X509_V_ERR_CERT_CHAIN_TOO_LONG : case X509_V_ERR_PATH_LENGTH_EXCEEDED : case X509_V_ERR_INVALID_CA : al = SSL_AD_UNKNOWN_CA ;
