static inline int sub_left_prediction ( HYuvContext * s , uint8_t * dst , const uint8_t * src , int w , int left ) {
 int i ;
 if ( w < 32 ) {
 for ( i = 0 ;
 i < w ;
 i ++ ) {
 const int temp = src [ i ] ;
 dst [ i ] = temp - left ;
 left = temp ;
 }
 return left ;
 }
 else {
 for ( i = 0 ;
 i < 16 ;
 i ++ ) {
 const int temp = src [ i ] ;
 dst [ i ] = temp - left ;
 left = temp ;
 }
 s -> dsp . diff_bytes ( dst + 16 , src + 16 , src + 15 , w - 16 ) ;
 return src [ w - 1 ] ;
 }
 }

static int get_active_cq_level ( const RATE_CONTROL * rc , const VP9EncoderConfig * const oxcf ) {
 static const double cq_adjust_threshold = 0.5 ;
 int active_cq_level = oxcf -> cq_level ;
 if ( oxcf -> rc_mode == VPX_CQ && rc -> total_target_bits > 0 ) {
 const double x = ( double ) rc -> total_actual_bits / rc -> total_target_bits ;
 if ( x < cq_adjust_threshold ) {
 active_cq_level = ( int ) ( active_cq_level * x / cq_adjust_threshold ) ;
 }
 }
 return active_cq_level ;
 }

static int init_block_mapping ( Vp3DecodeContext * s ) {
 int sb_x , sb_y , plane ;
 int x , y , i , j = 0 ;
 for ( plane = 0 ;
 plane < 3 ;
 plane ++ ) {
 int sb_width = plane ? s -> c_superblock_width : s -> y_superblock_width ;
 int sb_height = plane ? s -> c_superblock_height : s -> y_superblock_height ;
 int frag_width = s -> fragment_width [ ! ! plane ] ;
 int frag_height = s -> fragment_height [ ! ! plane ] ;
 for ( sb_y = 0 ;
 sb_y < sb_height ;
 sb_y ++ ) for ( sb_x = 0 ;
 sb_x < sb_width ;
 sb_x ++ ) for ( i = 0 ;
 i < 16 ;
 i ++ ) {
 x = 4 * sb_x + hilbert_offset [ i ] [ 0 ] ;
 y = 4 * sb_y + hilbert_offset [ i ] [ 1 ] ;
 if ( x < frag_width && y < frag_height ) s -> superblock_fragments [ j ++ ] = s -> fragment_start [ plane ] + y * frag_width + x ;
 else s -> superblock_fragments [ j ++ ] = - 1 ;
 }
 }
 return 0 ;
 }

