 }
 p -> pict_type = AV_PICTURE_TYPE_I ;
 ptr = p -> data [ 0 ] ;
 stride = p -> linesize [ 0 ] ;
 for ( y = 0 ;
 y < h && buf_end - buf >= w * bytes_per_pixel ;
 y ++ ) {
 # if HAVE_BIGENDIAN unsigned int x ;
