 x < w * bytes_per_pixel ;
 x += bytes_per_pixel ) AV_WN16 ( ptr + x , AV_RL16 ( buf + x ) ) ;
 # else memcpy ( ptr , buf , w * bytes_per_pixel ) ;
 # endif ptr += stride ;
