 }
 p_data = p_orig + 9 ;
 i_data -= 9 ;
 int i_count = ( i_data + i_max - 1 ) / i_max ;
 for ( int i = 0 ;
 i < i_count ;
 i ++ ) {
 int i_payload = __MIN ( i_max , i_data ) ;
 block_t * out = block_Alloc ( 18 + i_payload ) ;
 unsigned fragtype , numpkts ;
 if ( i_count == 1 ) {
 fragtype = 0 ;
 numpkts = 1 ;
 }
 else {
 numpkts = 0 ;
 if ( i == 0 ) fragtype = 1 ;
 else if ( i == i_count - 1 ) fragtype = 3 ;
 else fragtype = 2 ;
 }
