 h -> long_ref_count ++ ;
 }
 h -> cur_pic_ptr -> reference |= h -> picture_structure ;
 current_ref_assigned = 1 ;
 break ;
 case MMCO_SET_MAX_LONG : assert ( mmco [ i ] . long_arg <= 16 ) ;
 for ( j = mmco [ i ] . long_arg ;
 j < 16 ;
 j ++ ) {
