 case FOP_FUNC : if ( fop [ i ] . op . func . slen ) {
 ef_debug ( 1 , "@" ) ;
 len += add_data_segment ( & data , len , & fop [ i ] . op . func . string , fop [ i ] . op . func . slen ) ;
