 }
 break ;
 case FOP_TEST : if ( fop [ i ] . op . test . slen ) {
 ef_debug ( 1 , "@" ) ;
 len += add_data_segment ( & data , len , & fop [ i ] . op . test . string , fop [ i ] . op . test . slen ) ;
 }
 break ;
 case FOP_ASSIGN : if ( fop [ i ] . op . assign . slen ) {
 ef_debug ( 1 , "@" ) ;
