 REGISTER_DEFAULT_PUBKEYS ;
 rc = sexp_to_key ( s_pkey , 0 , GCRY_PK_USAGE_SIGN , NULL , & pkey , & module_key , NULL ) ;
 if ( rc ) goto leave ;
 init_encoding_ctx ( & ctx , PUBKEY_OP_VERIFY , gcry_pk_get_nbits ( s_pkey ) ) ;
 rc = sexp_data_to_mpi ( s_hash , & hash , & ctx ) ;
