 switch ( addr ) {
 case 0x00 : break ;
 case 0x40 : case 0x50 : case 0x60 : case 0x70 : case 0x80 : case 0x90 : case 0xA0 : case 0xB0 : openpic_cpu_write_internal ( opp , addr , val , get_current_cpu ( ) ) ;
