 EVP_AES_GCM_CTX * gctx = EVP_C_DATA ( EVP_AES_GCM_CTX , ctx ) ;
 if ( ! iv && ! key ) return 1 ;
 if ( key ) {
 do {
 # ifdef HWAES_CAPABLE if ( HWAES_CAPABLE ) {
 HWAES_set_encrypt_key ( key , EVP_CIPHER_CTX_key_length ( ctx ) * 8 , & gctx -> ks . ks ) ;
 CRYPTO_gcm128_init ( & gctx -> gcm , & gctx -> ks , ( block128_f ) HWAES_encrypt ) ;
 # ifdef HWAES_ctr32_encrypt_blocks gctx -> ctr = ( ctr128_f ) HWAES_ctr32_encrypt_blocks ;
 # else gctx -> ctr = NULL ;
 # endif break ;
 }
 else # endif # ifdef BSAES_CAPABLE if ( BSAES_CAPABLE ) {
 AES_set_encrypt_key ( key , EVP_CIPHER_CTX_key_length ( ctx ) * 8 , & gctx -> ks . ks ) ;
 CRYPTO_gcm128_init ( & gctx -> gcm , & gctx -> ks , ( block128_f ) AES_encrypt ) ;
 gctx -> ctr = ( ctr128_f ) bsaes_ctr32_encrypt_blocks ;
 break ;
 }
 else # endif # ifdef VPAES_CAPABLE if ( VPAES_CAPABLE ) {
 vpaes_set_encrypt_key ( key , EVP_CIPHER_CTX_key_length ( ctx ) * 8 , & gctx -> ks . ks ) ;
 CRYPTO_gcm128_init ( & gctx -> gcm , & gctx -> ks , ( block128_f ) vpaes_encrypt ) ;
 gctx -> ctr = NULL ;
 break ;
 }
 else # endif ( void ) 0 ;
 AES_set_encrypt_key ( key , EVP_CIPHER_CTX_key_length ( ctx ) * 8 , & gctx -> ks . ks ) ;
 CRYPTO_gcm128_init ( & gctx -> gcm , & gctx -> ks , ( block128_f ) AES_encrypt ) ;
 # ifdef AES_CTR_ASM gctx -> ctr = ( ctr128_f ) AES_ctr32_encrypt ;
 # else gctx -> ctr = NULL ;
 # endif }
 while ( 0 ) ;
 if ( iv == NULL && gctx -> iv_set ) iv = gctx -> iv ;
 if ( iv ) {
 CRYPTO_gcm128_setiv ( & gctx -> gcm , iv , gctx -> ivlen ) ;
 gctx -> iv_set = 1 ;
 }
 gctx -> key_set = 1 ;
 }
 else {
 if ( gctx -> key_set ) CRYPTO_gcm128_setiv ( & gctx -> gcm , iv , gctx -> ivlen ) ;
 else memcpy ( gctx -> iv , iv , gctx -> ivlen ) ;
 gctx -> iv_set = 1 ;
 gctx -> iv_gen = 0 ;
 }
 return 1 ;
 }

static int mss1_decode_frame ( AVCodecContext * avctx , void * data , int * got_frame , AVPacket * avpkt ) {
 const uint8_t * buf = avpkt -> data ;
 int buf_size = avpkt -> size ;
 MSS1Context * ctx = avctx -> priv_data ;
 MSS12Context * c = & ctx -> ctx ;
 GetBitContext gb ;
 ArithCoder acoder ;
 int pal_changed = 0 ;
 int ret ;
 init_get_bits ( & gb , buf , buf_size * 8 ) ;
 arith_init ( & acoder , & gb ) ;
 ctx -> pic . reference = 3 ;
 ctx -> pic . buffer_hints = FF_BUFFER_HINTS_VALID | FF_BUFFER_HINTS_READABLE | FF_BUFFER_HINTS_PRESERVE | FF_BUFFER_HINTS_REUSABLE ;
 if ( ( ret = avctx -> reget_buffer ( avctx , & ctx -> pic ) ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "reget_buffer() failed\n" ) ;
 return ret ;
 }
 c -> pal_pic = ctx -> pic . data [ 0 ] + ctx -> pic . linesize [ 0 ] * ( avctx -> height - 1 ) ;
 c -> pal_stride = - ctx -> pic . linesize [ 0 ] ;
 c -> keyframe = ! arith_get_bit ( & acoder ) ;
 if ( c -> keyframe ) {
 c -> corrupted = 0 ;
 ff_mss12_slicecontext_reset ( & ctx -> sc ) ;
 pal_changed = decode_pal ( c , & acoder ) ;
 ctx -> pic . key_frame = 1 ;
 ctx -> pic . pict_type = AV_PICTURE_TYPE_I ;
 }
 else {
 if ( c -> corrupted ) return AVERROR_INVALIDDATA ;
 ctx -> pic . key_frame = 0 ;
 ctx -> pic . pict_type = AV_PICTURE_TYPE_P ;
 }
 c -> corrupted = ff_mss12_decode_rect ( & ctx -> sc , & acoder , 0 , 0 , avctx -> width , avctx -> height ) ;
 if ( c -> corrupted ) return AVERROR_INVALIDDATA ;
 memcpy ( ctx -> pic . data [ 1 ] , c -> pal , AVPALETTE_SIZE ) ;
 ctx -> pic . palette_has_changed = pal_changed ;
 * got_frame = 1 ;
 * ( AVFrame * ) data = ctx -> pic ;
 return buf_size ;
 }

int cli_scanmschm ( cli_ctx * ctx ) {
 struct mschm_decompressor * mschm_d ;
 struct mschmd_header * mschm_h ;
 struct mschmd_file * mschm_f ;
 int ret ;
 int files ;
 int virus_num = 0 ;
 struct mspack_name mspack_fmap = {
 . fmap = * ctx -> fmap , }
 ;
 struct mspack_system_ex ops_ex ;
 memset ( & ops_ex , 0 , sizeof ( struct mspack_system_ex ) ) ;
 ops_ex . ops = mspack_sys_fmap_ops ;
 MSPACK_SYS_SELFTEST ( ret ) ;
 if ( ret ) {
 cli_dbgmsg ( "%s() failed at %d\n" , __func__ , __LINE__ ) ;
 return CL_EUNPACK ;
 }
 mschm_d = mspack_create_chm_decompressor ( & ops_ex . ops ) ;
 if ( ! mschm_d ) {
 cli_dbgmsg ( "%s() failed at %d\n" , __func__ , __LINE__ ) ;
 return CL_EUNPACK ;
 }
 mschm_h = mschm_d -> open ( mschm_d , ( char * ) & mspack_fmap ) ;
 if ( ! mschm_h ) {
 ret = CL_EFORMAT ;
 cli_dbgmsg ( "%s() failed at %d\n" , __func__ , __LINE__ ) ;
 goto out_dest ;
 }
 files = 0 ;
 for ( mschm_f = mschm_h -> files ;
 mschm_f ;
 mschm_f = mschm_f -> next ) {
 off_t max_size ;
 char * tmp_fname ;
 ret = cli_matchmeta ( ctx , mschm_f -> filename , 0 , mschm_f -> length , 0 , files , 0 , NULL ) ;
 if ( ret ) {
 if ( ret == CL_VIRUS ) {
 virus_num ++ ;
 if ( ! SCAN_ALL ) break ;
 }
 goto out_close ;
 }
 if ( ctx -> engine -> maxscansize ) {
 if ( ctx -> scansize >= ctx -> engine -> maxscansize ) {
 ret = CL_CLEAN ;
 break ;
 }
 }
 if ( ctx -> engine -> maxscansize && ctx -> scansize + ctx -> engine -> maxfilesize >= ctx -> engine -> maxscansize ) max_size = ctx -> engine -> maxscansize - ctx -> scansize ;
 else max_size = ctx -> engine -> maxfilesize ? ctx -> engine -> maxfilesize : 0xffffffff ;
 ops_ex . max_size = max_size ;
 tmp_fname = cli_gentemp ( ctx -> engine -> tmpdir ) ;
 if ( ! tmp_fname ) {
 ret = CL_EMEM ;
 break ;
 }
 ret = mschm_d -> extract ( mschm_d , mschm_f , tmp_fname ) ;
 if ( ret ) cli_dbgmsg ( "%s() failed to extract %d\n" , __func__ , ret ) ;
 ret = cli_scanfile ( tmp_fname , ctx ) ;
 if ( ret == CL_VIRUS ) virus_num ++ ;
 if ( ! ctx -> engine -> keeptmp ) {
 if ( ! access ( tmp_fname , R_OK ) && cli_unlink ( tmp_fname ) ) {
 free ( tmp_fname ) ;
 ret = CL_EUNLINK ;
 break ;
 }
 }
 free ( tmp_fname ) ;
 files ++ ;
 if ( ret == CL_VIRUS && SCAN_ALL ) continue ;
 if ( ret ) break ;
 }
 out_close : mschm_d -> close ( mschm_d , mschm_h ) ;
 out_dest : mspack_destroy_chm_decompressor ( mschm_d ) ;
 if ( virus_num ) return CL_VIRUS ;
 return ret ;
 return 0 ;
 }

