 switch ( s -> dmode ) {
 case 1 : for ( i = 0 ;
 i < length ;
 i ++ ) {
 int32_t a = p1 [ i ] ;
 int32_t b = p2 [ i ] ;
 p2 [ i ] = a + b ;
 }
 break ;
 case 2 : for ( i = 0 ;
 i < length ;
 i ++ ) {
 int32_t a = p1 [ i ] ;
 int32_t b = p2 [ i ] ;
 p1 [ i ] = b - a ;
 }
 break ;
 case 3 : for ( i = 0 ;
 i < length ;
 i ++ ) {
 int32_t a = p1 [ i ] ;
 int32_t b = p2 [ i ] ;
