 i < length ;
 i ++ ) {
 int32_t a = p1 [ i ] ;
 int32_t b = p2 [ i ] ;
 b = dfactor * ( b >> dshift ) + 128 >> 8 << dshift ;
 p1 [ i ] = b - a ;
 }
 break ;
 case 6 : FFSWAP ( int32_t * , p1 , p2 ) ;
 case 7 : {
