 dshift = get_bits_esc4 ( gb ) ;
 filter_order = 8 << get_bits1 ( gb ) ;
 dval1 = get_bits1 ( gb ) ;
 dval2 = get_bits1 ( gb ) ;
 for ( i = 0 ;
 i < filter_order ;
 i ++ ) {
 if ( ! ( i & 3 ) ) code_size = 14 - get_bits ( gb , 3 ) ;
 filter [ i ] = get_sbits ( gb , code_size ) ;
 }
 order_half = filter_order / 2 ;
 length2 = length - ( filter_order - 1 ) ;
 if ( dval1 ) {
 for ( i = 0 ;
 i < order_half ;
 i ++ ) {
 int32_t a = p1 [ i ] ;
 int32_t b = p2 [ i ] ;
 p1 [ i ] = a + b ;
 }
 }
 if ( dval2 ) {
 for ( i = length2 + order_half ;
 i < length ;
 i ++ ) {
 int32_t a = p1 [ i ] ;
 int32_t b = p2 [ i ] ;
 p1 [ i ] = a + b ;
 }
 }
