 memset ( s -> residues , 0 , s -> residues_buf_size ) ;
 for ( i = 0 ;
 i < length ;
 i ++ ) s -> residues [ i ] = p2 [ i ] >> dshift ;
 p1 += order_half ;
 for ( i = 0 ;
