 * pErrorCode = U_BUFFER_OVERFLOW_ERROR ;
 while ( -- srcLength > 0 ) {
 c = * src ++ ;
 if ( ! IS_BIDI_CONTROL_CHAR ( c ) ) {
 -- remaining ;
 }
 }
 return destSize - remaining ;
 }
 * dest ++ = c ;
 }
 }
 while ( -- srcLength > 0 ) ;
