 # if defined __MSDOS__ || defined WINDOWS32 int sep_char = '/' ;
 # define DIRSEP_CHAR sep_char # else # define DIRSEP_CHAR '/' # endif if ( dirlen == 1 && dirname [ 0 ] == '/' ) dirlen = 0 ;
 # if defined __MSDOS__ || defined WINDOWS32 else if ( dirlen > 1 ) {
