 else if ( dirname [ dirlen - 1 ] == ':' ) {
 -- dirlen ;
 sep_char = ':' ;
 }
 }
 # endif for ( i = 0 ;
 i < n ;
 ++ i ) {
 size_t eltlen = strlen ( array [ i ] ) + 1 ;
 char * new = ( char * ) malloc ( dirlen + 1 + eltlen ) ;
 if ( new == NULL ) {
 while ( i > 0 ) free ( array [ -- i ] ) ;
