 ++ j ) temp_in [ j ] = input [ j * stride + i ] * 4 ;
 ht . cols ( temp_in , temp_out ) ;
 for ( j = 0 ;
 j < 8 ;
 ++ j ) outptr [ j * 8 + i ] = temp_out [ j ] ;
 }
 for ( i = 0 ;
 i < 8 ;
 ++ i ) {
 for ( j = 0 ;
 j < 8 ;
 ++ j ) temp_in [ j ] = out [ j + i * 8 ] ;
 ht . rows ( temp_in , temp_out ) ;
 for ( j = 0 ;
 j < 8 ;
 ++ j ) output [ j + i * 8 ] = ( temp_out [ j ] + ( temp_out [ j ] < 0 ) ) >> 1 ;
 }
 }
 }

