 uint16_t r , g , b ;
 if ( avctx -> codec_id == AV_CODEC_ID_R210 ) {
 b = pixel << 6 ;
 g = ( pixel >> 4 ) & 0xffc0 ;
 r = ( pixel >> 14 ) & 0xffc0 ;
 }
 else {
 b = pixel << 4 ;
 g = ( pixel >> 6 ) & 0xffc0 ;
 r = ( pixel >> 16 ) & 0xffc0 ;
 }
 * dst ++ = r | ( r >> 10 ) ;
 * dst ++ = g | ( g >> 10 ) ;
 * dst ++ = b | ( b >> 10 ) ;
