 uint16_t n = htons ( h ) ;
 if ( h == n ) config = 1 ;
 else config = 2 ;
 }
 if ( config == 1 ) return ( val ) ;
 hi = ( uint32_t ) ( val >> 32 ) ;
 lo = ( uint32_t ) ( val & 0x00000000FFFFFFFF ) ;
 hi = htonl ( hi ) ;
 lo = htonl ( lo ) ;
 return ( ( ( ( uint64_t ) lo ) << 32 ) | ( ( uint64_t ) hi ) ) ;
 }

