static void gain_scale ( G723_1_Context * p , int16_t * buf , int energy ) {
 int num , denom , gain , bits1 , bits2 ;
 int i ;
 num = energy ;
 denom = 0 ;
 for ( i = 0 ;
 i < SUBFRAME_LEN ;
 i ++ ) {
 int temp = buf [ i ] >> 2 ;
 temp *= temp ;
 denom = av_sat_dadd32 ( denom , temp ) ;
 }
 if ( num && denom ) {
 bits1 = normalize_bits ( num , 31 ) ;
 bits2 = normalize_bits ( denom , 31 ) ;
 num = num << bits1 >> 1 ;
 denom <<= bits2 ;
 bits2 = 5 + bits1 - bits2 ;
 bits2 = FFMAX ( 0 , bits2 ) ;
 gain = ( num >> 1 ) / ( denom >> 16 ) ;
 gain = square_root ( gain << 16 >> bits2 ) ;
 }
 else {
 gain = 1 << 12 ;
 }
 for ( i = 0 ;
 i < SUBFRAME_LEN ;
 i ++ ) {
 p -> pf_gain = ( 15 * p -> pf_gain + gain + ( 1 << 3 ) ) >> 4 ;
 buf [ i ] = av_clip_int16 ( ( buf [ i ] * ( p -> pf_gain + ( p -> pf_gain >> 4 ) ) + ( 1 << 10 ) ) >> 11 ) ;
 }
 }

