uint32_t pcnet_ioport_readw ( void * opaque , uint32_t addr ) {
 PCNetState * s = opaque ;
 uint32_t val = - 1 ;
 pcnet_poll_timer ( s ) ;
 if ( ! BCR_DWIO ( s ) ) {
 switch ( addr & 0x0f ) {
 case 0x00 : val = pcnet_csr_readw ( s , s -> rap ) ;
 break ;
 case 0x02 : val = s -> rap ;
 break ;
 case 0x04 : pcnet_s_reset ( s ) ;
 val = 0 ;
 break ;
 case 0x06 : val = pcnet_bcr_readw ( s , s -> rap ) ;
 break ;
 }
 }
 pcnet_update_irq ( s ) ;
 # ifdef PCNET_DEBUG_IO printf ( "pcnet_ioport_readw addr=0x%08x val=0x%04x\n" , addr , val & 0xffff ) ;
 # endif return val ;
 }

int ehci_create_ich9_with_companions ( PCIBus * bus , int slot ) {
 const struct ehci_companions * comp ;
 PCIDevice * ehci , * uhci ;
 BusState * usbbus ;
 const char * name ;
 int i ;
 switch ( slot ) {
 case 0x1d : name = "ich9-usb-ehci1" ;
 comp = ich9_1d ;
 break ;
 case 0x1a : name = "ich9-usb-ehci2" ;
 comp = ich9_1a ;
 break ;
 default : return - 1 ;
 }
 ehci = pci_create_multifunction ( bus , PCI_DEVFN ( slot , 7 ) , true , name ) ;
 qdev_init_nofail ( & ehci -> qdev ) ;
 usbbus = QLIST_FIRST ( & ehci -> qdev . child_bus ) ;
 for ( i = 0 ;
 i < 3 ;
 i ++ ) {
 uhci = pci_create_multifunction ( bus , PCI_DEVFN ( slot , comp [ i ] . func ) , true , comp [ i ] . name ) ;
 qdev_prop_set_string ( & uhci -> qdev , "masterbus" , usbbus -> name ) ;
 qdev_prop_set_uint32 ( & uhci -> qdev , "firstport" , comp [ i ] . port ) ;
 qdev_init_nofail ( & uhci -> qdev ) ;
 }
 return 0 ;
 }

static void cancel_loading_attributes ( NautilusDirectory * directory , NautilusFileAttributes file_attributes ) {
 Request request ;
