static int parse_CPropertyRestriction ( tvbuff_t * tvb , packet_info * pinfo , int offset , proto_tree * parent_tree , proto_tree * pad_tree , struct CPropertyRestriction * v , const char * fmt , ... ) {
 proto_tree * tree ;
 proto_item * item ;
