 if ( arg && ( arg -> newsockfd >= 0 ) ) fd_set_nonblocking ( arg -> newsockfd ) ;
 # ifndef NDEBUG if ( ( msg -> flags & SLURM_DROP_PRIV ) ) drop_priv = true ;
 # endif rpc_uid = ( uint32_t ) g_slurm_auth_get_uid ( msg -> auth_cred , slurmctld_config . auth_info ) ;
