 case REQUEST_RESOURCE_ALLOCATION : _slurm_rpc_allocate_resources ( msg ) ;
 break ;
 case REQUEST_JOB_PACK_ALLOCATION : _slurm_rpc_allocate_pack ( msg ) ;
