static int call_ber_syntax_callback ( const char * syntax , tvbuff_t * tvb , int offset , packet_info * pinfo , proto_tree * tree ) {
 tvbuff_t * next_tvb ;
 int len = 0 ;
 next_tvb = tvb_new_subset_remaining ( tvb , offset ) ;
 if ( syntax == NULL || ( len = dissector_try_string ( ber_syntax_dissector_table , syntax , next_tvb , pinfo , tree , NULL ) ) == 0 ) {
 proto_item * item = NULL ;
 if ( syntax == NULL ) {
 item = proto_tree_add_expert_format ( tree , pinfo , & ei_ber_no_oid , next_tvb , 0 , tvb_reported_length_remaining ( tvb , offset ) , "BER: No syntax supplied to call_ber_syntax_callback" ) ;
 }
 else {
 item = proto_tree_add_expert_format ( tree , pinfo , & ei_ber_syntax_not_implemented , next_tvb , 0 , tvb_reported_length_remaining ( tvb , offset ) , "BER: Dissector for syntax:%s not implemented." " Contact Wireshark developers if you want this supported" , syntax ) ;
 }
 if ( decode_unexpected ) {
 proto_tree * unknown_tree = proto_item_add_subtree ( item , ett_ber_unknown ) ;
 dissect_unknown_ber ( pinfo , next_tvb , 0 , unknown_tree ) ;
 }
 len = tvb_reported_length_remaining ( tvb , offset ) ;
 }
 offset += len ;
 return offset ;
 }

int MBS_ReadHeader ( int fd , MBSPatchHeader * header ) {
 int s = read ( fd , header , sizeof ( MBSPatchHeader ) ) ;
 if ( s != sizeof ( MBSPatchHeader ) ) return READ_ERROR ;
 header -> slen = ntohl ( header -> slen ) ;
 header -> scrc32 = ntohl ( header -> scrc32 ) ;
 header -> dlen = ntohl ( header -> dlen ) ;
 header -> cblen = ntohl ( header -> cblen ) ;
 header -> difflen = ntohl ( header -> difflen ) ;
 header -> extralen = ntohl ( header -> extralen ) ;
 struct stat hs ;
 s = fstat ( fd , & hs ) ;
 if ( s != 0 ) return READ_ERROR ;
 if ( memcmp ( header -> tag , "MBDIFF10" , 8 ) != 0 ) return UNEXPECTED_ERROR ;
 if ( hs . st_size > INT_MAX ) return UNEXPECTED_ERROR ;
 size_t size = static_cast < size_t > ( hs . st_size ) ;
 if ( size < sizeof ( MBSPatchHeader ) ) return UNEXPECTED_ERROR ;
 size -= sizeof ( MBSPatchHeader ) ;
 if ( size < header -> cblen ) return UNEXPECTED_ERROR ;
 size -= header -> cblen ;
 if ( size < header -> difflen ) return UNEXPECTED_ERROR ;
 size -= header -> difflen ;
 if ( size < header -> extralen ) return UNEXPECTED_ERROR ;
 size -= header -> extralen ;
 if ( size != 0 ) return UNEXPECTED_ERROR ;
 return OK ;
 }

