 assert ( n -> vdev . vm_running ) ;
 n -> tx_waiting = 0 ;
 if ( unlikely ( ! ( n -> vdev . status & VIRTIO_CONFIG_S_DRIVER_OK ) ) ) return ;
 ret = virtio_net_flush_tx ( n , n -> tx_vq ) ;
 if ( ret == - EBUSY ) {
