int EVP_CIPHER_CTX_ctrl ( EVP_CIPHER_CTX * ctx , int type , int arg , void * ptr ) {
 int ret ;
 if ( ! ctx -> cipher ) {
 EVPerr ( EVP_F_EVP_CIPHER_CTX_CTRL , EVP_R_NO_CIPHER_SET ) ;
 return 0 ;
 }
 if ( ! ctx -> cipher -> ctrl ) {
 EVPerr ( EVP_F_EVP_CIPHER_CTX_CTRL , EVP_R_CTRL_NOT_IMPLEMENTED ) ;
