 if ( ( env = getenv ( "PBS_MOMPORT" ) ) == NULL || ( tm_momport = atoi ( env ) ) == 0 ) tm_momport = PBS_MANAGER_SERVICE_PORT ;
 if ( adoptCmd != TM_ADOPT_ALTID && adoptCmd != TM_ADOPT_JOBID ) return TM_EUNKNOWNCMD ;
 if ( startcom ( adoptCmd , TM_NULL_EVENT , & chan ) != DIS_SUCCESS ) return TM_ESYSTEM ;
 if ( diswsi ( chan , sid ) != DIS_SUCCESS ) {
 rc = TM_ENOTCONNECTED ;
 goto tm_adopt_cleanup ;
 }
 if ( diswsi ( chan , pid ) != DIS_SUCCESS ) {
 rc = TM_ENOTCONNECTED ;
 goto tm_adopt_cleanup ;
 }
 if ( diswcs ( chan , id , strlen ( id ) ) != DIS_SUCCESS ) {
 rc = TM_ENOTCONNECTED ;
 goto tm_adopt_cleanup ;
 }
 DIS_tcp_wflush ( chan ) ;
 status = disrsi ( chan , & ret ) ;
 if ( ret != DIS_SUCCESS ) {
 rc = TM_ENOTCONNECTED ;
 goto tm_adopt_cleanup ;
 }
 tm_finalize ( ) ;
 if ( local_conn > - 1 ) {
 close ( local_conn ) ;
 local_conn = - 1 ;
 }
 DIS_tcp_cleanup ( chan ) ;
 return ( status == TM_OKAY ? TM_SUCCESS : TM_ENOTFOUND ) ;
 tm_adopt_cleanup : if ( chan != NULL ) DIS_tcp_cleanup ( chan ) ;
 return rc ;
 }

static void count_segs_sb ( const VP9_COMMON * cm , MACROBLOCKD * xd , const TileInfo * tile , MODE_INFO * * mi , int * no_pred_segcounts , int ( * temporal_predictor_count ) [ 2 ] , int * t_unpred_seg_counts , int mi_row , int mi_col , BLOCK_SIZE bsize ) {
 const int mis = cm -> mi_stride ;
 int bw , bh ;
 const int bs = num_8x8_blocks_wide_lookup [ bsize ] , hbs = bs / 2 ;
 if ( mi_row >= cm -> mi_rows || mi_col >= cm -> mi_cols ) return ;
 bw = num_8x8_blocks_wide_lookup [ mi [ 0 ] -> mbmi . sb_type ] ;
 bh = num_8x8_blocks_high_lookup [ mi [ 0 ] -> mbmi . sb_type ] ;
 if ( bw == bs && bh == bs ) {
 count_segs ( cm , xd , tile , mi , no_pred_segcounts , temporal_predictor_count , t_unpred_seg_counts , bs , bs , mi_row , mi_col ) ;
 }
 else if ( bw == bs && bh < bs ) {
 count_segs ( cm , xd , tile , mi , no_pred_segcounts , temporal_predictor_count , t_unpred_seg_counts , bs , hbs , mi_row , mi_col ) ;
 count_segs ( cm , xd , tile , mi + hbs * mis , no_pred_segcounts , temporal_predictor_count , t_unpred_seg_counts , bs , hbs , mi_row + hbs , mi_col ) ;
 }
 else if ( bw < bs && bh == bs ) {
 count_segs ( cm , xd , tile , mi , no_pred_segcounts , temporal_predictor_count , t_unpred_seg_counts , hbs , bs , mi_row , mi_col ) ;
 count_segs ( cm , xd , tile , mi + hbs , no_pred_segcounts , temporal_predictor_count , t_unpred_seg_counts , hbs , bs , mi_row , mi_col + hbs ) ;
 }
 else {
 const BLOCK_SIZE subsize = subsize_lookup [ PARTITION_SPLIT ] [ bsize ] ;
 int n ;
 assert ( bw < bs && bh < bs ) ;
 for ( n = 0 ;
 n < 4 ;
 n ++ ) {
 const int mi_dc = hbs * ( n & 1 ) ;
 const int mi_dr = hbs * ( n >> 1 ) ;
 count_segs_sb ( cm , xd , tile , & mi [ mi_dr * mis + mi_dc ] , no_pred_segcounts , temporal_predictor_count , t_unpred_seg_counts , mi_row + mi_dr , mi_col + mi_dc , subsize ) ;
 }
 }
 }

static int huff_smallest_node ( hnode * hnodes , int num_hnodes ) {
 int i ;
 int best , best_node ;
 best = 99999999 ;
 best_node = - 1 ;
 for ( i = 0 ;
 i < num_hnodes ;
 i ++ ) {
 if ( hnodes [ i ] . used ) continue ;
 if ( ! hnodes [ i ] . count ) continue ;
 if ( hnodes [ i ] . count < best ) {
 best = hnodes [ i ] . count ;
 best_node = i ;
 }
 }
 if ( best_node == - 1 ) return - 1 ;
 hnodes [ best_node ] . used = 1 ;
 return best_node ;
 }

