 if ( p_sys -> i_pts > VLC_TS_INVALID && p_sys -> i_pts != date_Get ( & p_sys -> end_date ) ) date_Set ( & p_sys -> end_date , p_sys -> i_pts ) ;
 p_sys -> i_state = STATE_HEADER ;
 break ;
 case STATE_HEADER : if ( p_sys -> i_type == TYPE_ADTS ) {
