 }
 else {
 assert ( p_sys -> i_type == TYPE_LOAS ) ;
 if ( block_PeekBytes ( & p_sys -> bytestream , p_header , LOAS_HEADER_SIZE ) != VLC_SUCCESS ) return NULL ;
 p_sys -> i_frame_size = LOASSyncInfo ( p_header , & p_sys -> i_header_size ) ;
 }
