 msg_Dbg ( p_dec , "emulated sync word" ) ;
 block_SkipByte ( & p_sys -> bytestream ) ;
 p_sys -> i_state = STATE_NOSYNC ;
 break ;
 }
 p_sys -> i_state = STATE_NEXT_SYNC ;
 case STATE_NEXT_SYNC : if ( p_sys -> bytestream . p_block == NULL ) {
