 case OBJ_COMMIT : if ( size < 40 + strlen ( "tree " ) || get_sha1_hex ( buf + strlen ( "tree " ) , sha1 ) ) die ( "Invalid SHA1 in commit: %s" , command_buf . buf ) ;
 }
 free ( buf ) ;
 return find_object ( sha1 ) ;
 }

