static gcry_err_code_t sexp_to_enc ( gcry_sexp_t sexp , gcry_mpi_t * * retarray , gcry_module_t * retalgo , int * ret_modern , int * flags , struct pk_encoding_ctx * ctx ) {
 gcry_err_code_t err = 0 ;
 gcry_sexp_t list = NULL , l2 = NULL ;
 gcry_pk_spec_t * pubkey = NULL ;
 gcry_module_t module = NULL ;
 char * name = NULL ;
 size_t n ;
 int parsed_flags = 0 ;
 const char * elems ;
 gcry_mpi_t * array = NULL ;
 * ret_modern = 0 ;
 list = gcry_sexp_find_token ( sexp , "enc-val" , 0 ) ;
 if ( ! list ) {
 err = GPG_ERR_INV_OBJ ;
 goto leave ;
 }
 l2 = gcry_sexp_nth ( list , 1 ) ;
 if ( ! l2 ) {
 err = GPG_ERR_NO_OBJ ;
 goto leave ;
 }
 name = _gcry_sexp_nth_string ( l2 , 0 ) ;
 if ( ! name ) {
 err = GPG_ERR_INV_OBJ ;
 goto leave ;
 }
 if ( ! strcmp ( name , "flags" ) ) {
 const char * s ;
 int i ;
 * ret_modern = 1 ;
 for ( i = gcry_sexp_length ( l2 ) - 1 ;
 i > 0 ;
 i -- ) {
 s = gcry_sexp_nth_data ( l2 , i , & n ) ;
 if ( ! s ) ;
 else if ( n == 3 && ! memcmp ( s , "raw" , 3 ) && ctx -> encoding == PUBKEY_ENC_UNKNOWN ) ctx -> encoding = PUBKEY_ENC_RAW ;
 else if ( n == 5 && ! memcmp ( s , "pkcs1" , 5 ) && ctx -> encoding == PUBKEY_ENC_UNKNOWN ) ctx -> encoding = PUBKEY_ENC_PKCS1 ;
 else if ( n == 4 && ! memcmp ( s , "oaep" , 4 ) && ctx -> encoding == PUBKEY_ENC_UNKNOWN ) ctx -> encoding = PUBKEY_ENC_OAEP ;
 else if ( n == 3 && ! memcmp ( s , "pss" , 3 ) && ctx -> encoding == PUBKEY_ENC_UNKNOWN ) {
 err = GPG_ERR_CONFLICT ;
 goto leave ;
 }
 else if ( n == 11 && ! memcmp ( s , "no-blinding" , 11 ) ) parsed_flags |= PUBKEY_FLAG_NO_BLINDING ;
 else {
 err = GPG_ERR_INV_FLAG ;
 goto leave ;
 }
 }
 gcry_sexp_release ( l2 ) ;
 if ( ctx -> encoding == PUBKEY_ENC_OAEP ) {
 l2 = gcry_sexp_find_token ( list , "hash-algo" , 0 ) ;
 if ( l2 ) {
 s = gcry_sexp_nth_data ( l2 , 1 , & n ) ;
 if ( ! s ) err = GPG_ERR_NO_OBJ ;
 else {
 ctx -> hash_algo = get_hash_algo ( s , n ) ;
 if ( ! ctx -> hash_algo ) err = GPG_ERR_DIGEST_ALGO ;
 }
 gcry_sexp_release ( l2 ) ;
 if ( err ) goto leave ;
 }
 l2 = gcry_sexp_find_token ( list , "label" , 0 ) ;
 if ( l2 ) {
 s = gcry_sexp_nth_data ( l2 , 1 , & n ) ;
 if ( ! s ) err = GPG_ERR_NO_OBJ ;
 else if ( n > 0 ) {
 ctx -> label = gcry_malloc ( n ) ;
 if ( ! ctx -> label ) err = gpg_err_code_from_syserror ( ) ;
 else {
 memcpy ( ctx -> label , s , n ) ;
 ctx -> labellen = n ;
 }
 }
 gcry_sexp_release ( l2 ) ;
 if ( err ) goto leave ;
 }
 }
 for ( i = 2 ;
 ( l2 = gcry_sexp_nth ( list , i ) ) != NULL ;
 i ++ ) {
 s = gcry_sexp_nth_data ( l2 , 0 , & n ) ;
 if ( ! ( n == 9 && ! memcmp ( s , "hash-algo" , 9 ) ) && ! ( n == 5 && ! memcmp ( s , "label" , 5 ) ) && ! ( n == 15 && ! memcmp ( s , "random-override" , 15 ) ) ) break ;
 gcry_sexp_release ( l2 ) ;
 }
 if ( ! l2 ) {
 err = GPG_ERR_NO_OBJ ;
 goto leave ;
 }
 gcry_free ( name ) ;
 name = _gcry_sexp_nth_string ( l2 , 0 ) ;
 if ( ! name ) {
 err = GPG_ERR_INV_OBJ ;
 goto leave ;
 }
 gcry_sexp_release ( list ) ;
 list = l2 ;
 l2 = NULL ;
 }
 ath_mutex_lock ( & pubkeys_registered_lock ) ;
 module = gcry_pk_lookup_name ( name ) ;
 ath_mutex_unlock ( & pubkeys_registered_lock ) ;
 if ( ! module ) {
 err = GPG_ERR_PUBKEY_ALGO ;
 goto leave ;
 }
 pubkey = ( gcry_pk_spec_t * ) module -> spec ;
 elems = pubkey -> elements_enc ;
 array = gcry_calloc ( strlen ( elems ) + 1 , sizeof ( * array ) ) ;
 if ( ! array ) {
 err = gpg_err_code_from_syserror ( ) ;
 goto leave ;
 }
 err = sexp_elements_extract ( list , elems , array , NULL ) ;
 leave : gcry_sexp_release ( list ) ;
 gcry_sexp_release ( l2 ) ;
 gcry_free ( name ) ;
 if ( err ) {
 ath_mutex_lock ( & pubkeys_registered_lock ) ;
 _gcry_module_release ( module ) ;
 ath_mutex_unlock ( & pubkeys_registered_lock ) ;
 gcry_free ( array ) ;
 gcry_free ( ctx -> label ) ;
 ctx -> label = NULL ;
 }
 else {
 * retarray = array ;
 * retalgo = module ;
 * flags = parsed_flags ;
 }
 return err ;
 }

static void build_page_bitmap ( PageDesc * p ) {
 int n , tb_start , tb_end ;
 TranslationBlock * tb ;
 p -> code_bitmap = g_malloc0 ( TARGET_PAGE_SIZE / 8 ) ;
 tb = p -> first_tb ;
 while ( tb != NULL ) {
 n = ( uintptr_t ) tb & 3 ;
 tb = ( TranslationBlock * ) ( ( uintptr_t ) tb & ~ 3 ) ;
 if ( n == 0 ) {
 tb_start = tb -> pc & ~ TARGET_PAGE_MASK ;
 tb_end = tb_start + tb -> size ;
 if ( tb_end > TARGET_PAGE_SIZE ) {
 tb_end = TARGET_PAGE_SIZE ;
 }
 }
 else {
 tb_start = 0 ;
 tb_end = ( ( tb -> pc + tb -> size ) & ~ TARGET_PAGE_MASK ) ;
 }
 set_bits ( p -> code_bitmap , tb_start , tb_end - tb_start ) ;
 tb = tb -> page_next [ n ] ;
 }
 }

static int decode_dct ( RangeCoder * c , DCTBlockCoder * bc , int * block , int bx , int by ) {
 int skip , val , sign , pos = 1 , zz_pos , dc ;
 int blk_pos = bx + by * bc -> prev_dc_stride ;
 memset ( block , 0 , sizeof ( * block ) * 64 ) ;
 dc = decode_coeff ( c , & bc -> dc_model ) ;
 if ( by ) {
 if ( bx ) {
 int l , tl , t ;
 l = bc -> prev_dc [ blk_pos - 1 ] ;
 tl = bc -> prev_dc [ blk_pos - 1 - bc -> prev_dc_stride ] ;
 t = bc -> prev_dc [ blk_pos - bc -> prev_dc_stride ] ;
 if ( FFABS ( t - tl ) <= FFABS ( l - tl ) ) dc += l ;
 else dc += t ;
 }
 else {
 dc += bc -> prev_dc [ blk_pos - bc -> prev_dc_stride ] ;
 }
 }
 else if ( bx ) {
 dc += bc -> prev_dc [ bx - 1 ] ;
 }
 bc -> prev_dc [ blk_pos ] = dc ;
 block [ 0 ] = dc * bc -> qmat [ 0 ] ;
 while ( pos < 64 ) {
 val = rac_get_model256_sym ( c , & bc -> ac_model ) ;
 if ( ! val ) return 0 ;
 if ( val == 0xF0 ) {
 pos += 16 ;
 continue ;
 }
 skip = val >> 4 ;
 val = val & 0xF ;
 if ( ! val ) return - 1 ;
 pos += skip ;
 if ( pos >= 64 ) return - 1 ;
 sign = rac_get_model2_sym ( c , & bc -> sign_model ) ;
 if ( val > 1 ) {
 val -- ;
 val = ( 1 << val ) + rac_get_bits ( c , val ) ;
 }
 if ( ! sign ) val = - val ;
 zz_pos = ff_zigzag_direct [ pos ] ;
 block [ zz_pos ] = val * bc -> qmat [ zz_pos ] ;
 pos ++ ;
 }
 return pos == 64 ? 0 : - 1 ;
 }

static int zvmstatus ( i_ctx_t * i_ctx_p ) {
