 # ifdef DEBUG_CONF ap_log_perror ( APLOG_MARK , APLOG_STARTUP | APLOG_NOERRNO , 0 , cmd -> pool , "Rule: type=%d p1='%s' p2='%s' p3='%s'" , RULE_TYPE_MARKER , p1 , p2 , p3 ) ;
