 p ++ ;
 if ( type == ST_DATA ) {
 memcpy ( & n , p , sizeof n ) ;
 p += sizeof n + n ;
 }
 else if ( type == ST_OPEN ) {
 if ( ! level ) * r_off = ( p - 1 ) - list -> d ;
