 netid_len = octet & 0x7F ;
 proto_tree_add_item ( tree , hf_q931_netid_length , tvb , offset , 1 , ENC_BIG_ENDIAN ) ;
 offset += 1 ;
 len -= 1 ;
 if ( netid_len != 0 ) {
