 if ( netid_len > len ) netid_len = len ;
 if ( netid_len != 0 ) {
 proto_tree_add_item ( tree , hf_q931_netid , tvb , offset , netid_len , ENC_NA | ENC_ASCII ) ;
 offset += netid_len ;
 len -= netid_len ;
