 if ( a -> type > b -> type ) return - 1 ;
 if ( a -> type < b -> type ) return 1 ;
 if ( a -> hash > b -> hash ) return - 1 ;
 if ( a -> hash < b -> hash ) return 1 ;
 if ( a -> preferred_base > b -> preferred_base ) return - 1 ;
