static uint64_t nvic_sysreg_read ( void * opaque , hwaddr addr , unsigned size ) {
 nvic_state * s = ( nvic_state * ) opaque ;
 uint32_t offset = addr ;
 int i ;
 uint32_t val ;
 switch ( offset ) {
 case 0xd18 ... 0xd23 : val = 0 ;
 for ( i = 0 ;
 i < size ;
 i ++ ) {
 val |= s -> gic . priority1 [ ( offset - 0xd14 ) + i ] [ 0 ] << ( i * 8 ) ;
 }
