static int v410_decode_frame ( AVCodecContext * avctx , void * data , int * got_frame , AVPacket * avpkt ) {
 AVFrame * pic = data ;
 uint8_t * src = avpkt -> data ;
 uint16_t * y , * u , * v ;
 uint32_t val ;
 int i , j ;
 if ( avpkt -> size < 4 * avctx -> height * avctx -> width ) {
 av_log ( avctx , AV_LOG_ERROR , "Insufficient input data.\n" ) ;
 return AVERROR ( EINVAL ) ;
 }
 if ( ff_get_buffer ( avctx , pic , 0 ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "Could not allocate buffer.\n" ) ;
 return AVERROR ( ENOMEM ) ;
 }
 pic -> key_frame = 1 ;
 pic -> pict_type = AV_PICTURE_TYPE_I ;
 y = ( uint16_t * ) pic -> data [ 0 ] ;
 u = ( uint16_t * ) pic -> data [ 1 ] ;
 v = ( uint16_t * ) pic -> data [ 2 ] ;
 for ( i = 0 ;
 i < avctx -> height ;
 i ++ ) {
 for ( j = 0 ;
 j < avctx -> width ;
 j ++ ) {
 val = AV_RL32 ( src ) ;
 u [ j ] = ( val >> 2 ) & 0x3FF ;
 y [ j ] = ( val >> 12 ) & 0x3FF ;
 v [ j ] = ( val >> 22 ) ;
 src += 4 ;
 }
 y += pic -> linesize [ 0 ] >> 1 ;
 u += pic -> linesize [ 1 ] >> 1 ;
 v += pic -> linesize [ 2 ] >> 1 ;
 }
 * got_frame = 1 ;
 return avpkt -> size ;
 }

static void sbr_dequant ( SpectralBandReplication * sbr , int id_aac ) {
 int k , e ;
 int ch ;
 if ( id_aac == TYPE_CPE && sbr -> bs_coupling ) {
 float alpha = sbr -> data [ 0 ] . bs_amp_res ? 1.0f : 0.5f ;
 float pan_offset = sbr -> data [ 0 ] . bs_amp_res ? 12.0f : 24.0f ;
 for ( e = 1 ;
 e <= sbr -> data [ 0 ] . bs_num_env ;
 e ++ ) {
 for ( k = 0 ;
 k < sbr -> n [ sbr -> data [ 0 ] . bs_freq_res [ e ] ] ;
 k ++ ) {
 float temp1 = exp2f ( sbr -> data [ 0 ] . env_facs [ e ] [ k ] * alpha + 7.0f ) ;
 float temp2 = exp2f ( ( pan_offset - sbr -> data [ 1 ] . env_facs [ e ] [ k ] ) * alpha ) ;
 float fac ;
 if ( temp1 > 1E20 ) {
 av_log ( NULL , AV_LOG_ERROR , "envelope scalefactor overflow in dequant\n" ) ;
 temp1 = 1 ;
 }
 fac = temp1 / ( 1.0f + temp2 ) ;
 sbr -> data [ 0 ] . env_facs [ e ] [ k ] = fac ;
 sbr -> data [ 1 ] . env_facs [ e ] [ k ] = fac * temp2 ;
 }
 }
 for ( e = 1 ;
 e <= sbr -> data [ 0 ] . bs_num_noise ;
 e ++ ) {
 for ( k = 0 ;
 k < sbr -> n_q ;
 k ++ ) {
 float temp1 = exp2f ( NOISE_FLOOR_OFFSET - sbr -> data [ 0 ] . noise_facs [ e ] [ k ] + 1 ) ;
 float temp2 = exp2f ( 12 - sbr -> data [ 1 ] . noise_facs [ e ] [ k ] ) ;
 float fac ;
 if ( temp1 > 1E20 ) {
 av_log ( NULL , AV_LOG_ERROR , "envelope scalefactor overflow in dequant\n" ) ;
 temp1 = 1 ;
 }
 fac = temp1 / ( 1.0f + temp2 ) ;
 sbr -> data [ 0 ] . noise_facs [ e ] [ k ] = fac ;
 sbr -> data [ 1 ] . noise_facs [ e ] [ k ] = fac * temp2 ;
 }
 }
 }
 else {
 for ( ch = 0 ;
 ch < ( id_aac == TYPE_CPE ) + 1 ;
 ch ++ ) {
 float alpha = sbr -> data [ ch ] . bs_amp_res ? 1.0f : 0.5f ;
 for ( e = 1 ;
 e <= sbr -> data [ ch ] . bs_num_env ;
 e ++ ) for ( k = 0 ;
 k < sbr -> n [ sbr -> data [ ch ] . bs_freq_res [ e ] ] ;
 k ++ ) {
 sbr -> data [ ch ] . env_facs [ e ] [ k ] = exp2f ( alpha * sbr -> data [ ch ] . env_facs [ e ] [ k ] + 6.0f ) ;
 if ( sbr -> data [ ch ] . env_facs [ e ] [ k ] > 1E20 ) {
 av_log ( NULL , AV_LOG_ERROR , "envelope scalefactor overflow in dequant\n" ) ;
 sbr -> data [ ch ] . env_facs [ e ] [ k ] = 1 ;
 }
 }
 for ( e = 1 ;
 e <= sbr -> data [ ch ] . bs_num_noise ;
 e ++ ) for ( k = 0 ;
 k < sbr -> n_q ;
 k ++ ) sbr -> data [ ch ] . noise_facs [ e ] [ k ] = exp2f ( NOISE_FLOOR_OFFSET - sbr -> data [ ch ] . noise_facs [ e ] [ k ] ) ;
 }
 }
 }

