 for ( i = 0 ;
 i < table_entries_used ;
 i ++ ) {
 nsv -> nsvs_timestamps [ i ] = avio_rl32 ( pb ) ;
 }
 }
 }
 av_log ( s , AV_LOG_TRACE , "NSV got index;
 filepos %" PRId64 "\n" , avio_tell ( pb ) ) ;
 avio_seek ( pb , nsv -> base_offset + size , SEEK_SET ) ;
