static int __udp6_lib_mcast_deliver ( struct net * net , struct sk_buff * skb , struct in6_addr * saddr , struct in6_addr * daddr , struct udp_table * udptable ) {
 struct sock * sk , * stack [ 256 / sizeof ( struct sock * ) ] ;
