 }
 }
 for ( i = 0 ;
 i < count ;
 i ++ ) sock_hold ( stack [ i ] ) ;
 spin_unlock ( & hslot -> lock ) ;
 if ( count ) {
 flush_stack ( stack , count , skb , count - 1 ) ;
 for ( i = 0 ;
 i < count ;
 i ++ ) sock_put ( stack [ i ] ) ;
 }
