int ssl3_setup_write_buffer ( SSL * s ) {
 unsigned char * p ;
 size_t len , align = 0 , headerlen ;
 if ( SSL_version ( s ) == DTLS1_VERSION || SSL_version ( s ) == DTLS1_BAD_VER ) headerlen = DTLS1_RT_HEADER_LENGTH + 1 ;
 else headerlen = SSL3_RT_HEADER_LENGTH ;
 # if defined ( SSL3_ALIGN_PAYLOAD ) && SSL3_ALIGN_PAYLOAD != 0 align = ( - SSL3_RT_HEADER_LENGTH ) & ( SSL3_ALIGN_PAYLOAD - 1 ) ;
 # endif if ( s -> s3 -> wbuf . buf == NULL ) {
 len = s -> max_send_fragment + SSL3_RT_SEND_MAX_ENCRYPTED_OVERHEAD + headerlen + align ;
 # ifndef OPENSSL_NO_COMP if ( ! ( s -> options & SSL_OP_NO_COMPRESSION ) ) len += SSL3_RT_MAX_COMPRESSED_OVERHEAD ;
 # endif if ( ! ( s -> options & SSL_OP_DONT_INSERT_EMPTY_FRAGMENTS ) ) len += headerlen + align + SSL3_RT_SEND_MAX_ENCRYPTED_OVERHEAD ;
