 }

static int mp_decode_layer1 ( MPADecodeContext * s ) {
 int bound , i , v , n , ch , j , mant ;
 uint8_t allocation [ MPA_MAX_CHANNELS ] [ SBLIMIT ] ;
 uint8_t scale_factors [ MPA_MAX_CHANNELS ] [ SBLIMIT ] ;
 if ( s -> mode == MPA_JSTEREO ) bound = ( s -> mode_ext + 1 ) * 4 ;
 else bound = SBLIMIT ;
 for ( i = 0 ;
 i < bound ;
 i ++ ) {
 for ( ch = 0 ;
 ch < s -> nb_channels ;
 ch ++ ) {
 allocation [ ch ] [ i ] = get_bits ( & s -> gb , 4 ) ;
 }
 }
 for ( i = bound ;
 i < SBLIMIT ;
 i ++ ) allocation [ 0 ] [ i ] = get_bits ( & s -> gb , 4 ) ;
 for ( i = 0 ;
 i < bound ;
 i ++ ) {
 for ( ch = 0 ;
 ch < s -> nb_channels ;
 ch ++ ) {
 if ( allocation [ ch ] [ i ] ) scale_factors [ ch ] [ i ] = get_bits ( & s -> gb , 6 ) ;
 }
 }
 for ( i = bound ;
 i < SBLIMIT ;
 i ++ ) {
 if ( allocation [ 0 ] [ i ] ) {
 scale_factors [ 0 ] [ i ] = get_bits ( & s -> gb , 6 ) ;
 scale_factors [ 1 ] [ i ] = get_bits ( & s -> gb , 6 ) ;
 }
 }
 for ( j = 0 ;
 j < 12 ;
 j ++ ) {
 for ( i = 0 ;
 i < bound ;
 i ++ ) {
 for ( ch = 0 ;
 ch < s -> nb_channels ;
 ch ++ ) {
 n = allocation [ ch ] [ i ] ;
 if ( n ) {
 mant = get_bits ( & s -> gb , n + 1 ) ;
 v = l1_unscale ( n , mant , scale_factors [ ch ] [ i ] ) ;
 }
 else {
 v = 0 ;
 }
 s -> sb_samples [ ch ] [ j ] [ i ] = v ;
 }
 }
 for ( i = bound ;
 i < SBLIMIT ;
 i ++ ) {
 n = allocation [ 0 ] [ i ] ;
 if ( n ) {
 mant = get_bits ( & s -> gb , n + 1 ) ;
 v = l1_unscale ( n , mant , scale_factors [ 0 ] [ i ] ) ;
 s -> sb_samples [ 0 ] [ j ] [ i ] = v ;
 v = l1_unscale ( n , mant , scale_factors [ 1 ] [ i ] ) ;
 s -> sb_samples [ 1 ] [ j ] [ i ] = v ;
 }
 else {
 s -> sb_samples [ 0 ] [ j ] [ i ] = 0 ;
 s -> sb_samples [ 1 ] [ j ] [ i ] = 0 ;
 }
 }
 }
 return 12 ;
 }

static int rv34_decode_block ( int16_t * dst , GetBitContext * gb , RV34VLC * rvlc , int fc , int sc , int q_dc , int q_ac1 , int q_ac2 ) {
 int code , pattern , has_ac = 1 ;
 code = get_vlc2 ( gb , rvlc -> first_pattern [ fc ] . table , 9 , 2 ) ;
 pattern = code & 0x7 ;
 code >>= 3 ;
 if ( modulo_three_table [ code ] & 0x3F ) {
 decode_subblock3 ( dst , code , gb , & rvlc -> coefficient , q_dc , q_ac1 , q_ac2 ) ;
 }
 else {
 decode_subblock1 ( dst , code , gb , & rvlc -> coefficient , q_dc ) ;
 if ( ! pattern ) return 0 ;
 has_ac = 0 ;
 }
 if ( pattern & 4 ) {
 code = get_vlc2 ( gb , rvlc -> second_pattern [ sc ] . table , 9 , 2 ) ;
 decode_subblock ( dst + 4 * 0 + 2 , code , 0 , gb , & rvlc -> coefficient , q_ac2 ) ;
 }
 if ( pattern & 2 ) {
 code = get_vlc2 ( gb , rvlc -> second_pattern [ sc ] . table , 9 , 2 ) ;
 decode_subblock ( dst + 4 * 2 + 0 , code , 1 , gb , & rvlc -> coefficient , q_ac2 ) ;
 }
 if ( pattern & 1 ) {
 code = get_vlc2 ( gb , rvlc -> third_pattern [ sc ] . table , 9 , 2 ) ;
 decode_subblock ( dst + 4 * 2 + 2 , code , 0 , gb , & rvlc -> coefficient , q_ac2 ) ;
 }
 return has_ac | pattern ;
 }

