 }
 if ( quote < 0 ) {
 if ( buffer [ uprv_strlen ( buffer ) - 1 ] == '"' ) {
 buffer [ uprv_strlen ( buffer ) - 1 ] = '\0' ;
 }
 if ( buffer [ 0 ] == '"' ) {
 uprv_strcpy ( buffer , buffer + 1 ) ;
 }
 }
 else if ( quote > 0 ) {
