 uprv_strcpy ( buffer , "\"" ) ;
 uprv_strcat ( buffer , l -> str ) ;
 }
 if ( l -> str [ uprv_strlen ( l -> str ) - 1 ] != '"' ) {
 uprv_strcat ( buffer , "\"" ) ;
 }
 }
 T_FileStream_write ( s , buffer , ( int32_t ) uprv_strlen ( buffer ) ) ;
 }
 if ( l -> next && delim ) {
