 }
 else if ( isdigit ( ( int ) string [ 0 ] ) ) {
 fop -> op . test . value = strtoul ( string , NULL , 10 ) ;
 return E_SUCCESS ;
 }
 else if ( string [ 0 ] == '\'' && string [ strlen ( string ) - 1 ] == '\'' ) {
 struct ip_addr ipaddr ;
 p = strchr ( string + 1 , '\'' ) ;
 * p = '\0' ;
 if ( ip_addr_pton ( string + 1 , & ipaddr ) == E_SUCCESS ) {
