 }
 }
 else {
 return - E_FATAL ;
 }
 return E_SUCCESS ;
 }
 else if ( string [ 0 ] == '\"' && string [ strlen ( string ) - 1 ] == '\"' ) {
 p = strchr ( string + 1 , '\"' ) ;
 * p = '\0' ;
