static int read_odml_index ( AVFormatContext * s , int frame_num ) {
 AVIContext * avi = s -> priv_data ;
 AVIOContext * pb = s -> pb ;
 int longs_per_entry = avio_rl16 ( pb ) ;
 int index_sub_type = avio_r8 ( pb ) ;
 int index_type = avio_r8 ( pb ) ;
 int entries_in_use = avio_rl32 ( pb ) ;
 int chunk_id = avio_rl32 ( pb ) ;
 int64_t base = avio_rl64 ( pb ) ;
 int stream_id = ( ( chunk_id & 0xFF ) - '0' ) * 10 + ( ( chunk_id >> 8 & 0xFF ) - '0' ) ;
 AVStream * st ;
 AVIStream * ast ;
 int i ;
 int64_t last_pos = - 1 ;
 int64_t filesize = avi -> fsize ;
 av_log ( s , AV_LOG_TRACE , "longs_per_entry:%d index_type:%d entries_in_use:%d " "chunk_id:%X base:%16" PRIX64 " frame_num:%d\n" , longs_per_entry , index_type , entries_in_use , chunk_id , base , frame_num ) ;
 if ( stream_id >= s -> nb_streams || stream_id < 0 ) return AVERROR_INVALIDDATA ;
 st = s -> streams [ stream_id ] ;
 ast = st -> priv_data ;
 if ( index_sub_type ) return AVERROR_INVALIDDATA ;
 avio_rl32 ( pb ) ;
 if ( index_type && longs_per_entry != 2 ) return AVERROR_INVALIDDATA ;
 if ( index_type > 1 ) return AVERROR_INVALIDDATA ;
 if ( filesize > 0 && base >= filesize ) {
 av_log ( s , AV_LOG_ERROR , "ODML index invalid\n" ) ;
 if ( base >> 32 == ( base & 0xFFFFFFFF ) && ( base & 0xFFFFFFFF ) < filesize && filesize <= 0xFFFFFFFF ) base &= 0xFFFFFFFF ;
 else return AVERROR_INVALIDDATA ;
 }
 for ( i = 0 ;
 i < entries_in_use ;
 i ++ ) {
 if ( index_type ) {
 int64_t pos = avio_rl32 ( pb ) + base - 8 ;
 int len = avio_rl32 ( pb ) ;
 int key = len >= 0 ;
 len &= 0x7FFFFFFF ;
 av_log ( s , AV_LOG_TRACE , "pos:%" PRId64 ", len:%X\n" , pos , len ) ;
 if ( avio_feof ( pb ) ) return AVERROR_INVALIDDATA ;
 if ( last_pos == pos || pos == base - 8 ) avi -> non_interleaved = 1 ;
 if ( last_pos != pos && len ) av_add_index_entry ( st , pos , ast -> cum_len , len , 0 , key ? AVINDEX_KEYFRAME : 0 ) ;
 ast -> cum_len += get_duration ( ast , len ) ;
 last_pos = pos ;
 }
 else {
 int64_t offset , pos ;
 int duration ;
 offset = avio_rl64 ( pb ) ;
 avio_rl32 ( pb ) ;
 duration = avio_rl32 ( pb ) ;
 if ( avio_feof ( pb ) ) return AVERROR_INVALIDDATA ;
 pos = avio_tell ( pb ) ;
 if ( avi -> odml_depth > MAX_ODML_DEPTH ) {
 av_log ( s , AV_LOG_ERROR , "Too deeply nested ODML indexes\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 if ( avio_seek ( pb , offset + 8 , SEEK_SET ) < 0 ) return - 1 ;
 avi -> odml_depth ++ ;
 read_odml_index ( s , frame_num ) ;
 avi -> odml_depth -- ;
 frame_num += duration ;
 if ( avio_seek ( pb , pos , SEEK_SET ) < 0 ) {
 av_log ( s , AV_LOG_ERROR , "Failed to restore position after reading index\n" ) ;
 return - 1 ;
 }
 }
 }
 avi -> index_loaded = 2 ;
 return 0 ;
 }

static void nice_time ( double sec , char * buff , bool part_second ) {
 ulong tmp ;
 if ( sec >= 3600.0 * 24 ) {
 tmp = ( ulong ) floor ( sec / ( 3600.0 * 24 ) ) ;
 sec -= 3600.0 * 24 * tmp ;
 buff = int10_to_str ( ( long ) tmp , buff , 10 ) ;
 buff = strmov ( buff , tmp > 1 ? " days " : " day " ) ;
 }
 if ( sec >= 3600.0 ) {
 tmp = ( ulong ) floor ( sec / 3600.0 ) ;
 sec -= 3600.0 * tmp ;
 buff = int10_to_str ( ( long ) tmp , buff , 10 ) ;
 buff = strmov ( buff , tmp > 1 ? " hours " : " hour " ) ;
 }
 if ( sec >= 60.0 ) {
 tmp = ( ulong ) floor ( sec / 60.0 ) ;
 sec -= 60.0 * tmp ;
 buff = int10_to_str ( ( long ) tmp , buff , 10 ) ;
 buff = strmov ( buff , " min " ) ;
 }
 if ( part_second ) sprintf ( buff , "%.2f sec" , sec ) ;
 else sprintf ( buff , "%d sec" , ( int ) sec ) ;
 }

