 m = mbtab [ * p ] ;
 n += m ;
 p += m ;
 len ++ ;
 }
 ;
 }
 }
 else {
 mbfl_convert_filter * filter = mbfl_convert_filter_new ( string -> no_encoding , mbfl_no_encoding_wchar , filter_count_output , 0 , & len ) ;
 if ( filter == NULL ) {
 return - 1 ;
 }
 n = string -> len ;
 p = string -> val ;
