 }
 r = * buf ++ ;
 buf ++ ;
 g = * buf ++ ;
 buf ++ ;
 b = * buf ++ ;
 buf ++ ;
 pal [ idx ] = ( r << 16 ) | ( g << 8 ) | b ;
 }
 p -> palette_has_changed = 1 ;
