 out += code + 1 ;
 buf += code + 1 ;
 left -= 2 + code ;
 tsize += code + 1 ;
 }
 }
 buf = next ;
 outdata += a -> pic . linesize [ 0 ] ;
 }
 * got_frame = 1 ;
 * ( AVFrame * ) data = a -> pic ;
 return buf_size ;
 }

