 cpu_fprintf ( f , "TB avg host size %td bytes (expansion ratio: %0.1f)\n" , tcg_ctx . tb_ctx . nb_tbs ? ( tcg_ctx . code_gen_ptr - tcg_ctx . code_gen_buffer ) / tcg_ctx . tb_ctx . nb_tbs : 0 , target_code_size ? ( double ) ( tcg_ctx . code_gen_ptr - tcg_ctx . code_gen_buffer ) / target_code_size : 0 ) ;
 cpu_fprintf ( f , "cross page TB count %d (%d%%)\n" , cross_page , tcg_ctx . tb_ctx . nb_tbs ? ( cross_page * 100 ) / tcg_ctx . tb_ctx . nb_tbs : 0 ) ;
 cpu_fprintf ( f , "direct jump count %d (%d%%) (2 jumps=%d %d%%)\n" , direct_jmp_count , tcg_ctx . tb_ctx . nb_tbs ? ( direct_jmp_count * 100 ) / tcg_ctx . tb_ctx . nb_tbs : 0 , direct_jmp2_count , tcg_ctx . tb_ctx . nb_tbs ? ( direct_jmp2_count * 100 ) / tcg_ctx . tb_ctx . nb_tbs : 0 ) ;
 cpu_fprintf ( f , "\nStatistics:\n" ) ;
 cpu_fprintf ( f , "TB flush count %d\n" , tcg_ctx . tb_ctx . tb_flush_count ) ;
 cpu_fprintf ( f , "TB invalidate count %d\n" , tcg_ctx . tb_ctx . tb_phys_invalidate_count ) ;
