inline static void _slurm_rpc_dump_stats ( slurm_msg_t * msg ) {
 char * dump ;
 int dump_size ;
 stats_info_request_msg_t * request_msg ;
 slurm_msg_t response_msg ;
 uid_t uid = g_slurm_auth_get_uid ( msg -> auth_cred , slurmctld_config . auth_info ) ;
