 }
 intern -> u . dir . index = 0 ;
 if ( EG ( exception ) || intern -> u . dir . dirp == NULL ) {
 intern -> u . dir . entry . d_name [ 0 ] = '\0' ;
 if ( ! EG ( exception ) ) {
 zend_throw_exception_ex ( spl_ce_UnexpectedValueException , 0 TSRMLS_CC , "Failed to open directory \"%s\"" , path ) ;
