 codebook [ i ] . u = 128 + * data ++ ;
 codebook [ i ] . v = 128 + * data ++ ;
 }
 else {
 codebook [ i ] . y0 = * data ++ ;
 codebook [ i ] . y1 = * data ++ ;
 codebook [ i ] . y2 = * data ++ ;
 codebook [ i ] . y3 = * data ++ ;
