 for ( i = 4 ;
 i < 6 ;
 i ++ ) idct ( block [ i ] ) ;
 }
 for ( y = 0 ;
 y < 8 ;
 y ++ ) {
 for ( x = 0 ;
 x < 8 ;
 x ++ ) {
 int16_t * temp = block [ ( x >> 2 ) + 2 * ( y >> 2 ) ] + 2 * ( x & 3 ) + 2 * 8 * ( y & 3 ) ;
