 dst [ 0 ] = ( ( y + cb ) >> 3 ) + ( ( ( y - cg ) & 0xFC ) << 3 ) + ( ( ( y + cr ) & 0xF8 ) << 8 ) ;
 y = temp [ 1 ] ;
 dst [ 1 ] = ( ( y + cb ) >> 3 ) + ( ( ( y - cg ) & 0xFC ) << 3 ) + ( ( ( y + cr ) & 0xF8 ) << 8 ) ;
 y = temp [ 8 ] ;
 dst [ stride ] = ( ( y + cb ) >> 3 ) + ( ( ( y - cg ) & 0xFC ) << 3 ) + ( ( ( y + cr ) & 0xF8 ) << 8 ) ;
 y = temp [ 9 ] ;
 dst [ 1 + stride ] = ( ( y + cb ) >> 3 ) + ( ( ( y - cg ) & 0xFC ) << 3 ) + ( ( ( y + cr ) & 0xF8 ) << 8 ) ;
 dst += 2 ;
