 if ( ( uri -> scheme == NULL ) || ( xmlStrEqual ( BAD_CAST uri -> scheme , BAD_CAST "file" ) ) ) {
 check = xsltGetSecurityPrefs ( sec , XSLT_SECPREF_READ_FILE ) ;
 if ( check != NULL ) {
 ret = check ( sec , ctxt , uri -> path ) ;
