 xsltTransformError ( ctxt , NULL , NULL , "Local file read for %s refused\n" , URL ) ;
 xmlFreeURI ( uri ) ;
 return ( 0 ) ;
 }
 }
 }
 else {
 check = xsltGetSecurityPrefs ( sec , XSLT_SECPREF_READ_NETWORK ) ;
