 * target ++ = c ;
 source ++ ;
 continue ;
 }
 len = PQmblen ( source , encoding ) ;
 for ( i = 0 ;
 i < len ;
 i ++ ) {
 if ( * source == '\0' ) break ;
 * target ++ = * source ++ ;
