 pd1 = pd & 0x000F ;
 pd2 = ( ( pd >> 4 ) & 0x000F ) ^ pd1 ;
 tmp ^= ( pd1 << 3 ) | ( pd1 << 8 ) ;
 tmp ^= pd2 | ( pd2 << 7 ) | ( pd2 << 12 ) ;
 return tmp ;
 }

