void vp9_xform_quant ( MACROBLOCK * x , int plane , int block , BLOCK_SIZE plane_bsize , TX_SIZE tx_size ) {
 MACROBLOCKD * const xd = & x -> e_mbd ;
 const struct macroblock_plane * const p = & x -> plane [ plane ] ;
 const struct macroblockd_plane * const pd = & xd -> plane [ plane ] ;
 const scan_order * const scan_order = & vp9_default_scan_orders [ tx_size ] ;
 int16_t * const coeff = BLOCK_OFFSET ( p -> coeff , block ) ;
 int16_t * const qcoeff = BLOCK_OFFSET ( p -> qcoeff , block ) ;
 int16_t * const dqcoeff = BLOCK_OFFSET ( pd -> dqcoeff , block ) ;
 uint16_t * const eob = & p -> eobs [ block ] ;
 const int diff_stride = 4 * num_4x4_blocks_wide_lookup [ plane_bsize ] ;
 int i , j ;
 const int16_t * src_diff ;
 txfrm_block_to_raster_xy ( plane_bsize , tx_size , block , & i , & j ) ;
 src_diff = & p -> src_diff [ 4 * ( j * diff_stride + i ) ] ;
 switch ( tx_size ) {
 case TX_32X32 : fdct32x32 ( x -> use_lp32x32fdct , src_diff , coeff , diff_stride ) ;
 vp9_quantize_b_32x32 ( coeff , 1024 , x -> skip_block , p -> zbin , p -> round , p -> quant , p -> quant_shift , qcoeff , dqcoeff , pd -> dequant , p -> zbin_extra , eob , scan_order -> scan , scan_order -> iscan ) ;
 break ;
 case TX_16X16 : vp9_fdct16x16 ( src_diff , coeff , diff_stride ) ;
 vp9_quantize_b ( coeff , 256 , x -> skip_block , p -> zbin , p -> round , p -> quant , p -> quant_shift , qcoeff , dqcoeff , pd -> dequant , p -> zbin_extra , eob , scan_order -> scan , scan_order -> iscan ) ;
 break ;
 case TX_8X8 : vp9_fdct8x8 ( src_diff , coeff , diff_stride ) ;
 vp9_quantize_b ( coeff , 64 , x -> skip_block , p -> zbin , p -> round , p -> quant , p -> quant_shift , qcoeff , dqcoeff , pd -> dequant , p -> zbin_extra , eob , scan_order -> scan , scan_order -> iscan ) ;
 break ;
 case TX_4X4 : x -> fwd_txm4x4 ( src_diff , coeff , diff_stride ) ;
 vp9_quantize_b ( coeff , 16 , x -> skip_block , p -> zbin , p -> round , p -> quant , p -> quant_shift , qcoeff , dqcoeff , pd -> dequant , p -> zbin_extra , eob , scan_order -> scan , scan_order -> iscan ) ;
 break ;
 default : assert ( 0 ) ;
 break ;
 }
 }

static int decode_frame ( AVCodecContext * avctx , void * data , int * got_frame , AVPacket * avpkt ) {
 AnmContext * s = avctx -> priv_data ;
 const int buf_size = avpkt -> size ;
 uint8_t * dst , * dst_end ;
 int count , ret ;
 if ( ( ret = avctx -> reget_buffer ( avctx , & s -> frame ) ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "get_buffer() failed\n" ) ;
 return ret ;
 }
 dst = s -> frame . data [ 0 ] ;
 dst_end = s -> frame . data [ 0 ] + s -> frame . linesize [ 0 ] * avctx -> height ;
 bytestream2_init ( & s -> gb , avpkt -> data , buf_size ) ;
 if ( bytestream2_get_byte ( & s -> gb ) != 0x42 ) {
 av_log_ask_for_sample ( avctx , "unknown record type\n" ) ;
 return buf_size ;
 }
 if ( bytestream2_get_byte ( & s -> gb ) ) {
 av_log_ask_for_sample ( avctx , "padding bytes not supported\n" ) ;
 return buf_size ;
 }
 bytestream2_skip ( & s -> gb , 2 ) ;
 s -> x = 0 ;
 do {
 # define OP ( gb , pixel , count ) op ( & dst , dst_end , ( gb ) , ( pixel ) , ( count ) , & s -> x , avctx -> width , s -> frame . linesize [ 0 ] ) int type = bytestream2_get_byte ( & s -> gb ) ;
 count = type & 0x7F ;
 type >>= 7 ;
 if ( count ) {
 if ( OP ( type ? NULL : & s -> gb , - 1 , count ) ) break ;
 }
 else if ( ! type ) {
 int pixel ;
 count = bytestream2_get_byte ( & s -> gb ) ;
 pixel = bytestream2_get_byte ( & s -> gb ) ;
 if ( OP ( NULL , pixel , count ) ) break ;
 }
 else {
 int pixel ;
 type = bytestream2_get_le16 ( & s -> gb ) ;
 count = type & 0x3FFF ;
 type >>= 14 ;
 if ( ! count ) {
 if ( type == 0 ) break ;
 if ( type == 2 ) {
 av_log_ask_for_sample ( avctx , "unknown opcode" ) ;
 return AVERROR_PATCHWELCOME ;
 }
 continue ;
 }
 pixel = type == 3 ? bytestream2_get_byte ( & s -> gb ) : - 1 ;
 if ( type == 1 ) count += 0x4000 ;
 if ( OP ( type == 2 ? & s -> gb : NULL , pixel , count ) ) break ;
 }
 }
 while ( bytestream2_get_bytes_left ( & s -> gb ) > 0 ) ;
 memcpy ( s -> frame . data [ 1 ] , s -> palette , AVPALETTE_SIZE ) ;
 * got_frame = 1 ;
 * ( AVFrame * ) data = s -> frame ;
 return buf_size ;
 }

static void config_access ( config_tree * ptree ) {
 static int warned_signd ;
 attr_val * my_opt ;
 restrict_node * my_node ;
 int_node * curr_flag ;
 sockaddr_u addr ;
 sockaddr_u mask ;
 struct addrinfo hints ;
 struct addrinfo * ai_list ;
 struct addrinfo * pai ;
 int rc ;
 int restrict_default ;
 u_short flags ;
 u_short mflags ;
 int range_err ;
 const char * signd_warning = # ifdef HAVE_NTP_SIGND "MS-SNTP signd operations currently block ntpd degrading service to all clients." ;
 # else "mssntp restrict bit ignored, this ntpd was configured without --enable-ntp-signd." ;
 # endif my_opt = HEAD_PFIFO ( ptree -> mru_opts ) ;
 for ( ;
 my_opt != NULL ;
 my_opt = my_opt -> link ) {
 range_err = FALSE ;
 switch ( my_opt -> attr ) {
 case T_Incalloc : if ( 0 <= my_opt -> value . i ) mru_incalloc = my_opt -> value . u ;
 else range_err = TRUE ;
 break ;
 case T_Incmem : if ( 0 <= my_opt -> value . i ) mru_incalloc = ( my_opt -> value . u * 1024 ) / sizeof ( mon_entry ) ;
 else range_err = TRUE ;
 break ;
 case T_Initalloc : if ( 0 <= my_opt -> value . i ) mru_initalloc = my_opt -> value . u ;
 else range_err = TRUE ;
 break ;
 case T_Initmem : if ( 0 <= my_opt -> value . i ) mru_initalloc = ( my_opt -> value . u * 1024 ) / sizeof ( mon_entry ) ;
 else range_err = TRUE ;
 break ;
 case T_Mindepth : if ( 0 <= my_opt -> value . i ) mru_mindepth = my_opt -> value . u ;
 else range_err = TRUE ;
 break ;
 case T_Maxage : mru_maxage = my_opt -> value . i ;
 break ;
 case T_Maxdepth : if ( 0 <= my_opt -> value . i ) mru_maxdepth = my_opt -> value . u ;
 else mru_maxdepth = UINT_MAX ;
 break ;
 case T_Maxmem : if ( 0 <= my_opt -> value . i ) mru_maxdepth = my_opt -> value . u * 1024 / sizeof ( mon_entry ) ;
 else mru_maxdepth = UINT_MAX ;
 break ;
 default : msyslog ( LOG_ERR , "Unknown mru option %s (%d)" , keyword ( my_opt -> attr ) , my_opt -> attr ) ;
 exit ( 1 ) ;
 }
 if ( range_err ) msyslog ( LOG_ERR , "mru %s %d out of range, ignored." , keyword ( my_opt -> attr ) , my_opt -> value . i ) ;
 }
 my_opt = HEAD_PFIFO ( ptree -> discard_opts ) ;
 for ( ;
 my_opt != NULL ;
 my_opt = my_opt -> link ) {
 switch ( my_opt -> attr ) {
 case T_Average : if ( 0 <= my_opt -> value . i && my_opt -> value . i <= UCHAR_MAX ) ntp_minpoll = ( u_char ) my_opt -> value . u ;
 else msyslog ( LOG_ERR , "discard average %d out of range, ignored." , my_opt -> value . i ) ;
 break ;
 case T_Minimum : ntp_minpkt = my_opt -> value . i ;
 break ;
 case T_Monitor : mon_age = my_opt -> value . i ;
 break ;
 default : msyslog ( LOG_ERR , "Unknown discard option %s (%d)" , keyword ( my_opt -> attr ) , my_opt -> attr ) ;
 exit ( 1 ) ;
 }
 }
 my_node = HEAD_PFIFO ( ptree -> restrict_opts ) ;
 for ( ;
 my_node != NULL ;
 my_node = my_node -> link ) {
 flags = 0 ;
 mflags = 0 ;
 curr_flag = HEAD_PFIFO ( my_node -> flags ) ;
 for ( ;
 curr_flag != NULL ;
 curr_flag = curr_flag -> link ) {
 switch ( curr_flag -> i ) {
 default : NTP_INSIST ( 0 ) ;
 break ;
 case T_Ntpport : mflags |= RESM_NTPONLY ;
 break ;
 case T_Source : mflags |= RESM_SOURCE ;
 break ;
 case T_Flake : flags |= RES_FLAKE ;
 break ;
 case T_Ignore : flags |= RES_IGNORE ;
 break ;
 case T_Kod : flags |= RES_KOD ;
 break ;
 case T_Mssntp : flags |= RES_MSSNTP ;
 break ;
 case T_Limited : flags |= RES_LIMITED ;
 break ;
 case T_Lowpriotrap : flags |= RES_LPTRAP ;
 break ;
 case T_Nomodify : flags |= RES_NOMODIFY ;
 break ;
 case T_Nopeer : flags |= RES_NOPEER ;
 break ;
 case T_Noquery : flags |= RES_NOQUERY ;
 break ;
 case T_Noserve : flags |= RES_DONTSERVE ;
 break ;
 case T_Notrap : flags |= RES_NOTRAP ;
 break ;
 case T_Notrust : flags |= RES_DONTTRUST ;
 break ;
 case T_Version : flags |= RES_VERSION ;
 break ;
 }
 }
 if ( ( RES_MSSNTP & flags ) && ! warned_signd ) {
 warned_signd = 1 ;
 fprintf ( stderr , "%s\n" , signd_warning ) ;
 msyslog ( LOG_WARNING , signd_warning ) ;
 }
 ZERO_SOCK ( & addr ) ;
 ai_list = NULL ;
 pai = NULL ;
 restrict_default = 0 ;
 if ( NULL == my_node -> addr ) {
 ZERO_SOCK ( & mask ) ;
 if ( ! ( RESM_SOURCE & mflags ) ) {
 restrict_default = 1 ;
 }
 else {
 DPRINTF ( 1 , ( "restrict source template mflags %x flags %x\n" , mflags , flags ) ) ;
 hack_restrict ( RESTRICT_FLAGS , NULL , NULL , mflags , flags , 0 ) ;
 continue ;
 }
 }
 else {
 AF ( & addr ) = ( u_short ) my_node -> addr -> type ;
 if ( getnetnum ( my_node -> addr -> address , & addr , 1 , t_UNK ) != 1 ) {
 ai_list = NULL ;
 memset ( & hints , 0 , sizeof ( hints ) ) ;
 hints . ai_protocol = IPPROTO_UDP ;
 hints . ai_socktype = SOCK_DGRAM ;
 hints . ai_family = my_node -> addr -> type ;
 rc = getaddrinfo ( my_node -> addr -> address , "ntp" , & hints , & ai_list ) ;
 if ( rc ) {
 msyslog ( LOG_ERR , "restrict: ignoring line %d, address/host '%s' unusable." , my_node -> line_no , my_node -> addr -> address ) ;
 continue ;
 }
 NTP_INSIST ( ai_list != NULL ) ;
 pai = ai_list ;
 NTP_INSIST ( pai -> ai_addr != NULL ) ;
 NTP_INSIST ( sizeof ( addr ) >= pai -> ai_addrlen ) ;
 memcpy ( & addr , pai -> ai_addr , pai -> ai_addrlen ) ;
 NTP_INSIST ( AF_INET == AF ( & addr ) || AF_INET6 == AF ( & addr ) ) ;
 }
 SET_HOSTMASK ( & mask , AF ( & addr ) ) ;
 if ( my_node -> mask ) {
 ZERO_SOCK ( & mask ) ;
 AF ( & mask ) = my_node -> mask -> type ;
 if ( getnetnum ( my_node -> mask -> address , & mask , 1 , t_MSK ) != 1 ) {
 msyslog ( LOG_ERR , "restrict: ignoring line %d, mask '%s' unusable." , my_node -> line_no , my_node -> mask -> address ) ;
 continue ;
 }
 }
 }
 if ( restrict_default ) {
 AF ( & addr ) = AF_INET ;
 AF ( & mask ) = AF_INET ;
 hack_restrict ( RESTRICT_FLAGS , & addr , & mask , mflags , flags , 0 ) ;
 AF ( & addr ) = AF_INET6 ;
 AF ( & mask ) = AF_INET6 ;
 }
 do {
 hack_restrict ( RESTRICT_FLAGS , & addr , & mask , mflags , flags , 0 ) ;
 if ( pai != NULL && NULL != ( pai = pai -> ai_next ) ) {
 NTP_INSIST ( pai -> ai_addr != NULL ) ;
 NTP_INSIST ( sizeof ( addr ) >= pai -> ai_addrlen ) ;
 ZERO_SOCK ( & addr ) ;
 memcpy ( & addr , pai -> ai_addr , pai -> ai_addrlen ) ;
 NTP_INSIST ( AF_INET == AF ( & addr ) || AF_INET6 == AF ( & addr ) ) ;
 SET_HOSTMASK ( & mask , AF ( & addr ) ) ;
 }
 }
 while ( pai != NULL ) ;
 if ( ai_list != NULL ) freeaddrinfo ( ai_list ) ;
 }
 }

static void gic_dist_writel ( void * opaque , hwaddr offset , uint32_t value ) {
 GICState * s = ( GICState * ) opaque ;
 if ( offset == 0xf00 ) {
 int cpu ;
 int irq ;
 int mask ;
 cpu = gic_get_current_cpu ( s ) ;
 irq = value & 0x3ff ;
 switch ( ( value >> 24 ) & 3 ) {
 case 0 : mask = ( value >> 16 ) & ALL_CPU_MASK ;
 break ;
 case 1 : mask = ALL_CPU_MASK ^ ( 1 << cpu ) ;
 break ;
 case 2 : mask = 1 << cpu ;
 break ;
 default : DPRINTF ( "Bad Soft Int target filter\n" ) ;
 mask = ALL_CPU_MASK ;
 break ;
 }
 GIC_SET_PENDING ( irq , mask ) ;
 gic_update ( s ) ;
 return ;
 }
 gic_dist_writew ( opaque , offset , value & 0xffff ) ;
 gic_dist_writew ( opaque , offset + 2 , value >> 16 ) ;
 }

