 lit_codes += 257 ;
 READ_BITS ( dist_codes , 5 ) ;
 dist_codes += 1 ;
 READ_BITS ( bitlen_codes , 4 ) ;
 bitlen_codes += 4 ;
 if ( lit_codes > MSZIP_LITERAL_MAXSYMBOLS ) return INF_ERR_SYMLENS ;
