 i < ( lit_codes + dist_codes ) ;
 i ++ ) {
 ENSURE_BITS ( 7 ) ;
 code = bl_table [ PEEK_BITS ( 7 ) ] ;
 REMOVE_BITS ( bl_len [ code ] ) ;
