 if ( ! skip_block ) {
 for ( i = 0 ;
 i < n_coeffs ;
 i ++ ) {
 const int rc = scan [ i ] ;
 const int coeff = coeff_ptr [ rc ] ;
 if ( coeff >= zbins [ rc != 0 ] || coeff <= nzbins [ rc != 0 ] ) idx_arr [ idx ++ ] = i ;
 }
 for ( i = 0 ;
 i < idx ;
 i ++ ) {
 const int rc = scan [ idx_arr [ i ] ] ;
 const int coeff = coeff_ptr [ rc ] ;
 const int coeff_sign = ( coeff >> 31 ) ;
 int tmp ;
 int abs_coeff = ( coeff ^ coeff_sign ) - coeff_sign ;
